// Generated content localization — English keys are stable lookup ids.
const dict: Record<string, string> = {
  "p.0": "Ama sa Langit, iniaalay ko ang araw na ito sa Iyong mga kamay bago ko ito ilagay sa inaasahan ng sinuman. Ayusin ang aking mga iniisip, patatagin ang aking mga damdamin, at akayin ako patungo sa kung ano ang mabuti. Hayaan ang aking unang tugon ay pananampalataya sa halip na takot. Pinagkakatiwalaan kita sa kung ano ang naiintindihan ko at kung ano ang hindi ko. Amen.",
  "p.1": "Panginoong Hesus, ang isip ko ay puno ng mga alalahanin na hindi ko kayang lutasin nang mag-isa. Patahimikin ang ingay sa loob ko at ipaalala sa akin na ang presensya mo ay mas malakas kaysa sa anumang kaba. Turuan mo ang puso kong huminga sa iyong kapayapaan. Hulmahin Mo ang puso ko hanggang maging tulad ito ng puso ni Kristo. Amen.",
  "p.2": "Banal na Espiritu, ang daan sa harap ko ay mas mabigat kaysa sa inaasahan ko. Bigyan mo ako ng pagtitiis para sa susunod na tapat na hakbang at lakas ng loob para sa susunod na hakbang. Palakasin mo ako nang hindi ako pinapahirapan. Angkla ako sa Banal na Kasulatan, palibutan ako ng awa, at punuin ako ng pag-asa. Amen.",
  "p.3": "Mapagmahal na Diyos, dinadala ko sa Iyo ang sakit na paulit-ulit kong inuulit sa lihim. Palayain mo ako sa kapaitan at turuan akong magpatawad nang may karunungan, katotohanan, at biyaya. Pagalingin kung anong kapatawaran ang hindi agad nabubura. Nawa'y ang Iyong kalooban ay maging aking kapayapaan at ang Iyong presensya ay maging aking lakas. Amen.",
  "p.4": "Maawaing Ama, itinataas ko ang aking pamilya at ang mga taong pinakamalapit sa aking puso sa Iyo. Takpan ang aming tahanan ng pasensya, katapatan, proteksyon, at pagmamahal. Gawing banayad ang aming mga salita at ang aming mga ugnayan ay nababanat. Panatilihin akong malapit upang marinig ang Iyong bulong at sapat na lakas ng loob na sundin ito. Amen.",
  "p.5": "Tapat na Panginoon, iniaalay ko sa Iyo ang gawa ng aking mga kamay at ang presyon sa aking mga balikat. Tulungan akong maglingkod nang may kahusayan nang hindi sumasamba sa tagumpay. Hayaang mas mahalaga sa akin ang integridad kaysa sa palakpakan. Gawin mo akong isang pagpapala sa isang taong nangangailangan ng Iyong kabaitan ngayon. Amen.",
  "p.6": "Mapagmahal na Tagapagligtas, dinadala ko sa Iyo ang mga lugar sa aking katawan, isip, at kaluluwa na nangangailangan ng pagpapanumbalik. Hipuin ang nasugatan, palakasin ang mahina, at gabayan ang bawat tagapag-alaga nang may karunungan. Gumawa ng pag-asa na tumaas bago pa man makita ang sagot. Gawin mo sa akin ang hindi ko magawa sa sarili ko. Amen.",
  "p.7": "Makapangyarihang Diyos, higit pa sa impormasyon ang kailangan ko — kailangan ko ng banal na karunungan. Ipakita sa akin kung ano ang pipiliin, kung ano ang tatanggihan, at kung kailan maghihintay. Ilayo mo ako sa mga desisyong ginawa lamang mula sa takot o pagmamataas. Hayaan ang aking buhay ngayon na maging isang tahimik na handog ng pagsamba. Amen.",
  "p.8": "Prinsipe ng Kapayapaan, huminto ako upang mapansin ang mga awa na madalas kong dinadaanan. Buksan ang aking mga mata sa mga regalong nakatago sa mga ordinaryong sandali. Gawing ugali ang pagpapasalamat, hindi isang mood. Hayaan ang Iyong biyaya na sumalubong sa akin sa bawat kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.9": "Ama ng Awa, hinihiling ko ang Iyong pagtakip sa aking buhay at sa bawat hakbang na aking gagawin ngayon. Ingatan mo ako mula sa nakikitang panganib at nakatagong mga bitag. Ipadala mo sa akin kung saan ako dapat pumunta at pigilan ako sa hindi dapat. Turuan mo akong lumakad nang mabagal, magmahal ng malalim, at magtiwala nang lubusan. Amen.",
  "p.10": "Ama sa Langit, patuloy na sinusubukan ng mundo na pangalanan ako sa pamamagitan ng aking mga pagkabigo, pagganap, o sakit. Ipaalala sa akin na ako ay iyo, tinubos ng biyaya at pinanghawakan sa pag-ibig. Hayaang maging mas malakas ang iyong katotohanan kaysa sa bawat maling label. Pinagkakatiwalaan kita sa kung ano ang naiintindihan ko at kung ano ang hindi ko. Amen.",
  "p.11": "Panginoong Hesus, may kalungkutan sa akin na hindi lubusang dalhin ng mga salita. Umupo sa tabi ko sa sakit at aliwin ako nang hindi minamadali ang aking paggaling. Turuan mo akong alalahanin nang may pagmamahal at mamuhay pa rin nang may pag-asa. Hulmahin Mo ang puso ko hanggang maging tulad ito ng puso ni Kristo. Amen.",
  "p.12": "Banal na Espiritu, ramdam ko po ang hila ng mga bagay na nagpapahina sa aking kaluluwa. Bigyan Mo po ako ng pusong dalisay, ng malinaw na daan palabas sa tukso, at ng lakas na piliin ang buhay. Tulungan Mo po akong maniwala na posibleng sumunod sa Iyo sa mismong sandaling ito. Iangkla Mo po ako sa Iyong Salita, balutin ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.13": "Mapagmahal na Diyos, napapagod na po akong maghintay at natutuksong pilitin ang mga bagay na hindi pa panahon. Turuan Mo po akong magtiwala sa Iyong timing nang hindi nagiging matigas ang loob o nawawalan ng sigla. Palaguin Mo po ang isang tahimik na pananampalataya sa gitna ng pagkaantala. Nawa'y ang Iyong kalooban ang maging kapayapaan ko at ang Iyong presensya ang aking lakas. Amen.",
  "p.14": "Mahabaging Ama, ayaw ko pong dumaan sa buhay na ito nang tila kalahating tulog at walang patutunguhan. Ipakita Mo po sa akin ang mabubuting bagay na inihanda Mo para gawin ko ngayong araw. Hayaang ang aking maliliit na gawa ng katapatan ay magkaroon ng halaga para sa kawalang-hanggan. Manatili sana akong sapat na malapit sa Iyo para marinig ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.15": "Tapat na Panginoon, sa pagtatapos ng araw na ito, ipinauubaya ko na sa Iyo ang lahat ng hindi ko na kayang ayusin ngayong gabi. Hugasan Mo po ang aking isipan ng kapayapaan at ingatan ang aking puso habang ako ay nahihimbing. Hayaan po na ang bukas ay sumalubong sa akin nang may sariwang awa. Gamitin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.16": "Mapagmahal na Tagapagligtas, itinataas ko po sa Iyo ang aming pagmamahalan, katapatan, at bawat relasyong nangangailangan ng Iyong haplos. Ibalik Mo po ang lambing sa mga pusong naging matalas dahil sa pagod at stress. Turuan Mo po kaming makinig, magpatawad, at piliin ang isa't isa muli. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko lang. Amen.",
  "p.17": "Makapangyarihang Diyos, ipinagkakatiwala ko po sa Iyong tapat na pangangalaga ang mga bata at kabataang mahal ko. Ingatan Mo po ang kanilang mga puso, gabayan ang kanilang mga desisyon, at paligiran sila ng mga taong may tamang payo. Tulungan Mo po silang makilala Ka nang personal at malalim. Hayaang ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba. Amen.",
  "p.18": "Prinsipe ng Kapayapaan, pagpalain Mo po ang Iyong bayan at panibaguhin ang aming pagmamahal sa isa't isa. Gawin Mo po kaming mapagpakumbaba, mapagbigay, tapat, at matapang. Nawa'y maging salamin ang aming buhay ng kagandahan ni Hesus sa harap ng mundong nakamasid. Hayaang ang Iyong biyaya ang sumalubong sa akin sa bawat kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.19": "Ama ng Awa, tila napakalayo pa ng ilang pangako at tila pagod na ang ilang mga pangarap. Hipan Mo po ng bagong pag-asa ang mga bahagi ng aking puso kung saan nanahan ang pagkabigo. Tulungan Mo po akong maniwala na nagsusulat Ka pa rin ng magagandang kabanata sa aking buhay. Turuan Mo po akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.20": "Ama sa Langit, lumalapit po ako nang may katapatan sa Iyo ngayon: inilalagay ko ang araw na ito sa Iyong mga kamay bago pa man ako magpadala sa inaasahan ng ibang tao. Pakiayos po ang aking mga iniisip, pakalmahin ang aking damdamin, at akayin ako sa kung ano ang mabuti. Hayaang ang panalanging ito ay maging higit pa sa salita; nawa'y pananampalataya ang maging unang tugon ko sa halip na takot. Hayaang ang aking buhay ngayong araw ay maging isang tahimik na alay ng pagsamba. Amen.",
  "p.21": "Panginoong Hesus, lumalapit po ako nang may katapatan sa Iyo ngayon: punung-puno ang isip ko ng mga alalahaning hindi ko kayang lutasin mag-isa. Pakiusap po, patahimikin Mo ang ingay sa loob ko at ipaalala sa akin na ang Iyong presensya ay mas malakas kaysa sa anumang takot. Hayaang ang panalanging ito ay maging higit pa sa salita; turuan Mo ang aking puso na huminga sa loob ng Iyong kapayapaan. Hayaang ang Iyong biyaya ang sumalubong sa akin sa bawat kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.22": "Banal na Espiritu, lumalapit po ako nang may katapatan sa Iyo ngayon: tila mas mabigat ang daang tinatahak ko kaysa sa aking inaasahan. Bigyan Mo po ako ng lakas para sa susunod na hakbang at katapangan para sa mga susunod pa roon. Hayaang ang panalanging ito ay maging higit pa sa salita; patatagin Mo po ako nang hindi tumitigas ang aking puso. Turuan Mo po akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.23": "Mapagpalang Diyos, lumalapit po ako nang may katapatan sa Iyo ngayon: iniaalay ko sa Iyo ang sakit na pilit kong inuulit-ulit sa aking isipan. Palayain Mo po ako sa pait ng kalooban at turuan akong magpatawad nang may karunungan, katotohanan, at biyaya. Hayaang ang panalanging ito ay maging higit pa sa salita; pagalingin Mo po ang mga sugat na hindi agad nabubura ng pagpapatawad. Nagtitiwala po ako sa Iyo, sa mga bagay na nauunawaan ko man o hindi. Amen.",
  "p.24": "Mahabaging Ama, lumalapit po ako nang tapat sa Iyong harapan ngayon: Itinataas ko po sa Iyo ang aking pamilya at ang mga taong pinakamalapit sa aking puso. Balutin Mo po ang aming tahanan ng pasensya, katapatan, proteksyon, at pagmamahal. Hayaang ang panalanging ito ay maging higit pa sa mga salita; gawin Mo pong malumanay ang aming pananalita at matatag ang aming ugnayan. Hubugin Mo po ang aking puso hanggang sa sumalamin dito ang puso ni Kristo. Amen.",
  "p.25": "Tapat na Panginoon, lumalapit po ako nang tapat sa Iyong harapan ngayon: Iniaalay ko po sa Iyo ang gawa ng aking mga kamay at ang bigat na pasan ng aking mga balikat. Tulungan Mo po akong maglingkod nang may kahusayan nang hindi sinasamba ang tagumpay. Hayaang ang panalanging ito ay maging higit pa sa mga salita; mas maging mahalaga sana sa akin ang integridad kaysa sa palakpak ng iba. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.26": "Mapagmahal na Tagapagligtas, lumalapit po ako nang tapat sa Iyong harapan ngayon: Dinadala ko po sa Iyo ang bawat bahagi ng aking katawan, isip, at kaluluwa na nangangailangan ng paghilom. Hipuin Mo po ang mga sugat, palakasin ang mahihina, at gabayan Mo po ng karunungan ang lahat ng nag-aalaga sa akin. Hayaang ang panalanging ito ay maging higit pa sa mga salita; nawa’y umusbong ang pag-asa bago pa man makita ang kasagutan. Ang Iyo sanang kalooban ang maging kapayapaan ko at ang Iyong presensya ang aking lakas. Amen.",
  "p.27": "Makapangyarihang Diyos, lumalapit po ako nang tapat sa Iyong harapan ngayon: Higit pa sa kaalaman, kailangan ko po ng banal na karunungan. Ipakita Mo po sa akin kung ano ang pipiliin, kung ano ang tatanggihan, at kung kailan dapat maghintay. Hayaang ang panalanging ito ay maging higit pa sa mga salita; ilayo Mo po ako sa mga desisyong udyok lamang ng takot o pride. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.28": "Prinsipe ng Kapayapaan, lumalapit po ako nang tapat sa Iyong harapan ngayon: Tumitigil po ako upang mapansin ang Iyong mga biyaya na madalas kong malampasan sa pagmamadali. Buksan Mo po ang aking mga mata sa mga regalong nakatago sa mga ordinaryong sandali. Hayaang ang panalanging ito ay maging higit pa sa mga salita; gawin Mo pong habit ang pagpapasalamat, at hindi lamang base sa nararamdaman. Gamitin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.29": "Ama ng Awa, lumalapit po ako nang tapat sa Iyong harapan ngayon: Hinihiling ko po ang Iyong pagkalinga sa aking buhay at sa bawat hakbang na gagawin ko ngayong araw. Bantayan Mo po ako laban sa mga panganib na nakikita at sa mga bitag na nakatago. Hayaang ang panalanging ito ay maging higit pa sa mga salita; dalhin Mo po ako kung saan ako dapat pumunta at pigilan Mo po ako kung saan hindi nararapat. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.30": "Ama sa Langit, lumalapit po ako nang tapat sa Iyong harapan ngayon: Pilit po akong binabansagan ng mundo base sa aking mga pagkakamali, performance, o sakit. Ipaalala Mo po sa akin na ako ay sa Iyo, tinubos ng biyaya at yakap ng Iyong pag-ibig. Hayaang ang panalanging ito ay maging higit pa sa mga salita; nawa’y mas mangibabaw ang Iyong katotohanan kaysa sa anumang maling label sa akin. Maging isang tahimik na handog ng pagsamba ang buhay ko ngayong araw. Amen.",
  "p.31": "Panginoong Hesus, lumalapit po ako nang tapat sa Iyong harapan ngayon: May lungkot sa loob ko na hindi kayang ipaliwanag ng mga salita. Samahan Mo po ako sa gitna ng sakit at alwin Mo po ako nang hindi minamadali ang aking paghilom. Hayaang ang panalanging ito ay maging higit pa sa mga salita; turuan Mo po akong makaalala nang may pagmamahal habang patuloy na namumuhay nang may pag-asa. Tagpuin nawa ako ng Iyong biyaya sa bawat kahinaan at akayin ako tungo sa kapayapaan. Amen.",
  "p.32": "Banal na Espiritu, lumalakit po ako nang tapat sa Iyong harapan ngayon: Ramdam ko po ang hila ng mga bagay na nagpapahina sa aking kaluluwa. Bigyan Mo po ako ng malinis na puso, ng malinaw na matatakasan, at ng lakas na piliin ang buhay. Hayaang ang panalanging ito ay maging higit pa sa mga salita; tulungan Mo po akong makasunod sa Iyo sa mismong sandaling ito. Turuan Mo po akong lumakad nang may hinahon, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.33": "Mapagpalang Diyos, lumalapit po ako nang tapat sa Iyong harapan ngayon: Pagod na po akong maghintay at natutuksong pilitin ang mga bagay na hindi pa panahon. Turuan Mo po akong magtiwala sa Iyong timing nang hindi nagiging tamad o mapait. Hayaang ang panalanging ito ay maging higit pa sa mga salita; patubuin Mo po ang isang tahimik na pananampalataya sa gitna ng paghihintay. Ipinagkakatiwala ko po sa Iyo ang mga bagay na nauunawaan ko at ang mga hindi ko maintindihan. Amen.",
  "p.34": "Mahabaging Ama, lumalapit po ako nang tapat sa Iyong harapan ngayon: Ayaw ko pong mamuhay nang walang direksyon o parang tulog ang diwa. Ipakita Mo po sa akin ang mabubuting bagay na inihanda Mo para gawin ko ngayong araw. Hayaang ang panalanging ito ay maging higit pa sa mga salita; gawin Mo pong mahalaga ang aking maliliit na gawa ng katapatan para sa kawalang-hanggan. Hubugin Mo po ang aking puso hanggang sa sumalamin dito ang puso ni Kristo. Amen.",
  "p.35": "Tapat na Panginoon, lumalapit po ako nang tapat sa Iyong harapan ngayon: Sa pagtatapos ng araw na ito, isinusuko ko po ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Hugasan Mo po ang aking isipan ng kapayapaan at ingatan Mo po ang aking puso habang ako ay natutulog. Hayaang ang panalanging ito ay maging higit pa sa mga salita; nawa’y salubungin ako ng bagong awa bukas. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.36": "Mapagmahal na Tagapagligtas, lumalapit po ako nang may katapatan sa Iyo ngayon: itinataas ko ang aming pagmamahalan, ang aming mga sumpaan, at ang bawat relasyong nangangailangan ng Iyong haplos. Ibalik Mo po ang lambing sa amin lalo na sa mga panahong dala ng stress ay nagiging matalas kami sa isa't isa. Higit pa sana sa mga salita ang dalanging ito; turuan Mo po kaming makinig, magpatawad, at muling piliin ang isa't isa araw-araw. Nawa'y ang Iyong kalooban ang maging aking kapayapaan, at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.37": "Makapangyarihang Diyos, tapat po akong lumalapit sa Iyo ngayon: ipinagkakatiwala ko po ang mga bata at kabataang mahal ko sa Iyong tapat na pag-aaruga. Protektahan Mo po ang kanilang mga puso, gabayan ang kanilang mga pinipili, at paligiran sila ng mga taong magbibigay ng matalinong payo. Nawa'y maging higit pa sa mga salita ang panalanging ito; tulungan Mo silang makilala Ikaw nang personal at malalim. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.38": "Prinsipe ng Kapayapaan, tapat po akong lumalapit sa Iyo ngayon: pagpalain Mo po ang Iyong bayan at panatilihing buhay ang aming pag-ibig sa isa't isa. Turuan Mo po kaming maging mapagpakumbaba, mapagbigay, matapat, at matapang. Huwag po sanang manatili sa salita lamang ang dalanging ito; nawa'y makita ang kagandahan ni Hesus sa aming buhay sa harap ng mundong nagmamasid. Gamitin Mo po akong pagpapala sa isang taong nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.39": "Ama ng Awa, tapat po akong lumalapit sa Iyo ngayon: may mga pangakong tila napakalayo pa at mga pangarap na tila pagod na. Buhayin Mo po ang pag-asa sa mga bahagi ng buhay ko na nababalot ng pagkabigo. Higit pa sana sa mga salita ang dalanging ito; tulungan Mo po akong maniwala na nagsusulat Ka pa rin ng magagandang kabanata sa aking buhay. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.40": "Ama sa Langit, salamat po sa pagpapadama ng Iyong presensya sa gitna ng aking totoong buhay. Ipinagkakatiwala ko po ang araw na ito sa Iyong mga kamay bago pa man ako maharap sa mga inaasahan ng ibang tao. Ayusin Mo po ang aking mga iniisip, patatagin ang aking damdamin, at akayin ako sa kung ano ang mabuti. Sa Iyong biyaya, nawa'y pananampalataya at hindi takot ang maging una kong tugon. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.41": "Panginoong Hesus, salamat po sa pagsama sa akin sa gitna ng totoong buhay, kung kailan ang isip ko ay punong-puno ng mga alalahaning hindi ko kayang lutasin nang mag-isa. Patahimikin Mo po ang ingay sa loob ko at ipaalala sa akin na ang Iyong presensya ay mas malakas kaysa sa anumang kaba. Sa Iyong biyaya, turuan Mo ang puso kong huminga sa Iyong kapayapaan. Gamitin Mo po akong pagpapala sa isang taong nangangailangan ng Iyong kabutihan ngayon. Amen.",
  "p.42": "Banal na Espiritu, salamat po sa pagsama sa akin sa gitna ng totoong buhay, kung kailan ang daang nasa harap ko ay tila mas mabigat kaysa sa inaasahan ko. Bigyan Mo po ako ng lakas para sa susunod na hakbang, at tapang para sa mga susunod pa. Sa Iyong biyaya, gawin Mo po akong matatag pero hindi matigas ang loob. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.43": "Mapagmahal na Diyos, salamat po sa pagsama sa akin sa gitna ng totoong buhay, kung kailan inilalapit ko sa Iyo ang mga sakit na paulit-ulit kong inaalala nang lihim. Palayain Mo po ako sa pait ng kalooban at turuan akong magpatawad nang may karunungan, katotohanan, at biyaya. Sa Iyong biyaya, hilumin Mo ang anumang sugat na hindi agad nabubura ng pagpapatawad. Nawa'y ang buhay ko ngayong araw ay maging isang tahimik na handog ng pagsamba sa Iyo. Amen.",
  "p.44": "Maawaing Ama, salamat po sa pagsama sa akin sa gitna ng totoong buhay. Itinataas ko po sa Iyo ang aking pamilya at ang mga taong pinakamalapit sa aking puso. Balutin Mo po ang aming tahanan ng pasensya, katapatan, proteksyon, at pagmamahal. Sa Iyong biyaya, gawin Mo pong banayad ang aming mga salita at matibay ang aming samahan. Nawa'y matagpuan ako ng Iyong biyaya sa bawat kong kahinaan at akayin ako tungo sa kapayapaan. Amen.",
  "p.45": "Tapat na Panginoon, salamat po sa pagsama sa akin sa gitna ng totoong buhay. Iniaalay ko po sa Iyo ang gawa ng aking mga kamay at ang bigat na pasan-pasan ko. Tulungan Mo po akong maglingkod nang mahusay nang hindi nahuhulog sa pagsamba sa tagumpay. Sa Iyong biyaya, mas maging mahalaga sana sa akin ang integridad kaysa sa palakpakan ng tao. Turuan Mo akong lumakad nang banayad, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.46": "Mapagmahal na Tagapagligtas, salamat po sa pagsama sa akin sa gitna ng totoong buhay. Dinadala ko po sa Iyo ang aking katawan, isip, at kaluluwa na nangangailangan ng panunumbalik. Hipuin Mo po ang mga sugat, palakasin ang mahihina, at gabayan ng karunungan ang bawat nag-aalaga sa akin. Sa Iyong biyaya, hayaang umusbong ang pag-asa bago pa man makita ang kasagutan. Ipinagkakatiwala ko sa Iyo ang mga bagay na naiintindihan ko at pati na rin ang mga hindi. Amen.",
  "p.47": "Makapangyarihang Diyos, salamat po sa pagsama sa akin sa gitna ng totoong buhay. Higit pa sa impormasyon, banal na karunungan ang kailangan ko. Ipakita Mo po sa akin kung ano ang dapat piliin, kung ano ang dapat tanggihan, at kung kailan dapat maghintay. Sa Iyong biyaya, ilayo Mo po ako sa mga desisyong udyok lamang ng takot o pride. Hubugin Mo po ang aking puso hanggang sa ito ay maging repleksyon ng puso ni Kristo. Amen.",
  "p.48": "Prinsipe ng Kapayapaan, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan humihinto ako para damhin ang mga biyayang madalas kong malagpasan sa pagmamadali. Buksan Mo po ang aking mga mata sa mga regalong nakatago sa bawat ordinaryong sandali. Sa Iyong biyaya, gawin Mo pong habit ang pagpapasalamat at hindi dahil lang sa aking nararamdaman. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.49": "Ama ng Awa, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan hinihiling ko ang Iyong pagtatakip sa aking buhay at sa bawat hakbang ko ngayong araw. Ingatan Mo po ako mula sa mga panganib na nakikita at sa mga bitag na nakatago. Sa Iyong biyaya, dalhin Mo po ako sa dapat kong puntahan at pigilan Mo ako sa hindi nararapat. Nawa ang Iyong kalooban ang maging kapayapaan ko at ang Iyong presensya ang aking lakas. Amen.",
  "p.50": "Ama sa Langit, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan pilit akong binabansagan ng mundo base sa aking mga pagkakamali, kakayahan, o pait na dinaranas. Ipaalala Mo po sa akin na ako ay Iyo, tinubos ng biyaya at yakap ng Iyong pagmamahal. Sa Iyong biyaya, hayaang mas manaig ang Iyong katotohanan kaysa sa anumang maling bansag sa akin. Manatili sana akong malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod. Amen.",
  "p.51": "Panginoong Hesus, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan may kalungkutan sa aking puso na hindi kayang ipaliwanag ng mga salita. Hiling ko po na samahan Mo ako sa hapdi at aliwin ako nang hindi minamadali ang aking paghilom. Sa Iyong biyaya, turuan Mo akong makaalala nang may pagmamahal habang patuloy na namumuhay nang may pag-asa. Gawin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayon. Amen.",
  "p.52": "Banal na Espiritu, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan nararamdaman ko ang hila ng mga bagay na nagpapahina sa aking kaluluwa. Bigyan Mo po ako ng malinis na puso, ng malinaw na matatakasan mula sa tukso, at ng lakas na piliin ang buhay. Sa Iyong biyaya, tulungan Mo akong makasunod sa Iyo sa mismong sandaling ito. Gawin Mo sa loob ko ang hindi ko kayang gawin sa sarili ko lang. Amen.",
  "p.53": "Mapagpalang Diyos, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan pagod na akong maghintay at natutuksong pilitin ang mga bagay na hindi pa handa. Turuan Mo po akong magtiwala sa Iyong takdang panahon nang hindi nawawalan ng sigla o nagtatanim ng sama ng loob. Sa Iyong biyaya, palaguin Mo ang isang tahimik na pananampalataya sa gitna ng paghihintay. Hayaang ang buhay ko ngayong araw ay maging isang payapang alay ng pagsamba. Amen.",
  "p.54": "Maawaing Ama, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, dahil ayaw ko pong dumaan lang sa mundong ito nang kalahating-gising. Ipakita Mo po sa akin ang mabubuting bagay na inihanda Mong gawin ko ngayong araw. Sa Iyong biyaya, gawing mahalaga ang aking maliliit na gawa ng katapatan para sa kawalang-hanggan. Hayaan pong ang Iyong biyaya ang sumalubong sa akin sa bawat kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.55": "Tapat na Panginoon, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay. Sa pagtatapos ng araw na ito, ipinapaubaya ko na sa Iyo ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Hugasan Mo po ng kapayapaan ang aking isipan at ingatan ang aking puso habang ako ay natutulog. Sa Iyong biyaya, nawa’y salubungin ako ng bukas nang may sariwang awa. Turuan Mo akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.56": "Mapagmahal na Tagapagligtas, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay. Itinataas ko sa Iyo ang pagmamahalan, katapatan, at bawat relasyong nangangailangan ng Iyong haplos. Ibalik Mo po ang lambing sa amin kung saan kami ay naging matalas dahil sa stress. Sa Iyong biyaya, turuan Mo kaming makinig, magpatawad, at muling piliin ang isa’t isa. Ipinagkakatiwala ko sa Iyo ang mga bagay na nauunawaan ko at pati ang mga hindi. Amen.",
  "p.57": "Makapangyarihang Diyos, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan ipinagkakatiwala ko sa Iyong tapat na kalinga ang mga bata at kabataang minamahal ko. Ingatan Mo po ang kanilang mga puso, gabayan ang kanilang mga desisyon, at palibutan sila ng mga taong magbibigay ng tamang payo. Sa Iyong biyaya, tulungan Mo silang makilala Ka nang personal at malalim. Hubugin Mo ang aking puso hanggang sa masalamin nito ang puso ni Kristo. Amen.",
  "p.58": "Prinsipe ng Kapayapaan, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay; pagpalain Mo po ang Iyong bayan at panibaguhin ang aming pagmamahal sa isa’t isa. Gawin Mo po kaming mapagpakumbaba, mapagbigay, matapat, at matapang. Sa Iyong biyaya, nawa’y ipakita ng aming mga buhay ang kagandahan ni Hesus sa mundong nagmamasid. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.59": "Ama ng Awa, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan tila napakalayo pa ng ilang mga pangako at pagod na ang aking mga pangarap. Hinihiling ko na ihipan Mo ng pag-asa ang mga bahagi ng buhay ko na nababalutan ng pagkabigo. Sa Iyong biyaya, tulungan Mo akong maniwala na patuloy Ka pang nagsusulat ng magagandang kabanata para sa akin. Nawa ang Iyong kalooban ang maging kapayapaan ko at ang Iyong presensya ang aking lakas. Amen.",
  "p.60": "Ama sa Langit, isinusuko ko sa Iyo ang pangangailangang ito: ipinagkakatiwala ko sa Iyong mga kamay ang araw na ito bago pa man ako maharap sa mga inaasahan ng ibang tao. Samahan Mo po ako habang inaayos Mo ang aking isipan, pinapanatag ang aking damdamin, at inaakay ako sa kung ano ang mabuti. Sa aking mga iniisip, desisyon, at reaksyon, nawa’y pananampalataya ang mauna sa akin sa halip na takot. Hubugin Mo po ang aking puso hanggang sa ito ay maging katulad ng puso ni Kristo. Amen.",
  "p.61": "Panginoong Hesus, isinusuko ko sa Iyo ang pangangailangang ito: punong-puno ang isip ko ng mga alalahanin na hindi ko kayang lutasin nang mag-isa. Samahan Mo po ako habang pinatatahimik Mo ang ingay sa loob ko at ipinapaalala sa akin na ang Iyong presensya ay mas malakas kaysa sa anumang takot. Sa aking mga iniisip, desisyon, at reaksyon, turuan Mo ang aking pusong huminga sa Iyong kapayapaan. Iangkla Mo po ako sa Iyong Salita, balutin ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.62": "Banal na Espiritu, isinusuko ko sa Iyo ang pangangailangang ito: tila mas mabigat ang landas sa harap ko kaysa sa aking inaasahan. Samahan Mo po ako at bigyan ng lakas para sa susunod na hakbang, at tapang para sa mga susunod pa. Sa aking mga iniisip, desisyon, at reaksyon, gawin Mo po akong matatag nang hindi nagiging matigas ang aking kalooban. Nawa’y ang Iyong kalooban ang maging aking kapayapaan at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.63": "Mapagmahal na Diyos, isinusuko ko sa Iyo ang pangangailangang ito: dinadala ko sa Iyo ang sakit na pilit kong inaalala nang palihim. Samahan Mo po ako habang pinalalaya Mo ako mula sa pait ng kalooban at tinuturuang magpatawad nang may karunungan, katotohanan, at biyaya. Sa aking mga iniisip, desisyon, at reaksyon, pagalingin Mo po ang mga bahaging hindi agad nabura ng pagpapatawad. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod sa Iyo. Amen.",
  "p.64": "Amang Mahabagin, isinusuko ko sa Iyo ang pangangailangang ito: inilalapit ko sa Iyo ang aking pamilya at ang mga taong pinakamalapit sa aking puso. Samahan Mo po kami habang binabalot Mo ang aming tahanan ng pasensya, katapatan, proteksyon, at pag-ibig. Sa aking mga iniisip, desisyon, at reaksyon, nawa’y maging malumanay ang aming mga salita at maging matibay ang aming ugnayan. Gamitin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.65": "Tapat na Panginoon, isinusuko ko sa Iyo ang pangangailangang ito: iniaalay ko sa Iyo ang gawa ng aking mga kamay at ang bigat na pasan ng aking mga balikat. Samahan Mo po ako habang tinutulungan Mo akong maglingkod nang mahusay nang hindi sinasamba ang tagumpay. Sa aking mga iniisip, desisyon, at reaksyon, nawa’y mas mahalaga sa akin ang integridad kaysa sa palakpak ng tao. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.66": "Mapagmahal na Tagapagligtas, isinusuko ko sa Iyo ang pangangailangang ito: inilalapit ko sa Iyo ang bawat bahagi ng aking katawan, isipan, at kaluluwa na nangangailangan ng paghilom. Samahan Mo po ako habang hinahawakan Mo ang bawat sugat, pinapalakas ang mahihina, at ginagabayan ng karunungan ang lahat ng nag-aalaga sa akin. Sa aking mga iniisip, desisyon, at reaksyon, nawa’y umusbong ang pag-asa bago pa man makita ang kasagutan. Hayaang ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba. Amen.",
  "p.67": "Makapangyarihang Diyos, isinusuko ko sa Iyo ang pangangailangang ito: higit pa sa impormasyon, kailangan ko ng Iyong banal na karunungan. Samahan Mo po ako habang ipinapakita Mo kung ano ang pipiliin, ano ang tatanggihan, at kung kailan dapat maghintay. Sa aking mga iniisip, desisyon, at reaksyon, ilayo Mo po ako sa mga pasyang dala lamang ng takot o pagmamataas. Nawa’y samahan ako ng Iyong biyaya sa bawat kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.68": "Prinsipe ng Kapayapaan, isinusuko ko sa Iyo ang pangangailangang ito: humihinto ako upang mapansin ang Iyong mga biyaya na madalas kong malagpasan sa pagmamadali. Samahan Mo po ako habang binubuksan Mo ang aking mga mata sa mga regalong nakatago sa mga ordinaryong sandali. Sa aking mga iniisip, desisyon, at reaksyon, gawin Mong bahagi ng aking buhay ang pasasalamat sa halip na basta nararamdaman lang. Turuan Mo po akong lumakad nang may hinahon, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.69": "Ama ng Awa, isinusuko ko sa Iyo ang pangangailangang ito: hinihiling ko ang Iyong pag-iingat sa aking buhay at sa bawat hakbang na tatahakin ko ngayong araw. Samahan Mo po ako habang binabantayan Mo ako laban sa mga panganib na nakikita at mga bitag na nakatago. Sa aking mga iniisip, desisyon, at reaksyon, dalhin Mo po ako sa kung saan ako dapat pumunta at pigilan Mo ako sa hindi nararapat. Nagtitiwala ako sa Iyo sa mga bagay na naiintindihan ko at maging sa mga bagay na hindi ko pa maunawaan. Amen.",
  "p.70": "Ama sa Langit, isinusuko ko sa Iyo ang pangangailangang ito: pilit akong binabansagan ng mundo base sa aking mga kabiguan, kakayahan, o pait na naranasan. Samahan Mo po ako habang ipinapaalala Mo na ako ay sa Iyo, tinubos ng biyaya at hawak ng Iyong pag-ibig. Sa aking mga iniisip, desisyon, at reaksyon, nawa’y mas mangibabaw ang Iyong katotohanan kaysa sa anumang maling bansag ng iba. Hubugin Mo po ang aking puso hanggang sa ito ay maging katulad ng puso ni Kristo. Amen.",
  "p.71": "Panginoong Hesus, isinusuko ko sa Iyo ang pangangailangang ito: may lungkot sa aking loob na hindi kayang ipaliwanag ng anumang salita. Samahan Mo po ako sa gitna ng hapdi at aliwin Mo ako nang hindi minamadali ang aking paghilom. Sa aking mga iniisip, desisyon, at reaksyon, turuan Mo akong makaalala nang may pagmamahal habang patuloy na namumuhay nang may pag-asa. Iangkla Mo po ako sa Iyong Salita, balutin ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.72": "Banal na Espiritu, isinusuko ko po sa Iyo ang pangangailangang ito: Ramdam ko ang hila ng mga bagay na nagpapahina sa aking kaluluwa. Samahan Mo po ako habang binibigyan Mo ako ng malinis na puso, malinaw na paraan para makaiwas sa tukso, at lakas na piliin ang buhay. Nawa’y ipakita ng aking mga iniisip, desisyon, at reaksyon na posible pa ring sumunod sa Iyo sa bawat sandali. Maging kapayapaan ko nawa ang Iyong kalooban, at maging lakas ko ang Iyong presensya. Amen.",
  "p.73": "Mapagmahal na Diyos, isinusuko ko po sa Iyo ang pangangailangang ito: Pagod na po akong maghintay at natutukso nang pilitin ang mga bagay na hindi pa panahon. Samahan Mo po ako habang tinuturuan Mo akong magtiwala sa Iyong takdang oras nang hindi nawawalan ng sigla o nagtatanim ng sama ng loob. Nawa’y ipakita ng aking mga iniisip, desisyon, at reaksyon ang isang pananampalatayang tahimik na lumalago sa gitna ng paghihintay. Panatilihin Mo po akong malapit sa Iyo upang marinig ko ang Iyong bulong at magkaroon ng tapang na sumunod dito. Amen.",
  "p.74": "Mahabaging Ama, isinusuko ko po sa Iyo ang pangangailangang ito: Ayaw ko pong lumipas ang buhay na ito nang tila wala sa sarili at walang layunin. Samahan Mo po ako habang ipinapakita Mo ang mabubuting bagay na inihanda Mo para gawin ko ngayong araw. Nawa’y ipakita ng aking mga iniisip, desisyon, at reaksyon na ang maliliit kong gawa ng katapatan ay may kabuluhang pang-walang hanggan. Gamitin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayon. Amen.",
  "p.75": "Tapat na Panginoon, isinusuko ko po sa Iyo ang pangangailangang ito: Sa pagtatapos ng araw na ito, binibitawan ko na ang mga bagay na hindi ko kayang ayusin ngayong gabi. Samahan Mo po ako; punuin Mo ang aking isipan ng Iyong kapayapaan at ingatan ang aking puso habang ako ay nahihimbing. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon na ang bukas ay sasalubungin ako ng Iyong bagong awa. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.76": "Mapagmahal na Tagapagligtas, isinusuko ko po sa Iyo ang pangangailangang ito: Itinataas ko sa Iyo ang aming pagmamahalan, katapatan, at bawat relasyong nangangailangan ng Iyong haplos. Samahan Mo po ako sa pagbabalik ng lambing sa aming ugnayan lalo na kung saan kami naging matalas dahil sa pagod. Nawa’y ipakita ng aking mga iniisip, desisyon, at reaksyon ang pusong marunong makinig, magpatawad, at muling piliin ang isa’t isa. Hayaan Mo pong ang buhay ko ngayon ay maging isang tahimik na alay ng pagsamba sa Iyo. Amen.",
  "p.77": "Makapangyarihang Diyos, isinusuko ko po sa Iyo ang pangangailangang ito: Ipinagkakatiwala ko ang mga bata at kabataang mahal ko sa Iyong tapat na pangangalaga. Samahan Mo po ako; ingatan Mo ang kanilang mga puso, gabayan ang kanilang mga pagpili, at palibutan sila ng mga taong may mabuting payo. Nawa’y ipakita ng aking mga iniisip, desisyon, at reaksyon ang tulong na kailangan nila upang makilala Ka nang personal at malalim. Samahan Mo po ako ng Iyong biyaya sa bawat kahinaan at akayin ako patungo sa kapayapaan. Amen.",
  "p.78": "Prinsipe ng Kapayapaan, isinusuko ko po sa Iyo ang pangangailangang ito: Pagpalain Mo po ang Iyong bayan at panumbalikin ang aming pagmamahal sa isa’t isa. Samahan Mo po ako habang hinuhubog Mo kaming maging mapagpakumbaba, mapagbigay, matapat, at matapang. Nawa’y ipakita ng aking mga iniisip, desisyon, at reaksyon ang kagandahan ni Hesus sa mundong nakamasid sa amin. Turuan Mo po akong lumakad nang may hinahon, magmahal nang tapat, at magtiwala nang lubos. Amen.",
  "p.79": "Ama ng Awa, isinusuko ko po sa Iyo ang pangangailangang ito: May mga pangakong tila napakalayo pa at mga pangarap na tila nakapapagod na. Samahan Mo po ako at hipan ng bagong pag-asa ang mga bahagi ng buhay ko na puno ng pagkabigo. Nawa’y ipakita ng aking mga iniisip, desisyon, at reaksyon ang pananalig na sumusulat Ka pa rin ng magagandang kabanata para sa akin. Ipinagkakatiwala ko po sa Iyo ang mga bagay na nauunawaan ko at maging ang mga hindi ko maintindihan. Amen.",
  "p.80": "Ama sa Langit, nakikita Mo po ang aking mga dinadala at alam Mo kung bakit ito mahalaga: Ipinagkakatiwala ko ang araw na ito sa Iyong mga kamay bago pa man ako malunod sa inaasahan ng ibang tao. Tinatanggap ko po ang Iyong tulong sa pag-aayos ng aking isipan, pagpapatatag ng aking emosyon, at pag-akay sa akin sa kung ano ang mabuti. Ngayon, hayaang ang una kong tugon ay pananampalataya sa halip na takot. Samahan Mo po ako ng Iyong biyaya sa bawat kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.81": "Panginoong Hesus, nakikita Mo po ang aking mga dinadala at alam Mo kung bakit ito mahalaga: Puno ang isip ko ng mga alalahanin na hindi ko kayang lutasin nang mag-isa. Tinatanggap ko po ang Iyong tulong sa pagpapatahimik ng ingay sa loob ko; paalalahanan Mo po ako na ang Iyong presensya ay mas malakas kaysa sa anumang takot. Ngayon, turuan Mo ang aking puso na huminga sa Iyong kapayapaan. Turuan Mo po akong lumakad nang may hinahon, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.82": "Banal na Espiritu, nakikita Mo po ang aking mga dinadala at alam Mo kung bakit ito mahalaga: Ang landas sa harap ko ay tila mas mabigat kaysa sa inaasahan ko. Tinatanggap ko po ang Iyong tulong na nagbibigay sa akin ng tatag para sa susunod na hakbang, at lakas ng loob para sa mga susunod pa. Ngayon, gawin Mo po akong matatag nang hindi nagiging matigas ang aking puso. Ipinagkakatiwala ko po sa Iyo ang mga bagay na nauunawaan ko at maging ang mga hindi ko maintindihan. Amen.",
  "p.83": "Mapagmahal na Diyos, nakikita Mo po ang aking mga dinadala at alam Mo kung bakit ito mahalaga: Inilalapit ko po sa Iyo ang sakit na paulit-ulit kong inaalala nang palihim. Tinatanggap ko po ang Iyong tulong upang mapalaya mula sa pait at matutong magpatawad nang may karunungan, katotohanan, at biyaya. Ngayon, pagalingin Mo po ang mga sugat na hindi agad nabubura ng pagpapatawad. Hubugin Mo ang aking puso hanggang sa maging kawangis ito ng puso ni Kristo. Amen.",
  "p.84": "Maawaing Ama, nakikita Mo ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: Iniaalay ko sa Iyo ang aking pamilya at ang mga taong pinakamalapit sa aking puso. Tinatanggap ko ang Iyong tulong habang binabalot Mo ang aming tahanan ng pagtitimpi, katapatan, proteksyon, at pag-ibig. Ngayon, gawin Mo pong malumanay ang aming mga salita at matatag ang aming samahan. Itanim Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.85": "Tapat na Panginoon, nakikita Mo ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: Iniaalay ko sa Iyo ang gawa ng aking mga kamay at ang bigat na nararamdaman ko. Tinatanggap ko ang Iyong tulong upang makapaglingkod ako nang may kahusayan nang hindi nagiging diyos ang tagumpay. Ngayon, mas maging mahalaga nawa sa akin ang integridad kaysa sa palakpak ng iba. Ang kalooban Mo po nawa ang maging kapayapaan ko, at ang Iyong presensya ang aking lakas. Amen.",
  "p.86": "Loving Savior, nakikita Mo ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: Dinadala ko sa Iyo ang aking katawan, isipan, at kaluluwa na nangangailangan ng paghilom. Tinatanggap ko ang Iyong tulong habang hinahawakan Mo ang aking mga sugat, pinalalakas ang aking kahinaan, at binibigyan ng karunungan ang bawat nag-aalaga sa akin. Ngayon, buhayin Mo po ang pag-asa sa akin bago pa man dumating ang kasagutan. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod. Amen.",
  "p.87": "Makapangyarihang Diyos, nakikita Mo ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: Higit pa sa impormasyon, banal na karunungan po ang kailangan ko. Tinatanggap ko ang Iyong tulong habang ipinapakita Mo sa akin kung ano ang dapat piliin, kung ano ang dapat tanggihan, at kung kailan dapat maghintay. Ngayon, ilayo Mo po ako sa mga desisyong dala lamang ng takot o pagmamataas. Gamitin Mo po ako bilang pagpapala sa mga taong nangangailangan ng Iyong kabutihan ngayon. Amen.",
  "p.88": "Prinsipe ng Kapayapaan, nakikita Mo ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: Humihinto ako upang pagnilayan ang Iyong mga biyaya na madalas kong makaligtaan sa pagmamadali. Tinatanggap ko ang Iyong tulong habang binubuksan Mo ang aking mga mata sa mga regalong nakatago sa mga ordinaryong sandali. Ngayon, gawin Mo pong isang habit ang pagpapasalamat, at hindi lamang base sa nararamdaman. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.89": "Ama ng Awa, nakikita Mo ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: Hinihiling ko ang Iyong pag-iingat sa aking buhay at sa bawat hakbang ko ngayong araw. Tinatanggap ko ang Iyong tulong habang binabantayan Mo ako laban sa mga panganib at mga patibong na hindi ko nakikita. Ngayon, ihatid Mo po ako sa kung saan ako dapat pumunta at pigilan Mo po ako sa hindi nararapat. Ang buhay ko nawa ngayong araw ay maging isang tahimik na handog ng pagsamba. Amen.",
  "p.90": "Ama sa Langit, nakikita Mo ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: Paulit-ulit akong hinuhusgahan ng mundo base sa aking mga pagkakamali, performance, o pait na dinanas. Tinatanggap ko ang Iyong tulong habang ipinapaalala Mo sa akin na ako ay Iyo, tinubos ng biyaya at yakap ng Iyong pag-ibig. Ngayon, ang katotohanan Mo nawa ang mas mangibabaw kaysa sa anumang maling bansag sa akin. Samahan Mo po ako ng Iyong biyaya sa bawat kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.91": "Panginoong Hesus, nakikita Mo ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: May lungkot sa loob ko na hindi kayang ipaliwanag ng mga salita. Tinatanggap ko ang Iyong tulong habang sinasamahan Mo ako sa aking pait at inaaliw ako nang hindi minamadali ang aking paghilom. Ngayon, turuan Mo po akong gunitain ang lahat nang may pagmamahal at patuloy na mabuhay nang may pag-asa. Turuan Mo po akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.92": "Banal na Espiritu, nakikita Mo ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: Nararamdaman ko ang hila ng mga bagay na nagpapahina sa aking kaluluwa. Tinatanggap ko ang Iyong tulong habang binibigyan Mo ako ng malinis na puso, malinaw na paraan upang umiwas sa tukso, at lakas upang piliin ang buhay. Ngayon, tulungan Mo po akong makasunod sa Iyo sa bawat sandali. Ipinagkakatiwala ko sa Iyo ang mga bagay na nauunawaan ko at maging ang mga hindi ko maintindihan. Amen.",
  "p.93": "Mapagmahal na Diyos, nakikita Mo ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: Pagod na akong maghintay at natutukso nang pilitin ang mga bagay na hindi pa handa. Tinatanggap ko ang Iyong tulong habang tinuturuan Mo akong magtiwala sa Iyong timing nang hindi nagtatanim ng pait. Ngayon, palaguin Mo po ang aking pananampalataya sa gitna ng paghihintay. Hubugin Mo po ang aking puso hanggang sa maging katulad ito ng puso ni Kristo. Amen.",
  "p.94": "Maawaing Ama, nakikita Mo ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: Ayokong dumaan lang sa buhay na ito nang hindi gising ang diwa. Tinatanggap ko ang Iyong tulong habang ipinapakita Mo sa akin ang mabubuting gawa na inihanda Mo para sa akin ngayon. Ngayon, gawin Mong mahalaga ang aking maliliit na gawa ng katapatan para sa kawalang-hanggan. Itanim Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.95": "Tapat na Panginoon, nakikita Mo ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: Sa pagtatapos ng araw na ito, isinusuko ko na ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Tinatanggap ko ang Iyong tulong habang binabalot Mo ng kapayapaan ang aking isip at iniingatan ang aking puso sa aking pagtulog. Ngayon, salubungin nawa ako ng bukas nang may panibagong awa. Ang kalooban Mo po nawa ang maging kapayapaan ko, at ang Iyong presensya ang aking lakas. Amen.",
  "p.96": "Mapagmahal na Tagapagligtas, nakikita Mo po ang aking mga pasan at alam Mo kung bakit ito mahalaga: iniaalay ko sa Iyo ang aking pagmamahal, paninindigan, at bawat relasyong nangangailangan ng Iyong haplos. Tinatanggap ko po ang Iyong saklolo sa muling pagbabalik ng lambing kung saan kami ay nagiging matalas dahil sa stress. Ngayon, turuan Mo po kaming makinig, magpatawad, at muling piliin ang isa’t isa. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong at maging sapat ang tapang na sumunod dito. Amen.",
  "p.97": "Makapangyarihang Diyos, nakikita Mo po ang aking mga pasan at alam Mo kung bakit ito mahalaga: ipinagkakatiwala ko sa Iyong tapat na kalinga ang mga bata at kabataang mahal ko. Tinatanggap ko po ang Iyong tulong sa pag-iingat sa kanilang mga puso, paggabay sa kanilang mga pasya, at pagpapaligid sa kanila ng mga boses na may karunungan. Ngayon, tulungan Mo po silang makilala Ka nang personal at malalim. Gamitin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.98": "Prinsipe ng Kapayapaan, nakikita Mo po ang aking mga pasan at alam Mo kung bakit ito mahalaga: pagpalain Mo po ang Iyong bayan at panibaguhin ang aming pagmamahal sa isa’t isa. Tinatanggap ko po ang Iyong tulong upang kami ay maging mapagpakumbaba, mapagbigay, tapat, at matapang. Ngayon, nawa’y maging salamin ang aming buhay ng kagandahan ni Hesus sa harap ng mundong nagmamasid. Gawin Mo po sa loob ko ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.99": "Ama ng Awa, nakikita Mo po ang aking mga pasan at alam Mo kung bakit ito mahalaga: may mga pangakong tila napakalayo pa at mga pangarap na tila pagod na. Tinatanggap ko po ang Iyong tulong habang binibigyan Mo ng bagong pag-asa ang mga bahagi ng buhay ko na binalot na ng pagkabigo. Ngayon, tulungan Mo po akong maniwala na patuloy Ka pang sumusulat ng magagandang kabanata. Nawa ang araw ko ay maging isang tahimik na alay ng pagsamba sa Iyo. Amen.",
  "p.100": "Ama sa Langit, ipinagkakatiwala ko po ang araw na ito sa Iyong mga kamay bago pa man ito mabahiran ng mga inaasahan ng ibang tao. Ayusin Mo po ang aking mga iniisip, patatagin ang aking damdamin, at akayin ako sa kung ano ang mabuti. Nawa ang una kong maging tugon ay pananampalataya sa halip na takot. Gamitin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.101": "Panginoong Hesus, puno ang isip ko ng mga alalahaning hindi ko kayang lutasin nang mag-isa. Patahimikin Mo po ang ingay sa loob ko at ipaalala sa akin na ang Iyong presensya ay mas malakas kaysa sa anumang takot. Turuan Mo po ang puso kong huminga sa Iyong kapayapaan. Gawin Mo po sa loob ko ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.102": "Banal na Espiritu, tila mas mabigat ang landas sa harap ko kaysa sa inaasahan ko. Bigyan Mo po ako ng tiyaga para sa susunod na hakbang ng pananampalataya, at tapang para sa mga susunod pa. Gawin Mo po akong matatag nang hindi tumitigas ang puso. Nawa ang aking buhay ngayong araw ay maging isang tahimik na alay ng pagsamba sa Iyo. Amen.",
  "p.103": "Mapagpalang Diyos, dinadala ko sa Iyo ang sakit na paulit-ulit kong inaalala nang palihim. Palayain Mo po ako sa pait ng kalooban at turuan akong magpatawad nang may karunungan, katotohanan, at biyaya. Pagalingin Mo po ang mga sugat na hindi agad nabubura ng pagpapatawad. Nawa ang Iyong biyaya ang sumalubong sa akin sa bawat kahinaan at akayin ako tungo sa kapayapaan. Amen.",
  "p.104": "Maawaing Ama, itinataas ko sa Iyo ang aking pamilya at ang mga taong pinakamalapit sa aking puso. Balutin Mo po ang aming tahanan ng pagtitimpi, katapatan, proteksyon, at pag-ibig. Gawin Mo pong banayad ang aming mga salita at matatag ang aming ugnayan. Turuan Mo po akong lumakad nang may hinahon, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.105": "Tapat na Panginoon, iniaalay ko sa Iyo ang gawa ng aking mga kamay at ang bigat na pasan ng aking mga balikat. Tulungan Mo po akong maglingkod nang may kahusayan nang hindi sinasamba ang tagumpay. Nawa'y mas mahalaga sa akin ang integridad kaysa sa palakpak ng tao. Ipinagkakatiwala ko sa Iyo ang mga bagay na nauunawaan ko at maging ang mga hindi ko maintindihan. Amen.",
  "p.106": "Mapagmahal na Tagapagligtas, dinadala ko sa Iyo ang aking katawan, isipan, at kaluluwa na nangangailangan ng panunumbalik. Hipuin Mo po ang mga sugatan, palakasin ang mahihina, at gabayan ng karunungan ang bawat nag-aalaga sa amin. Nawa’y umusbong ang pag-asa bago pa man makita ang kasagutan. Hubugin Mo po ang aking puso hanggang sa maging kawangis ito ng puso ni Kristo. Amen.",
  "p.107": "Makapangyarihang Diyos, higit pa sa impormasyon ang kailangan ko; kailangan ko po ng banal na karunungan. Ipakita Mo po sa akin kung ano ang pipiliin, ano ang tatanggihan, at kailan dapat maghintay. Iligtas Mo po ako sa mga desisyong dala lamang ng takot o pagmamataas. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.108": "Prinsipe ng Kapayapaan, humihinto po ako sandali upang mapansin ang Iyong mga biyaya na madalas kong malampasan sa aking pagmamadali. Buksan Mo po ang aking mga mata sa mga regalong nakatago sa mga karaniwang sandali. Gawin Mo pong ugali ang pagpapasalamat, hindi lang dahil sa nararamdaman ko. Nawa'y ang Iyong kalooban ang maging kapayapaan ko at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.109": "Ama ng Awa, hinihiling ko po ang Iyong proteksyon sa aking buhay at sa bawat hakbang na gagawin ko ngayong araw. Ingatan Mo po ako sa mga panganib na nakikita at sa mga bitag na hindi nakikita. Ihatid Mo po ako kung saan ako dapat pumunta at pigilan Mo po ako kung saan hindi dapat. Panatilihin Mo po akong sapat na malapit upang marinig ang Iyong bulong at sapat na matapang upang sumunod dito. Amen.",
  "p.110": "Ama sa Langit, pilit po akong binabansagan ng mundo base sa aking mga pagkakamali, kakayahan, o pait ng nakaraan. Ipaalala Mo po sa akin na ako ay Iyo, tinubos ng biyaya at yakap ng Iyong pag-ibig. Hayaang mas manaig ang Iyong katotohanan kaysa sa anumang maling bansag sa akin. Gamitin Mo po akong pagpapala sa isang taong nangangailangan ng Iyong kabutihan ngayon. Amen.",
  "p.111": "Panginoong Hesus, may mga hapis po sa loob ko na hindi kayang ipaliwanag ng mga salita. Samahan Mo po ako sa gitna ng sakit at aliwin Mo po ako nang hindi minamadali ang aking paghilom. Turuan Mo po akong lumingon nang may pagmamahal habang patuloy na namumuhay nang may pag-asa. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.112": "Banal na Espiritu, nararamdaman ko po ang hatak ng mga bagay na nagpapahina sa aking kaluluwa. Bigyan Mo po ako ng malinis na puso, ng malinaw na matatakasan mula sa tukso, at ng lakas na piliin ang buhay. Nawa'y maging posible para sa akin ang sumunod sa Iyo sa mismong sandaling ito. Maging isang tahimik na alay ng pagsamba ang aking buhay ngayong araw. Amen.",
  "p.113": "Mapagmahal na Diyos, napapagod na po ako sa paghihintay at natutuksong pilitin ang mga bagay na hindi pa handa. Turuan Mo po akong magtiwala sa Iyong takdang oras nang hindi nagiging pabaya o mapait ang loob. Palaguin Mo po ang isang tahimik na pananampalataya sa gitna ng paghihintay. Salubungin nawa ako ng Iyong biyaya sa bawat kahinaan at akayin ako patungo sa kapayapaan. Amen.",
  "p.114": "Mahabaging Ama, ayaw ko pong dumaan lang sa buhay na ito nang hindi namamalayan ang Iyong presensya. Ipakita Mo po sa akin ang mabubuting bagay na inihanda Mo para gawin ko ngayong araw. Hayaang magbunga ang aking maliliit na gawa ng katapatan para sa kawalang-hanggan. Turuan Mo po akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.115": "Tapat na Panginoon, sa pagtatapos ng araw na ito, ipinapaubaya ko na po sa Iyo ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Hugasan Mo po ang aking isipan ng Iyong kapayapaan at ingatan Mo ang aking puso habang ako'y natutulog. Salubungin nawa ako ng bukas na may bagong awa. Nagtitiwala ako sa Iyo, sa mga bagay na nauunawaan ko man o hindi. Amen.",
  "p.116": "Mapagmahal na Tagapagligtas, itinataas ko po sa Iyo ang aming pagmamahalan, mga pangako, at bawat relasyong nangangailangan ng Iyong ugnay. Ibalik Mo po ang lambing sa mga pusong naging matigas dahil sa pagod. Turuan Mo po kaming makinig, magpatawad, at muling piliin ang isa't isa. Hubugin Mo po ang aking puso hanggang sa masalamin nito ang puso ni Kristo. Amen.",
  "p.117": "Makapangyarihang Diyos, ipinagkakatiwala ko po sa Iyong tapat na pag-aaruga ang mga bata at kabataang mahal ko. Ingatan Mo po ang kanilang mga puso, gabayan ang kanilang mga desisyon, at palibutan sila ng mga taong may tamang gabay. Tulungan Mo po silang makilala Ka nang personal at malalim. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.118": "Prinsipe ng Kapayapaan, pagpalain Mo po ang Iyong bayan at pasiglahin ang aming pagmamahalan sa isa't isa. Gawin Mo po kaming mapagpakumbaba, mapagbigay, tapat, at matapang. Nawa'y ang aming buhay ang magpakita ng ganda ni Hesus sa mundong nakamasid. Maging aking kapayapaan nawa ang Iyong kalooban, at maging aking lakas ang Iyong presensya. Amen.",
  "p.119": "Ama ng Awa, ang ilang mga pangako po ay parang napakalayo pa at ang ilang mga pangarap ay tila pagod na. Hiningahan Mo po ng pag-asa ang mga bahagi ng puso kong binalot na ng kabiguan. Tulungan Mo po akong maniwala na nagsusulat Ka pa rin ng magagandang kabanata sa aking buhay. Panatilihin Mo po akong sapat na malapit upang marinig ang Iyong bulong at sapat na matapang upang sumunod dito. Amen.",
  "p.120": "Ama sa Langit, lumalapit po ako nang tapat sa Iyo ngayon: Ipinagkakatiwala ko sa Iyong mga kamay ang araw na ito bago pa man ako maharap sa mga inaasahan ng ibang tao. Nawa’y iayos Mo po ang aking isipan, patatagin ang aking damdamin, at akayin ako sa kung ano ang mabuti. Huwag po nawang manatiling salita lamang ang dalanging ito; nawa’y pananampalataya ang mauna sa aking puso sa halip na takot. Ibaon Mo po ako sa Iyong Salita, balutin ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.121": "Panginoong Hesus, lumalapit po ako nang tapat sa Iyo ngayon: Punong-puno po ang isip ko ng mga alalahanin na hindi ko kayang lutasin nang mag-isa. Pakitahimik po ang ingay sa loob ko at ipaalala sa akin na ang Iyong presensya ay mas makapangyarihan kaysa sa anumang kaba. Huwag po nawang manatiling salita lamang ang dalanging ito; turuan Mo po ang aking pusong huminga sa Iyong kapayapaan. Nawa’y ang Iyong kalooban ang maging aking kapahingahan at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.122": "Banal na Espiritu, lumalapit po ako nang tapat sa Iyo ngayon: Tila mas mabigat po ang daang nasa harap ko kaysa sa aking inaasahan. Bigyan Mo po ako ng tiyaga para sa susunod na hakbang at lakas ng loob para sa mga susunod pa. Huwag po nawang manatiling salita lamang ang dalanging ito; palakasin Mo po ako nang hindi tumitigas ang aking puso. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.123": "Mapagmahal na Diyos, lumalapit po ako nang tapat sa Iyo ngayon: Dinadala ko sa Iyo ang sakit na palihim kong inuulit-ulit sa aking isipan. Palayain Mo po ako sa pait ng kalooban at turuan akong magpatawad nang may karunungan, katotohanan, at biyaya. Huwag po nawang manatiling salita lamang ang dalanging ito; pagalingin Mo po ang mga sugat na hindi agad nabura ng pagpapatawad. Gawin Mo po akong pagpapala sa mga taong nangangailangan ng Iyong kabutihan ngayon. Amen.",
  "p.124": "Maawaing Ama, lumalapit po ako nang tapat sa Iyo ngayon: Itinataas ko po sa Iyo ang aking pamilya at ang mga taong pinakamahalaga sa akin. Balutin Mo po ang aming tahanan ng pasensya, katapatan, proteksyon, at pagmamahal. Huwag po nawang manatiling salita lamang ang dalanging ito; gawin Mong malumanay ang aming mga salita at matatag ang aming samahan. Gawin Mo po sa loob ko ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.125": "Tapat na Panginoon, lumalapit po ako nang tapat sa Iyo ngayon: Iniaalay ko sa Iyo ang gawa ng aking mga kamay at ang bigat na pasan ng aking mga balikat. Tulungan Mo po akong maglingkod nang mahusay nang hindi sinasamba ang tagumpay. Huwag po nawang manatiling salita lamang ang dalanging ito; nawa’y mas mahalaga sa akin ang integridad kaysa sa palakpak ng tao. Hayaan ang buhay ko ngayong araw na maging isang tahimik na alay ng pagsamba. Amen.",
  "p.126": "Mapagmahal na Tagapagligtas, lumalapit po ako nang tapat sa Iyo ngayon: Dinadala ko sa Iyo ang bawat bahagi ng aking katawan, isip, at kaluluwa na nangangailangan ng panunumbalik. Hawakan Mo po ang mga sugatan, palakasin ang mahihina, at gabayan ng karunungan ang lahat ng nag-aalaga sa akin. Huwag po nawang manatiling salita lamang ang dalanging ito; hayaang umusbong ang pag-asa bago pa man makita ang kasagutan. Nawa’y samahan ako ng Iyong biyaya sa bawat kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.127": "Makapangyarihang Diyos, lumalapit po ako nang tapat sa Iyo ngayon: Higit pa sa impormasyon, kailangan ko po ng banal na karunungan. Ipakita Mo po sa akin kung ano ang dapat piliin, kung ano ang dapat tanggihan, at kung kailan dapat maghintay. Huwag po nawang manatiling salita lamang ang dalanging ito; ilayo Mo po ako sa mga desisyong dala lamang ng takot o pride. Turuan Mo po akong lumakad nang may pag-iingat, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.128": "Prinsipe ng Kapayapaan, lumalapit po ako nang tapat sa Iyo ngayon: Humihinto po ako upang mapansin ang Iyong mga biyaya na madalas kong malampasan sa pagmamadali. Buksan Mo po ang aking mga mata sa mga regalong nakatago sa mga ordinaryong sandali. Huwag po nawang manatiling salita lamang ang dalanging ito; gawin Mong habit ang pagpapasalamat, hindi lang base sa nararamdaman. Nagtitiwala ako sa Iyo sa mga bagay na nauunawaan ko at maging sa mga hindi. Amen.",
  "p.129": "Ama ng Awa, lumalapit po ako nang tapat sa Iyo ngayon: Hinihiling ko ang Iyong paggabay at proteksyon sa aking buhay at sa bawat hakbang ko ngayong araw. Bantayan Mo po ako laban sa mga panganib na nakikita at sa mga bitag na nakatago. Huwag po nawang manatiling salita lamang ang dalanging ito; dalhin Mo po ako kung saan ako dapat pumunta at pigilan Mo ako kung saan hindi nararapat. Hubugin Mo ang aking puso hanggang sa masalamin nito ang puso ni Kristo. Amen.",
  "p.130": "Ama sa Langit, lumalapit po ako nang tapat sa Iyo ngayon: Patuloy akong sinusubukang bansagan ng mundo base sa aking mga pagkakamali, kakayahan, o sakit. Ipaalala Mo po sa akin na ako ay sa Iyo, tinubos ng biyaya at kinalinga ng Iyong pag-ibig. Huwag po nawang manatiling salita lamang ang dalanging ito; nawa’y mas manaig ang Iyong katotohanan kaysa sa anumang maling label sa akin. Ibaon Mo po ako sa Iyong Salita, balutin ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.131": "Panginoong Hesus, lumalapit po ako nang tapat sa Iyo ngayon: May lungkot sa loob ko na hindi kayang ipaliwanag ng mga salita. Samahan Mo po ako sa gitna ng hapdi at aliwin ako nang hindi minamadali ang aking paghilom. Huwag po nawang manatiling salita lamang ang dalanging ito; turuan Mo po akong makaalala nang may pagmamahal habang patuloy na namumuhay nang may pag-asa. Nawa’y ang Iyong kalooban ang maging aking kapayapaan at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.132": "Banal na Espiritu, lumalapit po ako nang tapat sa Iyo ngayon: Nararamdaman ko ang hatak ng mga bagay na nagpapahina sa aking kaluluwa. Bigyan Mo po ako ng malinis na puso, ng malinaw na paraan upang makaiwas sa tukso, at ng lakas na piliin ang tunay na buhay. Hayaang ang panalanging ito ay maging higit pa sa mga salita; tulungan Mo po akong makitang posible ang pagsunod sa mismong sandaling ito. Manatili sana akong malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sundin ito. Amen.",
  "p.133": "Mapagmahal na Diyos, lumalapit po ako nang tapat sa Iyo ngayon: Pagod na po akong maghintay at natutuksong ipilit ang mga bagay na hindi pa naman panahon. Turuan Mo po akong magtiwala sa Iyong takdang oras nang hindi nagiging matigas ang loob o mapait ang puso. Hayaang ang panalanging ito ay maging higit pa sa mga salita; palaguin Mo po ang isang tahimik na pananampalataya sa gitna ng paghihintay. Gawin Mo po akong pagpapala sa mga nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.134": "Maawaing Ama, lumalapit po ako nang tapat sa Iyo ngayon: Ayaw ko pong lumipas ang buhay na ito nang walang malay o walang layunin. Ipakita Mo po sa akin ang mabubuting bagay na inihanda Mo para gawin ko ngayong araw. Hayaang ang panalanging ito ay maging higit pa sa mga salita; gawin Mong mahalaga ang aking maliliit na gawa ng katapatan para sa kawalang-hanggan. Gawin Mo po sa loob ko ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.135": "Tapat na Panginoon, lumalapit po ako nang tapat sa Iyo ngayon: Sa pagtatapos ng araw na ito, ipinauubaya ko na sa Iyo ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Hugasan Mo po ang aking isipan ng Iyong kapayapaan at ingatan ang aking puso habang ako ay natutulog. Hayaang ang panalanging ito ay maging higit pa sa mga salita; nawa ay salubungin ako ng Iyong bagong awa bukas. Hayaang ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba sa Iyo. Amen.",
  "p.136": "Mapagmahal na Tagapagligtas, lumalapit po ako nang tapat sa Iyo ngayon: Itinataas ko po sa Iyo ang aming pagmamahalan, ang aming mga pangako, at ang bawat relasyong nangangailangan ng Iyong haplos. Ibalik Mo po ang lambing sa mga pusong tumigas dahil sa bigat ng buhay. Hayaang ang panalanging ito ay maging higit pa sa mga salita; turuan Mo po kaming makinig, magpatawad, at piliin muli ang isa't isa. Nawa ay samahan ako ng Iyong biyaya sa bawat kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.137": "Makapangyarihang Diyos, lumalapit po ako nang tapat sa Iyo ngayon: Ipinagkakatiwala ko po sa Iyong tapat na pangangalaga ang mga bata at kabataang mahal ko. Ingatan Mo po ang kanilang mga puso, gabayan ang kanilang mga pasya, at palibutan sila ng mga taong magbibigay ng tamang payo. Hayaang ang panalanging ito ay maging higit pa sa mga salita; tulungan Mo po silang makilala Ka nang personal at malalim. Turuan Mo po akong lumakad nang may tiyaga, magmahal nang wagas, at magtiwala nang lubos. Amen.",
  "p.138": "Prinsipe ng Kapayapaan, lumalapit po ako nang tapat sa Iyo ngayon: Pagpalain Mo po ang Iyong bayan at panibaguhin ang aming pagmamahal sa isa't isa. Gawin Mo po kaming mapagpakumbaba, mapagbigay, matapat, at matapang. Hayaang ang panalanging ito ay maging higit pa sa mga salita; nawa ay makita ang ganda ni Hesus sa aming buhay sa harap ng mundong nagmamasid. Ipinagkakatiwala ko sa Iyo ang mga bagay na nauunawaan ko at pati na rin ang mga hindi ko maintindihan. Amen.",
  "p.139": "Ama ng Awa, lumalapit po ako nang tapat sa Iyo ngayon: May mga pangakong parang kay layo pa at mga pangarap na tila nakakapagod na. Hipan Mo po ng bagong pag-asa ang mga bahagi ng buhay ko na puno ng pagkabigo. Hayaang ang panalanging ito ay maging higit pa sa mga salita; tulungan Mo po akong maniwala na gumagawa Ka pa rin ng magagandang kabanata sa aking buhay. Hubugin Mo po ang aking puso hanggang sa maging katulad ito ng puso ni Kristo. Amen.",
  "p.140": "Ama sa Langit, salamat po sa pagtatagpo sa akin sa gitna ng totoong buhay. Ipinauubaya ko ang araw na ito sa Iyong mga kamay bago ko pa harapin ang inaasahan ng ibang tao. Hinihiling ko po na ayusin Mo ang aking isipan, patatagin ang aking damdamin, at akayin ako sa kung ano ang mabuti. Sa Iyong biyaya, nawa ay pananampalataya ang maging una kong tugon sa halip na takot. Turuan Mo po akong lumakad nang may tiyaga, magmahal nang wagas, at magtiwala nang lubos. Amen.",
  "p.141": "Panginoong Hesus, salamat po sa pagtatagpo sa akin sa gitna ng totoong buhay, kung saan ang isip ko ay puno ng mga alalahanin na hindi ko kayang lutasin nang mag-isa. Patahimikin Mo po ang ingay sa loob ko at ipaalala sa akin na ang Iyong presensya ay mas malakas kaysa sa anumang takot. Sa Iyong biyaya, turuan Mo po ang aking puso na huminga sa Iyong kapayapaan. Ipinagkakatiwala ko sa Iyo ang mga bagay na nauunawaan ko at pati na rin ang mga hindi ko maintindihan. Amen.",
  "p.142": "Banal na Espiritu, salamat po sa pagtatagpo sa akin sa gitna ng totoong buhay, kung saan ang landas na tinatahak ko ay mas mabigat kaysa sa inaasahan ko. Bigyan Mo po ako ng lakas para sa susunod na hakbang at katapangan para sa mga susunod pa. Sa Iyong biyaya, gawin Mo po akong matatag nang hindi nagiging matigas ang kalooban. Hubugin Mo po ang aking puso hanggang sa maging katulad ito ng puso ni Kristo. Amen.",
  "p.143": "Mapagmahal na Diyos, salamat po sa pagtatagpo sa akin sa gitna ng totoong buhay, kung saan dala-dala ko ang mga sakit na paulit-ulit kong inaalala nang lihim. Palayain Mo po ako sa pait ng kalooban at turuan akong magpatawad nang may karunungan, katotohanan, at biyaya. Sa Iyong biyaya, hilumin Mo po ang mga sugat na hindi agad nabubura ng kapatawaran. Ibaon Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.144": "Maawaing Ama, salamat po sa pakikipagtagpo Mo sa akin sa gitna ng totoong buhay, kung saan inilalapit ko sa Iyo ang aking pamilya at ang mga taong pinakamalapit sa aking puso. Dalangin ko po na balutin Mo ang aming tahanan ng pasensya, katapatan, proteksyon, at pagmamahal. Sa Iyong biyaya, gawin Mo pong malumanay ang aming mga salita at matatag ang aming samahan. Nawa’y ang Iyong kalooban ang maging kapayapaan ko at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.145": "Tapat na Panginoon, salamat po sa pakikipagtagpo Mo sa akin sa gitna ng totoong buhay, kung saan iniaalay ko sa Iyo ang gawa ng aking mga kamay at ang bigat na pasan ko. Tulungan Mo po akong maglingkod nang buong husay nang hindi sinasamba ang tagumpay. Sa Iyong biyaya, nawa’y mas pahalagahan ko ang integridad kaysa sa papuri ng tao. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong, at bigyan ako ng tapang na sumunod dito. Amen.",
  "p.146": "Mapagmahal na Tagapagligtas, salamat po sa pakikipagtagpo Mo sa akin sa gitna ng totoong buhay, kung saan dinadala ko sa Iyo ang aking katawan, isip, at kaluluwa na nangangailangan ng paghilom. Hipuin Mo po ang mga sugat, palakasin ang mahihina, at gabayan ng karunungan ang bawat nag-aalaga sa amin. Sa Iyong biyaya, buhayin Mo ang pag-asa sa akin bago pa man makita ang kasagutan. Gawin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayon. Amen.",
  "p.147": "Makapangyarihang Diyos, salamat po sa pakikipagtagpo Mo sa akin sa gitna ng totoong buhay, kung saan higit pa sa impormasyon ang kailangan ko; kailangan ko ng banal na karunungan. Ipakita Mo po sa akin kung ano ang pipiliin, ano ang tatanggihan, at kailan dapat maghintay. Sa Iyong biyaya, ilayo Mo ako sa mga desisyong dala lamang ng takot o yabang. Gawin Mo sa loob ko ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.148": "Prinsipe ng Kapayapaan, salamat po sa pakikipagtagpo Mo sa akin sa gitna ng totoong buhay, kung saan humihinto ako upang mapansin ang Iyong mga habag na madalas kong malampasan sa pagmamadali. Buksan Mo po ang aking mga mata sa mga biyayang nakatago sa mga ordinaryong sandali. Sa Iyong biyaya, gawin Mong habit ang pagpapasalamat, hindi lang dahil sa nararamdaman ko. Nawa’y ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba sa Iyo. Amen.",
  "p.149": "Ama ng Awa, salamat po sa pakikipagtagpo Mo sa akin sa gitna ng totoong buhay, kung saan hinihiling ko ang Iyong pag-iingat sa aking buhay at sa bawat hakbang ko ngayon. Bantayan Mo po ako sa mga panganib na nakikita at sa mga bitag na nakatago. Sa Iyong biyaya, dalhin Mo ako kung saan ako dapat pumunta at pigilan Mo ako kung saan hindi nararapat. Nawa’y samahan ako ng Iyong biyaya sa bawat kahinaan at akayin ako tungo sa kapayapaan. Amen.",
  "p.150": "Ama sa Langit, salamat po sa pakikipagtagpo Mo sa akin sa gitna ng totoong buhay, kung saan pilit akong binibigyan ng label ng mundo base sa aking mga pagkakamali, performance, o sakit. Ipaalala Mo po sa akin na ako ay sa Iyo, tinubos ng biyaya at yakap ng Iyong pag-ibig. Sa Iyong biyaya, hayaang mas manaig ang Iyong katotohanan kaysa sa anumang maling bansag sa akin. Turuan Mo po akong lumakad nang may katiyakan, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.151": "Panginoong Hesus, salamat po sa pakikipagtagpo Mo sa akin sa gitna ng totoong buhay, kung saan may lungkot sa aking loob na hindi kayang sambitin ng mga salita. Samahan Mo po ako sa aking pighati at aluin ako nang hindi minamadali ang aking paghilom. Sa Iyong biyaya, turuan Mo akong makaalala nang may pagmamahal habang patuloy na namumuhay nang may pag-asa. Ipinagkakatiwala ko sa Iyo ang mga bagay na nauunawaan ko at pati na rin ang mga hindi ko maintindihan. Amen.",
  "p.152": "Banal na Espiritu, salamat po sa pakikipagtagpo Mo sa akin sa gitna ng totoong buhay, kung saan nararamdaman ko ang hila ng mga bagay na nagpapahina sa aking kaluluwa. Bigyan Mo po ako ng malinis na puso, ng paraan upang makaiwas sa masama, at ng lakas na piliin ang buhay. Sa Iyong biyaya, tulungan Mo akong sumunod sa Iyo sa mismong sandaling ito. Hubugin Mo po ang aking puso hanggang sa ito ay maging katulad ng puso ni Kristo. Amen.",
  "p.153": "Mapagbiyayang Diyos, salamat po sa pakikipagtagpo Mo sa akin sa gitna ng totoong buhay, kung saan pagod na akong maghintay at natutuksong pilitin ang mga bagay na hindi pa handa. Turuan Mo po akong magtiwala sa Iyong timing nang hindi nagiging tamad o mapait ang loob. Sa Iyong biyaya, palaguin Mo ang isang tahimik na pananampalataya sa gitna ng paghihintay. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.154": "Maawaing Ama, salamat po sa pakikipagtagpo Mo sa akin sa gitna ng totoong buhay. Ayaw ko pong lumipas lang ang buhay na ito na para bang hindi ako gising. Ipakita Mo po sa akin ang mabubuting bagay na inihanda Mo para gawin ko ngayong araw. Sa Iyong biyaya, gawing mahalaga ang aking maliliit na pagtatapat para sa kawalang-hanggan. Nawa’y ang Iyong kalooban ang maging kapayapaan ko at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.155": "Tapat na Panginoon, salamat po sa pakikipagtagpo Mo sa akin sa gitna ng totoong buhay. Sa pagtatapos ng araw na ito, ipinauubaya ko na sa Iyo ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Hugasan Mo po ang aking isipan ng kapayapaan at ingatan ang aking puso habang ako ay natutulog. Sa Iyong biyaya, nawa’y salubungin ako ng bukas na may bagong awa. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong, at bigyan ako ng tapang na sumunod dito. Amen.",
  "p.156": "Mapagmahal na Tagapagligtas, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan iniaalay ko ang aking pag-ibig, katapatan, at bawat relasyong nangangailangan ng Iyong haplos. Dalangin ko pong ibalik Mo ang lambing sa aming pagsasama lalo na kapag nagiging magaspang ang pakikitungo namin dahil sa stress. Sa Iyong biyaya, turuan Mo po kaming makinig, magpatawad, at piliing muli ang isa’t isa. Gamitin Mo po akong pagpapala sa isang taong nangangailangan ng Iyong kabaitan ngayon. Amen.",
  "p.157": "Makapangyarihang Diyos, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan ipinagkakatiwala ko sa Iyong tapat na pangangalaga ang mga bata at kabataang mahal ko sa buhay. Ingatan Mo po ang kanilang mga puso, gabayan ang kanilang mga desisyon, at palibutan sila ng mga taong magbibigay ng matalinong payo. Sa Iyong biyaya, tulungan Mo po silang makilala Ka nang personal at malalim. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko lang. Amen.",
  "p.158": "Prinsipe ng Kapayapaan, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan pinagpapala Mo ang Iyong bayan at pinapanibago ang aming pagmamahalan. Gawin Mo po kaming mapagpakumbaba, mapagbigay, tapat, at matapang. Sa Iyong biyaya, nawa’y masalamin sa aming buhay ang kagandahan ni Hesus sa harap ng mundong nagmamasid. Hayaan pong ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba. Amen.",
  "p.159": "Ama ng Awa, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan tila kay layo pa ng ilang pangako at pagod na ang aking mga pangarap. Dalangin ko pong hingahan Mo ng bagong pag-asa ang mga bahagi ng buhay ko na nababalot ng pagkabigo. Sa Iyong biyaya, tulungan Mo po akong maniwala na patuloy Ka pa ring sumusulat ng magagandang kabanata para sa akin. Samahan Mo po ako sa bawat kahinaan at akayin tungo sa kapayapaan. Amen.",
  "p.160": "Ama sa Langit, isinusuko ko po sa Iyo ang pangangailangang ito: Inilalagay ko ang araw na ito sa Iyong mga kamay bago pa man ako malunod sa mga inaasahan ng ibang tao. Manatili Ka po sa piling ko habang inaayos Mo ang aking isipan, pinapanatag ang aking damdamin, at inaakay ako sa kung ano ang mabuti. Nawa’y makita sa aking mga iniisip, desisyon, at kilos na pananampalataya ang una kong tugon sa halip na takot. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko lang. Amen.",
  "p.161": "Panginoong Hesus, isinusuko ko po sa Iyo ang pangangailangang ito: Puno ang isip ko ng mga alalahaning hindi ko kayang lutasin nang mag-isa. Manatili Ka po sa piling ko habang pinatatahimik Mo ang ingay sa loob ko at ipinapaalala sa akin na ang Iyong presensya ay mas malakas kaysa sa anumang kaba. Nawa’y makita sa aking mga iniisip, desisyon, at kilos ang kapayapaang itinuturo Mo sa aking puso. Hayaan pong ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba. Amen.",
  "p.162": "Banal na Espiritu, isinusuko ko po sa Iyo ang pangangailangang ito: Ang daang nasa harap ko ay mas mabigat kaysa sa inaasahan ko. Manatili Ka po sa piling ko habang binibigyan Mo ako ng lakas para sa susunod na hakbang at tapang para sa mga susunod pa. Nawa’y makita sa aking mga iniisip, desisyon, at kilos na pinalalakas Mo ako nang hindi tumitigas ang aking puso. Samahan Mo po ako sa bawat kahinaan at akayin tungo sa kapayapaan. Amen.",
  "p.163": "Mapagpala naming Diyos, isinusuko ko po sa Iyo ang pangangailangang ito: Dinadala ko sa Iyo ang sugat na lihim kong inaalala nang paulit-ulit. Manatili Ka po sa piling ko habang pinalalaya Mo ako sa pait at tinuturuang magpatawad nang may karunungan, katotohanan, at biyaya. Nawa’y makita sa aking mga iniisip, desisyon, at kilos ang paghilom sa mga hapdi na hindi agad mabura ng pagpapatawad. Turuan Mo po akong lumakad nang may hinahon, magmahal nang malalim, at manalig nang lubos. Amen.",
  "p.164": "Mahabaging Ama, isinusuko ko po sa Iyo ang pangangailangang ito: Itinataas ko sa Iyo ang aking pamilya at ang mga taong pinakamahalaga sa aking puso. Manatili Ka po sa piling ko habang binabalot Mo ang aming tahanan ng pasensya, katapatan, proteksyon, at pag-ibig. Nawa’y makita sa aking mga iniisip, desisyon, at kilos na ginagawa Mong banayad ang aming mga salita at matibay ang aming ugnayan. Nagtitiwala ako sa Iyo sa mga bagay na nauunawaan ko at maging sa mga hindi ko maintindihan. Amen.",
  "p.165": "Tapat na Panginoon, isinusuko ko po sa Iyo ang pangangailangang ito: Inaalay ko sa Iyo ang gawa ng aking mga kamay at ang bigat na pasan ng aking mga balikat. Manatili Ka po sa piling ko habang tinutulungan Mo akong maglingkod nang may kahusayan nang hindi sinasamba ang tagumpay. Nawa’y makita sa aking mga iniisip, desisyon, at kilos na mas mahalaga sa akin ang integridad kaysa sa palakpak ng tao. Hubugin Mo po ang aking puso hanggang sa masalamin nito ang puso ni Kristo. Amen.",
  "p.166": "Mapagmahal na Tagapagligtas, isinusuko ko po sa Iyo ang pangangailangang ito: Dinadala ko sa Iyo ang aking katawan, isip, at kaluluwa na nangangailangan ng panunumbalik. Manatili Ka po sa piling ko habang hinahaplos Mo ang mga sugat, pinalalakas ang mahina, at binibigyan ng karunungan ang bawat nag-aalaga sa akin. Nawa’y makita sa aking mga iniisip, desisyon, at kilos na nagbibigay Ka ng pag-asa bago pa man dumating ang kasagutan. Iangkla Mo po ako sa Kasulatan, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.167": "Makapangyarihang Diyos, isinusuko ko po sa Iyo ang pangangailangang ito: Hindi lang impormasyon ang kailangan ko, kundi banal na karunungan. Manatili Ka po sa piling ko habang ipinapakita Mo sa akin kung ano ang pipiliin, ano ang tatanggihan, at kailan dapat maghintay. Nawa’y makita sa aking mga iniisip, desisyon, at kilos na inilalayo Mo ako sa mga pasyang dala lang ng takot o pagmamataas. Maging kapayapaan ko nawa ang Iyong kalooban at maging lakas ko ang Iyong presensya. Amen.",
  "p.168": "Prinsipe ng Kapayapaan, isinusuko ko po sa Iyo ang pangangailangang ito: tumitigil po ako sandali para bigyang-pansin ang Iyong mga habag na madalas kong nalalagpasan sa aking pagmamadali. Manatili Ka po sa piling ko habang iminumulat Mo ang aking mga mata sa mga biyayang nakatago sa mga ordinaryong sandali. Nawa'y makita sa aking mga iniisip, desisyon, at reaksyon na ang pasasalamat ay naging ugali ko na, at hindi lang basta nararamdaman. Panatilihin Mo po akong malapit sa Iyo upang marinig ko ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.169": "Ama ng Awa, isinusuko ko po sa Iyo ang pangangailangang ito: hinihiling ko po ang Iyong pagkalinga sa aking buhay at sa bawat hakbang ko ngayong araw. Samahan Mo po ako at ingatan mula sa mga panganib na nakikita at mga bitag na nakatago. Nawa'y makita sa aking mga iniisip, desisyon, at reaksyon na Ikaw ang nagtuturo sa akin kung saan dapat pumunta at pumipigil sa akin kung saan hindi dapat. Gawin Mo po akong pagpapala sa isang taong nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.170": "Ama sa Langit, isinusuko ko po sa Iyo ang pangangailangang ito: pilit po akong binibigyan ng mundo ng bansag batay sa aking mga pagkakamali, performance, o sakit. Manatili Ka po sa piling ko at ipaalala sa akin na ako ay Iyo, tinubos ng biyaya at yakap ng Iyong pagmamahal. Nawa'y makita sa aking mga iniisip, desisyon, at reaksyon na ang Iyong katotohanan ang mas matimbang kaysa sa anumang maling label sa akin. Gawin Mo po sa loob ko ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.171": "Panginoong Hesus, isinusuko ko po sa Iyo ang pangangailangang ito: may lungkot sa loob ko na hindi kayang ipaliwanag ng mga salita. Manatili Ka po sa tabi ko sa gitna ng hapdi at aliwin Mo po ako nang hindi minamadali ang aking paggaling. Nawa'y makita sa aking mga iniisip, desisyon, at reaksyon na tinuturuan Mo akong makaalala nang may pagmamahal habang namumuhay pa rin nang may pag-asa. Hayaang ang buhay ko ngayon ay maging isang tahimik na alay ng pagsamba sa Iyo. Amen.",
  "p.172": "Banal na Espiritu, isinusuko ko po sa Iyo ang pangangailangang ito: nararamdaman ko ang hila ng mga bagay na nagpapahina sa aking kaluluwa. Manatili Ka po sa piling ko habang binibigyan Mo ako ng malinis na puso, malinaw na matatakasan, at lakas na piliin ang buhay. Nawa'y makita sa aking mga iniisip, desisyon, at reaksyon na ginagawa Mong posible ang pagsunod sa Iyo sa mismong sandaling ito. Hayaang punan ng Iyong biyaya ang bawat kong kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.173": "Mapagmahal na Diyos, isinusuko ko po sa Iyo ang pangangailangang ito: pagod na po akong maghintay at natutukso na pilitin ang mga bagay na hindi pa handa. Manatili Ka po sa piling ko habang tinuturuan Mo akong magtiwala sa Iyong timing nang hindi nagiging tamad o mapait. Nawa'y makita sa aking mga iniisip, desisyon, at reaksyon na nagkakaroon ako ng tahimik na pananampalataya sa gitna ng paghihintay. Turuan Mo po akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubusan. Amen.",
  "p.174": "Mahabaging Ama, isinusuko ko po sa Iyo ang pangangailangang ito: ayaw ko pong dumaan lang sa buhay na ito nang tila tulog ang kalooban. Manatili Ka po sa tabi ko habang ipinapakita Mo ang mabubuting bagay na inihanda Mo para gawin ko ngayong araw. Nawa'y makita sa aking mga iniisip, desisyon, at reaksyon na ang maliliit kong gawa ng katapatan ay may halaga para sa walang hanggan. Ipinagkakatiwala ko po sa Iyo ang mga bagay na nauunawaan ko at maging ang mga hindi ko maintindihan. Amen.",
  "p.175": "Tapat na Panginoon, isinusuko ko po sa Iyo ang pangangailangang ito: sa pagtatapos ng araw na ito, binibitawan ko na ang mga bagay na hindi ko kayang ayusin ngayong gabi. Manatili Ka po sa tabi ko habang hinuhugasan Mo ang aking isipan ng kapayapaan at iniingatan ang aking puso habang ako ay natutulog. Nawa'y makita sa aking mga iniisip, desisyon, at reaksyon na sasalubungin ako ng bukas na may bagong awa. Hubugin Mo po ang aking puso hanggang sa ito ay maging katulad ng puso ni Kristo. Amen.",
  "p.176": "Mapagmahal na Tagapagligtas, isinusuko ko po sa Iyo ang pangangailangang ito: itinataas ko ang pagmamahal, katapatan, at bawat relasyong nangangailangan ng Iyong haplos. Manatili Ka po sa piling namin habang ibinabalik Mo ang lambing sa mga pusong pinatigas ng stress. Nawa'y makita sa aking mga iniisip, desisyon, at reaksyon na tinuturuan Mo kaming makinig, magpatawad, at muling piliin ang isa't isa. Iangkla Mo po ako sa Iyong Salita, palibutan ng awa, at punuin ng pag-asa. Amen.",
  "p.177": "Makapangyarihang Diyos, isinusuko ko po sa Iyo ang pangangailangang ito: inilalagay ko ang mga bata at kabataang mahal ko sa Iyong tapat na pangangalaga. Manatili Ka po sa piling nila habang iniingatan Mo ang kanilang puso, ginagabayan ang kanilang mga desisyon, at pinalilibutan sila ng mga taong may tamang payo. Nawa'y makita sa aking mga iniisip, desisyon, at reaksyon na tinutulungan Mo silang makilala Ikaw nang personal at malalim. Maging kapayapaan ko nawa ang Iyong kalooban at ang Iyong presensya ang maging lakas ko. Amen.",
  "p.178": "Prinsipe ng Kapayapaan, isinusuko ko po sa Iyo ang pangangailangang ito: pagpalain Mo po ang Iyong bayan at baguhin ang aming pagmamahal sa isa't isa. Manatili Ka po sa piling namin habang ginagawa Mo kaming mapagpakumbaba, mapagbigay, matapat, at matapang. Nawa'y makita sa aking mga iniisip, desisyon, at reaksyon na ang aming buhay ay nagpapakita ng kagandahan ni Hesus sa mundong nakamasid. Panatilihin Mo po akong malapit sa Iyo upang marinig ko ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.179": "Ama ng Awa, isinusuko ko po sa Iyo ang pangangailangang ito: ang ilang mga pangako ay tila kay layo at ang ilang mga pangarap ay tila pagod na. Manatili Ka po sa piling ko habang hinihingahan Mo ng pag-asa ang mga bahagi ng buhay ko na nababalot ng pagkabigo. Nawa'y makita sa aking mga iniisip, desisyon, at reaksyon na naniniwala akong nagsusulat Ka pa rin ng magagandang kabanata sa buhay ko. Gawin Mo po akong pagpapala sa mga taong nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.180": "Ama sa Langit, nakikita Mo po ang aking mga pasanin at alam Mo kung bakit ito mahalaga: Ipinagkakatiwala ko ang araw na ito sa Iyong mga kamay bago pa man sa mga inaasahan ng iba. Tinatanggap ko po ang Iyong tulong sa pag-aayos ng aking isipan, pagpapatatag ng aking damdamin, at pag-akay sa akin sa kabutihan. Ngayon, nawa'y pananampalataya ang maging tugon ko sa halip na takot. Maging kapayapaan ko nawa ang Iyong kalooban at maging lakas ko ang Iyong presensya. Amen.",
  "p.181": "Panginoong Hesus, nakikita Mo po ang aking mga pasanin at alam Mo kung bakit ito mahalaga: punong-puno ang aking isip ng mga alalahanin na hindi ko kayang lutasin nang mag-isa. Tinatanggap ko po ang Iyong tulong sa pagpatahimik ng gulo sa loob ko, at ipaalala Mo po sa akin na mas matimbang ang Iyong presensya kaysa sa anumang kaba. Ngayon, turuan Mo ang puso kong huminga sa Iyong kapayapaan. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.182": "Banal na Espiritu, nakikita Mo po ang aking mga pasanin at alam Mo kung bakit ito mahalaga: tila mas mabigat ang daang tatahakin ko kaysa sa inaasahan ko. Tinatanggap ko po ang Iyong tulong na bigyan ako ng tatag para sa susunod na hakbang, at tapang para sa mga susunod pa. Ngayon, palakasin Mo po ako nang hindi tumitigas ang aking puso. Gawin Mo po akong pagpapala sa mga taong nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.183": "Mapagmahal na Diyos, nakikita Mo po ang aking mga pasanin at alam Mo kung bakit ito mahalaga: inilalapit ko po sa Iyo ang mga sugat na lihim kong inaalala nang paulit-ulit. Tinatanggap ko po ang Iyong tulong upang lumaya ako sa pait ng kalooban at matutong magpatawad nang may karunungan, katotohanan, at biyaya. Ngayon, pagalingin Mo po ang mga sakit na hindi agad naalis ng pagpapatawad. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.184": "Maawaing Ama, nakikita Mo po ang aking mga pasanin at alam Mo kung bakit ito mahalaga: itinataas ko po sa Iyo ang aking pamilya at ang mga taong pinakamalapit sa aking puso. Tinatanggap ko po ang Iyong tulong sa pagbalot sa aming tahanan ng pagtitiyaga, katapatan, proteksyon, at pagmamahal. Ngayon, nawa'y maging malumanay ang aming mga salita at maging matatag ang aming samahan. Hayaan Mo pong ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba sa Iyo. Amen.",
  "p.185": "Tapat na Panginoon, nakikita Mo po ang aking mga pasanin at alam Mo kung bakit ito mahalaga: iniaalay ko po sa Iyo ang gawa ng aking mga kamay at ang bigat na pasan ng aking mga balikat. Tinatanggap ko po ang Iyong tulong sa paglilingkod nang may kahusayan nang hindi sinasamba ang tagumpay. Ngayon, nawa'y mas mahalaga sa akin ang integridad kaysa sa palakpak ng iba. Samahan nawa ako ng Iyong biyaya sa bawat kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.186": "Mapagmahal na Tagapagligtas, nakikita Mo po ang aking mga pasanin at alam Mo kung bakit ito mahalaga: inilalapit ko po sa Iyo ang aking katawan, isipan, at kaluluwa na nangangailangan ng panunumbalik. Tinatanggap ko po ang Iyong tulong; hipuin Mo po ang bawat sugat, palakasin ang mahina, at gabayan ng Iyong karunungan ang bawat nag-aalaga sa akin. Ngayon, hayaang umusbong ang pag-asa bago pa man makita ang kasagutan. Turuan Mo akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.187": "Makapangyarihang Diyos, nakikita Mo po ang aking mga pasanin at alam Mo kung bakit ito mahalaga: hindi lang impormasyon ang kailangan ko, kundi banal na karunungan. Tinatanggap ko po ang Iyong tulong sa pagpapakita kung ano ang dapat piliin, ang dapat tanggihan, at kung kailan dapat maghintay. Ngayon, ilayo Mo po ako sa mga desisyong dala lamang ng takot o pagmamataas. Ipinagkakatiwala ko sa Iyo ang mga bagay na nauunawaan ko man o hindi. Amen.",
  "p.188": "Prinsipe ng Kapayapaan, nakikita Mo po ang aking mga pasanin at alam Mo kung bakit ito mahalaga: humihinto po ako upang mapansin ang Iyong mga biyaya na madalas kong malampasan sa pagmamadali. Tinatanggap ko po ang Iyong tulong sa pagbubukas ng aking mga mata sa mga regalong nakatago sa mga ordinaryong sandali. Ngayon, gawin Mo pong ugali ang pasasalamat at hindi lamang base sa nararamdaman. Hubugin Mo po ang aking puso hanggang sa maaninag dito ang puso ni Kristo. Amen.",
  "p.189": "Ama ng Awa, nakikita Mo po ang aking mga pasanin at alam Mo kung bakit ito mahalaga: hinihiling ko po ang Iyong pagkalinga sa aking buhay at sa bawat hakbang ko ngayong araw. Tinatanggap ko po ang Iyong tulong sa pag-iingat sa akin mula sa mga panganib at mga nakatagong bitag. Ngayon, akayin Mo po ako sa nararapat kong puntahan at pigilan Mo ako sa hindi dapat. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.190": "Ama sa Langit, nakikita Mo po ang aking mga pasanin at alam Mo kung bakit ito mahalaga: patuloy akong sinusubukang bansagan ng mundo base sa aking mga pagkakamali, kakayahan, o pait na dinaranas. Tinatanggap ko po ang Iyong tulong at ang paalala na ako ay Iyo—tinubos ng biyaya at yunit sa pag-ibig. Ngayon, hayaan Mo pong ang Iyong katotohanan ang mas mangibabaw kaysa sa anumang maling paratang. Maging kapayapaan ko nawa ang Iyong kalooban at maging lakas ko ang Iyong presensya. Amen.",
  "p.191": "Panginoong Hesus, nakikita Mo po ang aking mga pasanin at alam Mo kung bakit ito mahalaga: may lungkot sa loob ko na hindi kayang ipaliwanag ng mga salita. Tinatanggap ko po ang Iyong tulong; samahan Mo po ako sa aking pighati at aluin ako nang hindi minamadali ang aking paghilom. Ngayon, turuan Mo akong umalala nang may pagmamahal habang patuloy na nabubuhay nang may pag-asa. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.192": "Banal na Espiritu, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: ramdam ko ang hila ng mga bagay na nagpapahina sa aking kaluluwa. Tinatanggap ko po ang Iyong tulong habang binibigyan Mo ako ng malinis na puso, malinaw na paraan para makaiwas sa pagkakasala, at lakas para piliin ang buhay. Ngayon, nawa’y maging posible sa akin ang sumunod sa Iyo sa bawat sandali. Gamitin Mo po akong pagpapala sa mga nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.193": "Mapagmahal na Diyos, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: pagod na po akong maghintay at natutuksong pilitin ang mga bagay na hindi pa panahon. Tinatanggap ko po ang Iyong tulong habang tinuturuan Mo akong magtiwala sa Iyong takdang oras nang hindi nawawalan ng sigla o nagtatanim ng sama ng loob. Ngayon, palaguin Mo po sa akin ang isang tahimik na pananampalataya sa gitna ng paghihintay. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.194": "Maawaing Ama, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: ayokong lumipas ang buhay na ito na tila nangangarap lang nang gising. Tinatanggap ko po ang Iyong tulong habang ipinapakita Mo ang mabubuting gawa na inihanda Mo para sa akin ngayong araw. Ngayon, gawin Mo pong mahalaga hanggang sa kawalang-hanggan ang aking maliliit na gawa ng katapatan. Nawa’y maging isang tahimik na alay ng pagsamba ang aking buhay ngayong araw. Amen.",
  "p.195": "Tapat na Panginoon, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: sa pagtatapos ng araw na ito, isinusuko ko ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Tinatanggap ko po ang Iyong tulong habang hinuhugasan Mo ang aking isipan ng Iyong kapayapaan at iniingatan ang aking puso habang ako’y natutulog. Hayaan Mo pong salubungin ako ng bukas nang may bagong awa. Nawa’y samahan ako ng Iyong biyaya sa lahat ng aking kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.196": "Mapagmahal na Tagapagligtas, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: itinataas ko sa Iyo ang aming pagmamahalan, pangako, at bawat relasyong nangangailangan ng Iyong haplos. Tinatanggap ko po ang Iyong tulong habang ibinabalik Mo ang lambing sa mga pusong pinatigas ng pagod at stress. Ngayon, turuan Mo po kaming makinig, magpatawad, at piliin muli ang isa’t isa. Turuan Mo po akong lumakad nang may hinahon, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.197": "Makapangyarihang Diyos, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: ipinagkakatiwala ko sa Iyong tapat na kalinga ang mga bata at kabataang mahal ko. Tinatanggap ko po ang Iyong tulong habang iniingatan Mo ang kanilang puso, ginagabayan ang kanilang mga desisyon, at pinalilibutan sila ng mga taong may mabuting payo. Ngayon, tulungan Mo po silang makilala Ka nang personal at malalim. Pinagkakatiwalaan Kita sa mga bagay na nauunawaan ko at maging sa mga hindi ko maintindihan. Amen.",
  "p.198": "Prinsipe ng Kapayapaan, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: pagpalain Mo po ang Iyong bayan at panibaguhin ang aming pagmamahal sa isa't isa. Tinatanggap ko po ang Iyong tulong habang hinuhubog Mo kaming maging mapagpakumbaba, mapagbigay, tapat, at matapang. Ngayon, nawa’y ipakita ng aming buhay ang kagandahan ni Hesus sa mundong nagmamasid. Hubugin Mo ang aking puso hanggang sa masalamin nito ang puso ni Kristo. Amen.",
  "p.199": "Ama ng Awa, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: tila napakalayo pa ng ilang mga pangako at pagod na ang aking mga pangarap. Tinatanggap ko po ang Iyong tulong habang hinihingahan Mo ng pag-asa ang mga bahagi ng buhay ko na nabahiran ng pagkabigo. Ngayon, tulungan Mo po akong maniwala na patuloy Ka pang sumusulat ng magagandang kabanata para sa akin. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.200": "Ama sa Langit, inilalagay ko po ang araw na ito sa Iyong mga kamay bago ko pa man isipin ang inaasahan ng ibang tao sa akin. Ayusin Mo po ang aking mga iniisip, patatagin ang aking emosyon, at akayin ako sa kung ano ang mabuti. Nawa’y pananampalataya ang una kong maging tugon sa halip na takot. Pinagkakatiwalaan Kita sa mga bagay na nauunawaan ko at maging sa mga hindi ko maintindihan. Amen.",
  "p.201": "Panginoong Hesus, punong-puno ang isip ko ng mga alalahanin na hindi ko kayang lutasin nang mag-isa. Patahimikin Mo po ang ingay sa loob ko at ipaalala sa akin na mas makapangyarihan ang Iyong presensya kaysa sa anumang kaba. Turuan Mo po ang puso kong huminga sa Iyong kapayapaan. Hubugin Mo po ang aking puso hanggang sa masalamin nito ang puso ni Kristo. Amen.",
  "p.202": "Banal na Espiritu, tila mas mabigat ang daang nasa harap ko kaysa sa inaasahan ko. Bigyan Mo po ako ng lakas para sa susunod na hakbang at katapangan para sa mga kasunod pa. Palakasin Mo po ako nang hindi tumitigas ang aking kalooban. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.203": "Mapagmahal na Diyos, inilalapit ko po sa Iyo ang sakit na paulit-ulit kong inaalala nang palihim. Palayain Mo po ako sa pait ng kalooban at turuan akong magpatawad nang may karunungan, katotohanan, at biyaya. Hilumin Mo po ang mga sugat na hindi agad nabubura ng pagpapatawad. Nawa’y ang Iyong kalooban ang maging aking kapayapaan at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.204": "Maawaing Ama, itinataas ko po sa Iyo ang aking pamilya at ang mga taong pinakamalapit sa puso ko. Balutin Mo po ang aming tahanan ng pasensya, katapatan, proteksyon, at pag-ibig. Gawin Mo pong banayad ang aming mga salita at matatag ang aming samahan. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong, at sapat na matapang upang sumunod sa Iyo. Amen.",
  "p.205": "Tapat na Panginoon, iniaalay ko po sa Iyo ang gawa ng aking mga kamay at ang bigat na pasan ng aking mga balikat. Tulungan Mo po akong maglingkod nang may kahusayan nang hindi ginagawang diyos ang tagumpay. Nawa’y mas mahalaga sa akin ang integridad kaysa sa palakpakan ng iba. Gamitin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.206": "Mapagmahal na Tagapagligtas, inilalapit ko po sa Iyo ang bawat bahagi ng aking katawan, isip, at kaluluwa na nangangailangan ng paghilom. Hipuin Mo po ang bawat sugat, palakasin ang mahihina, at pagkalooban ng karunungan ang lahat ng nag-aalaga sa akin. Nawa’y umusbong ang pag-asa bago pa man makita ang kasagutan. Gawin Mo po sa loob ko ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.207": "Makapangyarihang Diyos, hindi lang impormasyon ang kailangan ko kundi banal na karunungan. Ipakita Mo po sa akin ang dapat piliin, ang dapat tanggihan, at kung kailan dapat maghintay. Ilayo Mo po ako sa mga desisyong dala lamang ng takot o yabang. Nawa’y maging isang tahimik na alay ng pagsamba ang buhay ko ngayong araw. Amen.",
  "p.208": "Prinsipe ng Kapayapaan, humihinto po ako upang mapansin ang Iyong mga awa na madalas kong malagpasan sa aking pagmamadali. Buksan Mo po ang aking mga mata sa mga biyayang nakatago sa mga ordinaryong sandali. Gawin Mo pong gawi ng aking puso ang pagpapasalamat, hindi lang dahil sa nararamdaman ko. Nawa’y samahan ako ng Iyong biyaya sa bawat kahinaan at akayin ako tungo sa kapayapaan. Amen.",
  "p.209": "Ama ng Awa, hinihiling ko po ang Iyong pagkalinga sa aking buhay at sa bawat hakbang ko ngayong araw. Ingatan Mo po ako sa mga panganib na nakikita at sa mga bitag na nakatago. Ihatid Mo po ako sa dapat kong puntahan at pigilan Mo po ako sa hindi nararapat. Turuan Mo po akong lumakad nang may kapanatagan, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.210": "Ama sa Langit, pilit po akong hinuhusgahan ng mundo base sa aking mga kabiguan, performance, o sakit. Ipaalala Mo po sa akin na ako ay Iyo—tinubos ng biyaya at yakap ng pag-ibig. Nawa’y mas mangibabaw ang Iyong katotohanan kaysa sa anumang maling bansag sa akin. Ipinagkakatiwala ko po sa Iyo ang mga bagay na nauunawaan ko at pati na ang mga hindi. Amen.",
  "p.211": "Panginoong Hesus, may mga pighati sa puso ko na hindi kayang ipaliwanag ng mga salita. Samahan Mo po ako sa aking sakit at aluwin Mo po ako nang hindi minamadali ang aking paghilom. Turuan Mo po akong umalala nang may pagmamahal habang patuloy na namumuhay nang may pag-asa. Hubugin Mo po ang aking puso hanggang sa masalamin nito ang puso ni Kristo. Amen.",
  "p.212": "Espiritu Santo, nararamdaman ko po ang hila ng mga bagay na nagpapahina sa aking kaluluwa. Bigyan Mo po ako ng malinis na puso, malinaw na paraan para makaiwas sa tukso, at lakas na piliin ang buhay. Tulungan Mo po akong makasunod sa Iyo sa mismong sandaling ito. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.213": "Mapagpalang Diyos, napapagod na po akong maghintay at natutukso na pilitin ang mga bagay na hindi pa handa. Turuan Mo po akong magtiwala sa Iyong takdang oras nang hindi nawawalan ng sigla o nagtatanim ng pait. Palaguin Mo po ang isang tahimik na pananampalataya sa gitna ng paghihintay. Nawa’y ang Iyong kalooban ang maging aking kapayapaan at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.214": "Maawaing Ama, ayaw ko pong dumaan ang buhay na ito nang parang hindi gising sa katotohanan. Ipakita Mo po sa akin ang mabubuting gawa na inihanda Mo para sa akin ngayong araw. Nawa’y magkaroon ng halaga para sa kawalang-hanggan ang aking maliliit na gawa ng katapatan. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong, at sapat na matapang upang sumunod sa Iyo. Amen.",
  "p.215": "Tapat na Panginoon, sa pagtatapos ng araw na ito, isinusuko ko po sa Iyo ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Hugasan Mo po ng kapayapaan ang aking isipan at ingatan ang aking puso habang ako ay natutulog. Nawa’y salubungin ako ng bagong awa bukas ng umaga. Gamitin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.216": "Mapagmahal na Tagapagligtas, itinataas ko po sa Iyo ang aming pagmamahalan, katapatan, at bawat relasyong nangangailangan ng Iyong haplos. Ibalik Mo po ang lambing sa mga bahaging tumigas dahil sa pagod at stress. Turuan Mo po kaming makinig, magpatawad, at piliin muli ang isa't isa. Gawin Mo po sa akin ang hindi ko kayang gawin nang mag-isa. Amen.",
  "p.217": "Makapangyarihang Diyos, ipinagkakatiwala ko po sa Iyong tapat na kalinga ang mga bata at kabataang mahal ko. Ingatan Mo po ang kanilang puso, gabayan ang kanilang mga desisyon, at palibutan sila ng mga taong magbibigay ng tamang payo. Tulungan Mo po silang makilala Ka nang personal at malalim. Nawa ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba. Amen.",
  "p.218": "Prinsipe ng Kapayapaan, pagpalain Mo po ang Iyong bayan at panibaguhin ang aming pagmamahal sa isa't isa. Gawin Mo po kaming mapagkumbaba, mapagbigay, tapat, at matapang. Nawa’y makita ang ganda ni Jesus sa aming buhay sa harap ng mundong nagmamasid. Hayaan pong ang Iyong biyaya ang sumalubong sa akin sa bawat kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.219": "Ama ng Awa, may mga pangakong tila kaylayo pa at mga pangarap na tila nakapapagod na. Hipan Mo po ng bagong pag-asa ang mga bahagi ng buhay ko kung saan nanahan ang pagkabigo. Tulungan Mo po akong maniwala na nagsusulat Ka pa rin ng magagandang kabanata. Turuan Mo po akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.220": "Ama sa Langit, tapat akong lumalapit sa Iyo ngayon: Ipinapaubaya ko po sa Iyong mga kamay ang araw na ito bago pa man ako harapin ng mga inaasahan ng iba. Pakiayos po ang aking mga iniisip, patatagin ang aking emosyon, at akayin ako sa kung ano ang mabuti. Nawa ang dalanging ito ay higit pa sa mga salita; hayaang pananampalataya ang una kong itugon sa halip na takot. Maging isang tahimik na alay ng pagsamba ang buhay ko ngayong araw. Amen.",
  "p.221": "Panginoong Hesus, tapat akong lumalapit sa Iyo ngayon: punong-puno ang isip ko ng mga alalahanin na hindi ko kayang lutasin nang mag-isa. Pakiusap po, patahimikin Mo ang ingay sa loob ko at ipaalala sa akin na ang Iyong presensya ay mas malakas kaysa sa anumang kaba. Nawa’y higit pa sa salita ang panalanging ito; turuan Mo po ang aking puso na huminga sa Iyong kapayapaan. Hayaan pong ang Iyong biyaya ang sumalubong sa akin sa bawat kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.222": "Banal na Espiritu, tapat akong lumalapit sa Iyo ngayon: ang landas na nasa harap ko ay tila mas mabigat kaysa sa inaasahan ko. Bigyan Mo po ako ng tatag para sa susunod na hakbang at lakas ng loob para sa kasunod pa nito. Huwag pong hayaang manatiling salita lamang ang dalangin na ito; palakasin Mo po ako nang hindi tumitigas ang aking puso. Turuan Mo po akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.223": "Mapagmahal na Diyos, tapat akong lumalapit sa Iyo ngayon: Dinadala ko po sa Iyo ang sakit na paulit-ulit kong inaalala nang palihim. Palayain Mo po ako sa pait ng kalooban at turuan akong magpatawad nang may karunungan, katotohanan, at biyaya. Nawa’y higit pa sa salita ang panalanging ito; pagalingin Mo po ang mga sugat na hindi agad nabubura ng pagpapatawad. Pinagkakatiwalaan Kita sa mga bagay na nauunawaan ko at maging sa mga hindi. Amen.",
  "p.224": "Mahabaging Ama, tapat akong lumalapit sa Iyo ngayon: Itinataas ko po sa Iyo ang aking pamilya at ang mga taong pinakamalapit sa puso ko. Balutin Mo po ang aming tahanan ng pasensya, katapatan, proteksyon, at pagmamahal. Huwag pong hayaang manatiling salita lamang ang dalangin na ito; gawin Mo pong malumanay ang aming mga salita at matatag ang aming samahan. Hubugin Mo po ang puso ko hanggang sa makita rito ang puso ni Kristo. Amen.",
  "p.225": "Tapat na Panginoon, tapat akong lumalapit sa Iyo ngayon: Iniaalay ko po sa Iyo ang gawa ng aking mga kamay at ang bigat na pasan ko. Tulungan Mo po akong maglingkod nang mahusay nang hindi sinasamba ang tagumpay. Nawa’y higit pa sa salita ang dalanging ito; mas pahalagahan ko po sana ang integridad kaysa sa palakpak ng tao. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.226": "Mapagmahal na Tagapagligtas, tapat akong lumalapit sa Iyo ngayon: Dinadala ko po sa Iyo ang aking katawan, isip, at kaluluwa na nangangailangan ng pagpapanumbalik. Hiphin Mo po ang mga sugatan, palakasin ang mahihina, at gabayan ng karunungan ang lahat ng nag-aalaga sa akin. Nawa’y higit pa sa salita ang dalanging ito; bumangon sana ang pag-asa bago pa man makita ang kasagutan. Maging kapayapaan ko nawa ang Iyong kalooban at maging lakas ko ang Iyong presensya. Amen.",
  "p.227": "Makapangyarihang Diyos, tapat akong lumalapit sa Iyo ngayon: Higit pa sa impormasyon, ang kailangan ko po ay banal na karunungan. Ipakita Mo po sa akin kung ano ang dapat piliin, kung ano ang dapat tanggihan, at kung kailan dapat maghintay. Huwag pong hayaang manatiling salita lamang ang dalangin na ito; ilayo Mo po ako sa mga desisyong udyok lamang ng takot o pagmamataas. Manatili sana akong malapit sa Iyo upang marinig ang Iyong bulong, at maging sapat na matapang upang sumunod dito. Amen.",
  "p.228": "Prinsipe ng Kapayapaan, lumalapit po ako nang tapat sa Iyo ngayon: tumitigil po ako sandali para kilalanin ang Iyong mga biyaya na madalas kong nalalagpasan sa pagmamadali. Buksan Mo po ang aking mga mata sa mga regalong nakatago sa mga ordinaryong sandali. Nawa ang panalanging ito ay higit pa sa mga salita; gawin Mo pong isang gawi, at hindi lamang bugso ng damdamin, ang pagpapasalamat. Gamitin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.229": "Ama ng Awa, lumalapit po ako nang tapat sa Iyo ngayon: hinihiling ko po ang Iyong proteksyon sa aking buhay at sa bawat hakbang na gagawin ko. Bantayan Mo po ako laban sa mga panganib na nakikita at mga bitag na hindi ko namamalayan. Nawa ang panalanging ito ay maging higit pa sa mga salita; akayin Mo po ako sa dapat kong puntahan at pigilan Mo po ako sa hindi ko dapat pasukin. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.230": "Ama sa Langit, lumalapit po ako nang tapat sa Iyo ngayon: pilit po akong binabansagan ng mundo ayon sa aking mga pagkakamali, tagumpay, o pighati. Ipaalala Mo po sa akin na ako ay Iyo, tinubos ng biyaya at yakap ng pagmamahal. Nawa ang panalanging ito ay maging higit pa sa mga salita; hayaang mas mangibabaw ang Iyong katotohanan kaysa sa anumang maling bansag sa akin. Maging isang tahimik na alay ng pagsamba ang buhay ko ngayong araw. Amen.",
  "p.231": "Panginoong Hesus, lumalapit po ako nang tapat sa Iyo ngayon: may lungkot sa aking loob na hindi kayang ilarawan ng mga salita. Samahan Mo po ako sa aking pighati at aluin Mo ako nang hindi minamadali ang aking paghilom. Nawa ang panalanging ito ay maging higit pa sa mga salita; turuan Mo akong makaalala nang may pagmamahal habang patuloy na namumuhay nang may pag-asa. Nawa ang Iyong biyaya ang sumalubong sa akin sa bawat kahinaan at akayin ako tungo sa kapayapaan. Amen.",
  "p.232": "Banal na Espiritu, lumalapit po ako nang tapat sa Iyo ngayon: nararamdaman ko po ang hatak ng mga bagay na nagpapahina sa aking kaluluwa. Bigyan Mo po ako ng malinis na puso, ng malinaw na daan para makaiwas sa tukso, at ng lakas na piliin ang buhay. Nawa ang panalanging ito ay maging higit pa sa mga salita; tulungan Mo akong makitang posible ang pagsunod sa Iyo sa mismong sandaling ito. Turuan Mo akong lumakad nang may pag-iingat, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.233": "Mapagmahal na Diyos, lumalapit po ako nang tapat sa Iyo ngayon: napapagod na po akong maghintay at natutuksong pilitin ang mga bagay na hindi pa panahon. Turuan Mo po akong magtiwala sa Iyong takdang oras nang hindi nagiging tamad o mapait ang loob. Nawa ang panalanging ito ay maging higit pa sa mga salita; palaguin Mo po ang isang tahimik na pananampalataya sa gitna ng paghihintay. Ipinagkakatiwala ko po sa Iyo ang mga bagay na nauunawaan ko at pati na ang mga hindi. Amen.",
  "p.234": "Maawaing Ama, lumalapit po ako nang tapat sa Iyo ngayon: ayaw ko pong dumaan sa buhay na ito nang walang malay o walang layunin. Ipakita Mo po sa akin ang kabutihang inihanda Mo para gawin ko ngayong araw. Nawa ang panalanging ito ay maging higit pa sa mga salita; gawin Mong mahalaga ang aking maliliit na gawa ng katapatan para sa kawalang-hanggan. Hubugin Mo po ang aking puso hanggang sa maging aninag ito ng puso ni Kristo. Amen.",
  "p.235": "Tapat na Panginoon, lumalapit po ako nang tapat sa Iyo ngayon: sa pagtatapos ng araw na ito, isinusuko ko ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Linisin Mo po ang aking isipan ng Iyong kapayapaan at ingatan ang aking puso sa aking pagtulog. Nawa ang panalanging ito ay maging higit pa sa mga salita; hayaang salubungin ako ng bukas ng Iyong panibagong awa. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong habag, at punuin ng pag-asa. Amen.",
  "p.236": "Mapagmahal na Tagapagligtas, lumalapit po ako nang tapat sa Iyo ngayon: inilalapit ko po ang aming pagmamahalan, mga pangako, at bawat relasyong nangangailangan ng Iyong haplos. Ibalik Mo po ang lambing sa mga pusong naging matigas dahil sa pagod at stress. Nawa ang panalanging ito ay maging higit pa sa mga salita; turuan Mo kaming makinig, magpatawad, at muling piliin ang isa't isa. Nawa ang Iyong kalooban ang maging kapayapaan ko at ang Iyong presensya ang maging lakas ko. Amen.",
  "p.237": "Makapangyarihang Diyos, lumalapit po ako nang tapat sa Iyo ngayon: ipinagkakatiwala ko ang mga bata at kabataang mahal ko sa Iyong tapat na pangangalaga. Ingatan Mo po ang kanilang mga puso, gabayan ang kanilang mga pasya, at palibutan sila ng mga taong magbibigay ng tamang payo. Nawa ang panalanging ito ay maging higit pa sa mga salita; tulungan Mo silang makilala Ka nang personal at malalim. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.238": "Prinsipe ng Kapayapaan, lumalapit po ako nang tapat sa Iyo ngayon: pagpalain Mo po ang Iyong bayan at panariwain ang aming pagmamahalan sa isa't isa. Gawin Mo po kaming mapagpakumbaba, mapagbigay, matapat, at matapang. Nawa ang panalanging ito ay maging higit pa sa mga salita; nawa ang aming buhay ang magpakita ng ganda ni Hesus sa mundong nakamasid. Gamitin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.239": "Ama ng Awa, lumalapit po ako nang tapat sa Iyo ngayon: parang napakalayo pa ng ilang pangako at tila nanghihina na ang ilang mga pangarap. Hinihiling ko pong bugsuan Mo ng pag-asa ang mga bahagi ng buhay ko na binalot na ng pagkabigo. Nawa ang panalanging ito ay maging higit pa sa mga salita; tulungan Mo akong maniwala na patuloy Ka pang nagsusulat ng magagandang kabanata sa aking buhay. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.240": "Ama sa Langit, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan ipinagkakatiwala ko ang araw na ito sa Iyong mga kamay bago pa man ako matangay ng mga inaasahan ng iba. Dalangin ko po na ayusin Mo ang aking isipan, payapain ang aking damdamin, at akayin ako sa kung ano ang mabuti. Sa Iyong biyaya, nawa’y pananampalataya ang maging unang tugon ko sa halip na takot. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong, at bigyan ako ng tapang na sumunod dito. Amen.",
  "p.241": "Panginoong Hesus, salamat po sa pagdamay sa akin sa gitna ng totoong buhay, kung saan ang isip ko ay puno ng mga alalahaning hindi ko kayang lutasin nang mag-isa. Patahimikin Mo po ang ingay sa loob ko at ipaalala sa akin na ang Iyong presensya ay mas makapangyarihan kaysa sa anumang takot. Sa Iyong biyaya, turuan ang aking pusong huminga sa Iyong kapayapaan. Gawin Mo po akong pagpapala sa mga taong nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.242": "Banal na Espiritu, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan ang daang nasa harap ko ay tila mas mabigat kaysa sa inaasahan ko. Bigyan Mo po ako ng tatag para sa susunod na hakbang ng pananampalataya at tapang para sa mga susunod pa rito. Sa Iyong biyaya, patatagin Mo po ako nang hindi tumitigas ang aking puso. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.243": "Mapagpalang Diyos, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan inilalapit ko sa Iyo ang mga sugat na lihim kong inaalala. Palayain Mo po ako sa pait ng kalooban at turuan akong magpatawad nang may karunungan, katotohanan, at biyaya. Sa Iyong biyaya, pagalingin Mo ang mga hapdi na hindi agad nabura ng pagpapatawad. Nawa ang buhay ko ngayong araw ay maging isang tahimik na handog ng pagsamba. Amen.",
  "p.244": "Maawaing Ama, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan iniaalay ko sa Iyo ang aking pamilya at ang mga taong pinakamalapit sa aking puso. Balutin Mo po ang aming tahanan ng pasensya, katapatan, proteksyon, at pagmamahal. Sa Iyong biyaya, gawin Mong malumanay ang aming mga salita at matatag ang aming pagsasama. Nawa’y samahan ako ng Iyong biyaya sa bawat kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.245": "Tapat na Panginoon, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan iniaalay ko sa Iyo ang gawa ng aking mga kamay at ang bigat sa aking mga balikat. Tulungan Mo po akong maglingkod nang mahusay nang hindi sinasamba ang tagumpay. Sa Iyong biyaya, nawa’y mas mahalaga sa akin ang integridad kaysa sa palakpak ng iba. Turuan Mo akong lumakad nang may hinahon, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.246": "Mapagmahal na Tagapagligtas, salamat po sa pagdamay sa akin sa gitna ng totoong buhay, kung saan inilalapit ko sa Iyo ang aking katawan, isip, at kaluluwang nangangailangan ng panunumbalik. Hipuin Mo po ang bawat sugat, palakasin ang mahihina, at gabayan ng karunungan ang lahat ng nag-aalaga sa akin. Sa Iyong biyaya, hayaang umusbong ang pag-asa bago pa man makita ang kasagutan. Ipinagkakatiwala ko sa Iyo ang mga bagay na nauunawaan ko at maging ang mga hindi ko maintindihan. Amen.",
  "p.247": "Makapangyarihang Diyos, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan hindi lang impormasyon ang kailangan ko kundi ang Iyong banal na karunungan. Ipakita Mo po sa akin kung ano ang dapat piliin, kung ano ang dapat iwasan, at kung kailan dapat maghintay. Sa Iyong biyaya, ilayo Mo ako sa mga desisyong dala lamang ng takot o pagmamataas. Hubugin Mo po ang aking puso hanggang sa masalamin nito ang puso ni Kristo. Amen.",
  "p.248": "Prinsipe ng Kapayapaan, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan humihinto ako upang mapansin ang Iyong mga habag na madalas kong malampasan sa pagmamadali. Buksan Mo po ang aking mga mata sa mga regalong nakatago sa mga ordinaryong sandali. Sa Iyong biyaya, gawin Mong gawi ang pagpapasalamat at hindi lamang ayon sa nararamdaman. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.249": "Ama ng Awa, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay. Dalangin ko ang Iyong pag-iingat sa aking buhay at sa bawat hakbang ko ngayong araw. Bantayan Mo po ako laban sa mga panganib na nakikita at sa mga bitag na nakakubli. Sa Iyong biyaya, dalhin Mo po ako kung saan ako dapat pumunta at pigilan Mo ako sa hindi nararapat. Nawa ang Iyong kalooban ang maging kapayapaan ko at ang Iyong presensya ang maging lakas ko. Amen.",
  "p.250": "Ama sa Langit, salamat po sa pakikipagtagpo sa akin sa gitna ng totoong buhay, kung saan sinusubukan ng mundo na bansagan ako base sa aking mga kabiguan o kakayahan. Ipaalala Mo po sa akin na ako ay Iyo, tinubos ng biyaya at yakap ng Iyong pag-ibig. Sa Iyong biyaya, hayaang mas manaig ang Iyong katotohanan kaysa sa anumang maling husga sa akin. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong, at bigyan ako ng tapang na sumunod dito. Amen.",
  "p.251": "Panginoong Hesus, salamat po sa pagdamay sa akin sa gitna ng totoong buhay, kung saan may lungkot sa aking puso na hindi kayang ipaliwanag ng mga salita. Samahan Mo po ako sa gitna ng hapdi at aliwin ako nang hindi minamadali ang aking paghilom. Sa Iyong biyaya, turuan Mo akong makaalala nang may pagmamahal habang patuloy na namumuhay nang may pag-asa. Gawin Mo po akong pagpapala sa mga taong nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.252": "Banal na Espiritu, salamat po sa pagtatagpo Mo sa akin sa gitna ng totoong buhay, kung saan dama ko ang hila ng mga bagay na nagpapahina sa aking kaluluwa. Hinihiling ko po na bigyan Mo ako ng malinis na puso, ng malinaw na matatakasan mula sa tukso, at ng lakas na piliin ang buhay. Sa Iyong biyaya, gawin Mo pong posible ang pagsunod sa mismong sandaling ito. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko lang. Amen.",
  "p.253": "Mapagpalang Diyos, salamat po sa pagtatagpo Mo sa akin sa gitna ng totoong buhay, kung saan pagod na akong maghintay at natutuksong ipilit ang mga bagay na hindi pa naman dapat. Turuan Mo po akong magtiwala sa Iyong takdang panahon nang hindi nawawalan ng sigla o nagtatanim ng pait sa puso. Sa Iyong biyaya, patubuin po ang isang tahimik na pananampalataya sa gitna ng paghihintay. Nawa ang buhay ko ngayong araw ay maging isang payapang alay ng pagsamba sa Iyo. Amen.",
  "p.254": "Maawaing Ama, salamat po sa pagtatagpo Mo sa akin sa gitna ng totoong buhay, dahil ayaw ko pong dumaan lang sa mundong ito nang tila tulog ang diwa. Ipakita Mo po sa akin ang mabubuting bagay na inihanda Mo para gawin ko ngayong araw. Sa Iyong biyaya, gawin Mo pong mahalaga para sa kawalang-hanggan ang aking maliliit na gawa ng katapatan. Samahan Mo po ako ng Iyong biyaya sa bawat kahinaan at akayin ako sa Iyong kapayapaan. Amen.",
  "p.255": "Tapat na Panginoon, salamat po sa pagtatagpo Mo sa akin sa gitna ng totoong buhay. Sa pagtatapos ng araw na ito, isinusuko ko na po ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Hugasan Mo po ang aking isipan ng Iyong kapayapaan at ingatan ang aking puso habang ako ay natutulog. Sa Iyong biyaya, salubungin po sana ako ng bagong awa bukas. Turuan Mo po akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.256": "Mapagmahal na Tagapagligtas, salamat po sa pagtatagpo Mo sa akin sa gitna ng totoong buhay. Itinataas ko po sa Iyo ang aming pagmamahalan, pangako sa isa't isa, at bawat relasyong nangangailangan ng Iyong haplos. Ibalik Mo po ang lambing sa amin kung saan kami naging matalas dahil sa pagod at stress. Sa Iyong biyaya, turuan Mo kaming makinig, magpatawad, at muling piliin ang isa't isa. Ipinagkakatiwala ko po sa Iyo ang mga bagay na nauunawaan ko at maging ang mga hindi ko maintindihan. Amen.",
  "p.257": "Makapangyarihang Diyos, salamat po sa pagtatagpo Mo sa akin sa gitna ng totoong buhay. Ipinagkakatiwala ko po sa Iyong tapat na kalinga ang mga bata at kabataang mahal ko. Ingatan Mo po ang kanilang mga puso, gabayan ang kanilang mga pasya, at paligiran sila ng mga taong magbibigay ng matalinong payo. Sa Iyong biyaya, tulungan Mo silang makilala Ka nang personal at malalim. Hubugin Mo po ang aking puso hanggang sa ito ay maging repleksyon ng puso ni Kristo. Amen.",
  "p.258": "Prinsipe ng Kapayapaan, salamat po sa pagtatagpo Mo sa akin sa gitna ng totoong buhay. Pagpalain Mo po ang Iyong bayan at panibaguhin ang aming pag-ibig sa isa't isa. Gawin Mo po kaming mapagpakumbaba, mapagbigay, tapat, at matapang. Sa Iyong biyaya, nawa ay makita ang kagandahan ni Hesus sa aming buhay sa harap ng mundo. Iangkla Mo po ako sa Iyong Salita, paligiran ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.259": "Ama ng Awa, salamat po sa pagtatagpo Mo sa akin sa gitna ng totoong buhay, kung saan tila napakalayo pa ng mga pangako at nakakapagod na ang mga pangarap. Ihinga Mo po ang pag-asa sa mga bahagi ng buhay ko na nababalot ng pagkabigo. Sa Iyong biyaya, tulungan Mo akong maniwala na patuloy Ka pang sumusulat ng magagandang kabanata sa aking buhay. Nawa ang Iyong kalooban ang maging kapayapaan ko, at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.260": "Ama sa Langit, isinusuko ko po ang pangangailangang ito sa Iyo: Inilalagak ko po ang araw na ito sa Iyong mga kamay bago pa man ito mapuno ng mga inaasahan ng ibang tao. Manatili Ka po sa piling ko habang inaayos Mo ang aking isipan, pinapanatag ang aking damdamin, at inaakay ako sa mabuti. Nawa ang aking mga iniisip, pasya, at reaksyon ay magpakita na pananampalataya ang una kong tugon sa halip na takot. Hubugin Mo po ang aking puso hanggang sa maging katulad ito ng puso ni Kristo. Amen.",
  "p.261": "Panginoong Hesus, isinusuko ko po sa Iyo ang pangangailangang ito: punung-puno ang isip ko ng mga alalahanin na hindi ko kayang lutasin mag-isa. Samahan Mo po ako sa pagpapatahimik ng ingay sa loob ko at ipaalala sa akin na ang Iyong presensya ay mas malakas kaysa anumang kaba. Nawa ang aking mga iniisip, pasya, at reaksyon ay magturo sa aking puso na huminga sa Iyong kapayapaan. Iangkla Mo po ako sa Iyong Salita, paligiran ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.262": "Banal na Espiritu, isinusuko ko po sa Iyo ang pangangailangang ito: ang landas sa harap ko ay tila mas mabigat kaysa sa inaasahan ko. Manatili Ka po sa tabi ko habang binibigyan Mo ako ng tiyaga para sa susunod na hakbang at lakas ng loob para sa mga susunod pa. Nawa ang aking mga iniisip, pasya, at reaksyon ay magpakita na pinalalakas Mo ako nang hindi pinatitigas ang aking kalooban. Nawa ang Iyong kalooban ang maging kapayapaan ko, at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.263": "Mapagpalang Diyos, isinusuko ko po sa Iyo ang pangangailangang ito: dinadala ko po sa Iyo ang sakit na paulit-ulit kong naaalala nang lihim. Samahan Mo po ako sa paglaya mula sa pait ng kalooban at turuan akong magpatawad nang may karunungan, katotohanan, at biyaya. Nawa ang aking mga iniisip, pasya, at reaksyon ay magpakita na pinagagaling Mo ang mga bahaging hindi agad nabura ng pagpapatawad. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong, at sapat na matapang upang sumunod dito. Amen.",
  "p.264": "Mahabaging Ama, isinusuko ko po sa Iyo ang pangangailangang ito: Itinataas ko sa Iyo ang aking pamilya at ang mga taong pinakamalapit sa aking puso. Samahan Mo po ako habang binabalot Mo ang aming tahanan ng pasensya, katapatan, proteksyon, at pagmamahal. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon ang banayad na pananalita at matibay na ugnayan. Gamitin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.265": "Tapat na Panginoon, isinusuko ko po sa Iyo ang pangangailangang ito: Iniaalay ko sa Iyo ang gawa ng aking mga kamay at ang bigat na pasan ko. Manatili Ka po sa tabi ko at tulungan akong maglingkod nang may kahusayan, nang hindi sinasamba ang tagumpay. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon na mas mahalaga sa akin ang integridad kaysa sa palakpak ng tao. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.266": "Mapagmahal na Tagapagligtas, isinusuko ko po sa Iyo ang pangangailangang ito: Dinadala ko sa Iyo ang aking katawan, isipan, at kaluluwa na nangangailangan ng panunumbalik. Samahan Mo po ako habang hinahawakan Mo ang mga sugat, pinalalakas ang mahihina, at ginagabayan ng karunungan ang lahat ng nag-aalaga sa akin. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon ang pag-asang bumabangon bago pa man makita ang kasagutan. Hayaang ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba. Amen.",
  "p.267": "Makapangyarihang Diyos, isinusuko ko po sa Iyo ang pangangailangang ito: Higit pa sa kaalaman, kailangan ko po ng banal na karunungan. Manatili Ka po sa piling ko habang ipinapakita Mo ang dapat piliin, ang dapat tanggihan, at kung kailan dapat maghintay. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon na inilalayo Mo ako sa mga hakbang na udyok lamang ng takot o pride. Hayaan ang Iyong biyaya na samahan ako sa bawat kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.268": "Prinsipe ng Kapayapaan, isinusuko ko po sa Iyo ang pangangailangang ito: Humihinto ako upang mapansin ang Iyong mga awa na madalas kong malagpasan sa pagmamadali. Samahan Mo po ako at buksan ang aking mga mata sa mga biyayang nakatago sa mga ordinaryong sandali. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon na ang pasasalamat ay naging ugali ko na, at hindi lamang base sa nararamdaman. Turuan Mo po akong lumakad nang may hinahon, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.269": "Ama ng Awa, isinusuko ko po sa Iyo ang pangangailangang ito: Hinihiling ko ang Iyong pagkalinga sa aking buhay at sa bawat hakbang ko ngayong araw. Manatili Ka po sa tabi ko at bantayan ako laban sa mga panganib na nakikita at sa mga bitag na nakatago. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon na Ikaw ang nagpapadala sa akin kung saan ako dapat pumunta at humaharang sa akin kung saan hindi nararapat. Pinagkakatiwalaan Kita sa mga bagay na nauunawaan ko at sa mga bagay na hindi. Amen.",
  "p.270": "Ama sa Langit, isinusuko ko po sa Iyo ang pangangailangang ito: Patuloy akong sinusubukang bansagan ng mundo base sa aking mga pagkakamali, galing, o sakit. Samahan Mo po ako at ipaalalang ako ay Iyo, tinubos ng Iyong biyaya at yakap ng Iyong pag-ibig. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon na ang Iyong katotohanan ay mas matimbang kaysa sa anumang maling label. Hubugin Mo po ang aking puso hanggang sa masalamin nito ang puso ni Kristo. Amen.",
  "p.271": "Panginoong Hesus, isinusuko ko po sa Iyo ang pangangailangang ito: May pighati sa aking loob na hindi kayang ipahayag nang buo ng mga salita. Manatili Ka po sa tabi ko sa gitna ng sakit at alwin ako nang hindi minamadali ang aking paghilom. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon na natututo akong lumingon nang may pagmamahal habang nabubuhay nang may pag-asa. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.272": "Banal na Espiritu, isinusuko ko po sa Iyo ang pangangailangang ito: Nararamdaman ko ang hila ng mga bagay na nagpapahina sa aking kaluluwa. Samahan Mo po ako at bigyan ako ng malinis na puso, malinaw na daan palabas sa tukso, at lakas na piliin ang buhay. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon na posible ang sumunod sa Iyo sa mismong sandaling ito. Maging kapayapaan ko nawa ang Iyong kalooban at maging lakas ko ang Iyong presensya. Amen.",
  "p.273": "Mapagpalang Diyos, isinusuko ko po sa Iyo ang pangangailangang ito: Pagod na po akong maghintay at natutuksong pilitin ang mga bagay na hindi pa handa. Manatili Ka po sa tabi ko at turuan akong magtiwala sa Iyong takdang oras nang hindi nagiging tamad o mapait. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon ang isang tahimik na pananampalataya sa gitna ng paghihintay. Panatilihin Mo po akong sapat na malapit upang marinig ang Iyong bulong at sapat na matapang upang sumunod dito. Amen.",
  "p.274": "Mahabaging Ama, isinusuko ko po sa Iyo ang pangangailangang ito: Ayokong dumaan lang sa buhay na ito nang tila nangangarap nang gising. Samahan Mo po ako habang ipinapakita Mo ang mabubuting bagay na inihanda Mo para gawin ko ngayong araw. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon na ang aking maliliit na gawa ng katapatan ay may halaga sa kawalang-hanggan. Gamitin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.275": "Tapat na Panginoon, isinusuko ko po sa Iyo ang pangangailangang ito: Sa pagtatapos ng araw, binibitawan ko ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Manatili Ka po sa piling ko habang hinuhugasan Mo ang aking isipan ng kapayapaan at iniingatan ang aking puso habang ako’y natutulog. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon na sasalubungin ako ng bukas nang may bagong awa. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.276": "Mapagmahal na Tagapagligtas, isinusuko ko po sa Iyo ang pangangailangang ito: Itinataas ko po sa Iyo ang aming pagmamahalan, ang aming mga pangako, at ang bawat relasyon na nangangailangan ng Iyong haplos. Manatili Ka po sa aking piling habang ibinabalik Mo ang lambing sa aming pagsasama, lalo na’t naging matalas kami sa isa’t isa dahil sa pagod. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon ang Iyong turo na makinig, magpatawad, at muling piliin ang isa’t isa. Hayaan Mo pong ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba sa Iyo. Amen.",
  "p.277": "Makapangyarihang Diyos, isinusuko ko po sa Iyo ang pangangailangang ito: Ipinagkakatiwala ko po sa Iyong tapat na kalinga ang mga bata at kabataang mahal ko. Samahan Mo po ako habang iniingatan Mo ang kanilang mga puso, ginagabayan ang kanilang mga desisyon, at pinalilibutan sila ng mga taong magbibigay ng tamang payo. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon ang mga bagay na makakatulong sa kanilang makilala Ka nang personal at malalim. Hayaan Mo pong ang Iyong biyaya ang sumalubong sa akin sa bawat kahinaan at akayin ako sa Iyong kapayapaan. Amen.",
  "p.278": "Prinsipe ng Kapayapaan, isinusuko ko po sa Iyo ang pangangailangang ito: Pagpalain Mo po ang Iyong bayan at panibaguhin ang aming pagmamahal sa isa’t isa. Samahan Mo po ako habang hinuhubog Mo kaming maging mapagpakumbaba, mapagbigay, matapat, at matapang. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon ang Iyong kabutihan, upang ang aming buhay ay maging salamin ng ganda ni Hesus sa mundong nakamasid. Turuan Mo po akong lumakad nang may hinahon, magmahal nang malalim, at magtiwala nang lubusan. Amen.",
  "p.279": "Ama ng Awa, isinusuko ko po sa Iyo ang pangangailangang ito: May mga pangakong tila napakalayo pa at mga pangarap na tila nakakapagod na. Samahan Mo po ako at hipan ng bagong pag-asa ang mga bahagi ng buhay ko kung saan nananaig ang pagkabigo. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon ang pananalig na patuloy Ka pang sumusulat ng magagandang kabanata sa aking buhay. Ipinagkakatiwala ko po sa Iyo ang mga bagay na nauunawaan ko at pati na ang mga hindi ko maintindihan. Amen.",
  "p.280": "Ama sa Langit, nakikita Mo po ang aking mga pasan at alam Mo kung bakit ito mahalaga: Ipinapaubaya ko po ang araw na ito sa Iyong mga kamay bago pa man ito mabigatan ng mga inaasahan ng ibang tao. Tinatanggap ko po ang Iyong tulong sa pag-aayos ng aking isipan, sa pagpapatatag ng aking damdamin, at sa pag-akay sa akin sa kung ano ang mabuti. Ngayon, hayaan Mong pananampalataya ang maging una kong tugon sa halip na takot. Hayaan Mo pong ang Iyong biyaya ang sumalubong sa akin sa bawat kahinaan at akayin ako sa Iyong kapayapaan. Amen.",
  "p.281": "Panginoong Hesus, nakikita Mo po ang aking mga pasan at alam Mo kung bakit ito mahalaga: Puno ang aking isipan ng mga alalahanin na hindi ko kayang lutasin nang mag-isa. Tinatanggap ko po ang Iyong tulong sa pagpatahimik ng ingay sa loob ko; paalalahanan Mo po ako na ang Iyong presensya ay mas malakas kaysa sa anumang takot. Ngayon, turuan Mo po ang aking puso na huminga sa Iyong kapayapaan. Turuan Mo po akong lumakad nang may hinahon, magmahal nang malalim, at magtiwala nang lubusan. Amen.",
  "p.282": "Banal na Espiritu, nakikita Mo po ang aking mga pasan at alam Mo kung bakit ito mahalaga: Ang landas sa harap ko ay tila mas mabigat kaysa sa inaasahan ko. Tinatanggap ko po ang Iyong tulong sa pagbibigay sa akin ng tatag para sa susunod na hakbang, at lakas ng loob para sa mga susunod pa. Ngayon, gawin Mo po akong malakas nang hindi tumitigas ang aking kalooban. Ipinagkakatiwala ko po sa Iyo ang mga bagay na nauunawaan ko at pati na ang mga hindi ko maintindihan. Amen.",
  "p.283": "Mapagmahal na Diyos, nakikita Mo po ang aking mga pasan at alam Mo kung bakit ito mahalaga: Inilalapit ko po sa Iyo ang sakit na paulit-ulit kong inaalala sa aking sarili. Tinatanggap ko po ang Iyong tulong upang mapalaya ako sa pait ng kalooban, at turuan Mo po akong magpatawad nang may karunungan, katotohanan, at biyaya. Ngayon, pagalingin Mo po ang mga sugat na hindi agad nabubura ng pagpapatawad. Hubugin Mo po ang aking puso hanggang sa ito ay maging katulad ng puso ni Kristo. Amen.",
  "p.284": "Maawaing Ama, nakikita Mo po ang aking mga pasan at alam Mo kung bakit ito mahalaga: Iniaalay ko po sa Iyo ang aking pamilya at ang mga taong pinakamalapit sa aking puso. Tinatanggap ko po ang Iyong tulong sa paglukob sa aming tahanan ng pasensya, katapatan, proteksyon, at pagmamahal. Ngayon, gawin Mo pong malumanay ang aming mga salita at matatag ang aming samahan. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.285": "Tapat na Panginoon, nakikita Mo po ang aking mga pasan at alam Mo kung bakit ito mahalaga: Iniaalay ko po sa Iyo ang gawa ng aking mga kamay at ang bigat sa aking mga balikat. Tinatanggap ko po ang Iyong tulong upang makapaglingkod ako nang may kahusayan nang hindi sinasamba ang tagumpay. Ngayon, nawa’y mas mahalaga sa akin ang integridad kaysa sa palakpak ng tao. Maging kapayapaan ko nawa ang Iyong kalooban at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.286": "Mapagmahal na Tagapagligtas, nakikita Mo po ang aking mga pasan at alam Mo kung bakit ito mahalaga: Inilalapit ko po sa Iyo ang aking katawan, isipan, at kaluluwa na nangangailangan ng panunumbalik. Tinatanggap ko po ang Iyong tulong sa pagpapagaling ng mga sugat, pagpapalakas ng mga bahaging mahina, at paggabay nang may karunungan sa lahat ng nag-aalaga sa akin. Ngayon, hayaang umusbong ang pag-asa bago pa man dumating ang kasagutan. Manatili sana akong malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.287": "Makapangyarihang Diyos, nakikita Mo po ang aking mga pasan at alam Mo kung bakit ito mahalaga: Higit pa sa impormasyon ang kailangan ko; kailangan ko po ng banal na karunungan. Tinatanggap ko po ang Iyong tulong sa pagpapakita sa akin kung ano ang dapat piliin, kung ano ang dapat tanggihan, at kung kailan dapat maghintay. Ngayon, ilayo Mo po ako sa mga desisyong udyok lamang ng takot o pagmamataas. Gawin Mo po akong pagpapala sa mga taong nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.288": "Prinsipe ng Kapayapaan, nakikita Mo ang aking pasan at alam Mo kung bakit ito mahalaga: sandali po akong tumitigil upang pansinin ang Iyong mga habag na madalas kong malampasan sa aking pagmamadali. Tinatanggap ko ang Iyong tulong habang idinidilat Mo ang aking mga mata sa mga biyayang nakatago sa ordinaryong mga sandali. Ngayon, gawin Mo pong isang ugali ang pagpapasalamat, at hindi lang basta nararamdaman. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.289": "Ama ng Awa, nakikita Mo ang aking pasan at alam Mo kung bakit ito mahalaga: hinihiling ko po ang Iyong pagkalinga sa aking buhay at sa bawat hakbang na gagawin ko ngayong araw. Tinatanggap ko ang Iyong tulong habang iniingatan Mo ako sa mga nakikitang panganib at mga lihim na bitag. Ngayon, dalhin Mo po ako kung saan ako dapat pumunta at pigilan Mo ako sa hindi nararapat. Nawa ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba. Amen.",
  "p.290": "Ama sa Langit, nakikita Mo ang aking pasan at alam Mo kung bakit ito mahalaga: patuloy akong sinusubukang bansagan ng mundo ayon sa aking mga kabiguan, kakayahan, o sakit. Tinatanggap ko ang Iyong tulong habang ipinapaalala Mo sa akin na ako ay Iyo, tinubos ng biyaya at yakap ng Iyong pagmamahal. Ngayon, hayaang ang Iyong katotohanan ang mas mangibabaw kaysa sa anumang maling label sa akin. Nawa'y samahan ako ng Iyong biyaya sa bawat kahinaan at akayin ako tungo sa kapayapaan. Amen.",
  "p.291": "Panginoong Hesus, nakikita Mo ang aking pasan at alam Mo kung bakit ito mahalaga: may pait sa aking kalooban na hindi kayang ipaliwanag ng mga salita. Tinatanggap ko ang Iyong tulong habang sinasamahan Mo ako sa aking hapdi at inaaliw ako nang hindi minamadali ang aking paghilom. Ngayon, turuan Mo po akong makaalala nang may pagmamahal habang patuloy na namumuhay nang may pag-asa. Turuan Mo po akong lumakad nang marahan, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.292": "Banal na Espiritu, nakikita Mo ang aking pasan at alam Mo kung bakit ito mahalaga: nararamdaman ko ang hila ng mga bagay na nagpapahina sa aking kaluluwa. Tinatanggap ko ang Iyong tulong habang binibigyan Mo ako ng malinis na puso, ng paraan upang makaiwas, at ng lakas na piliin ang buhay. Ngayon, tulungan Mo po akong makitang posible ang pagsunod sa bawat sandali. Ipinagkakatiwala ko sa Iyo ang mga bagay na nauunawaan ko at maging ang mga hindi ko pa naiintindihan. Amen.",
  "p.293": "Mapagmahal na Diyos, nakikita Mo ang aking pasan at alam Mo kung bakit ito mahalaga: pagod na po akong maghintay at natutuksong ipilit ang mga bagay na hindi pa panahon. Tinatanggap ko ang Iyong tulong habang tinuturuan Mo akong magtiwala sa Iyong takdang oras nang hindi nawawalan ng sigla o nagtatanim ng pait. Ngayon, palaguin Mo po ang isang tahimik na pananampalataya sa gitna ng paghihintay. Hubugin Mo ang aking puso hanggang sa maging katulad ito ng puso ni Kristo. Amen.",
  "p.294": "Maawaing Ama, nakikita Mo ang aking pasan at alam Mo kung bakit ito mahalaga: ayaw ko pong dumaan sa buhay na ito nang tila kalahating tulog. Tinatanggap ko ang Iyong tulong habang ipinapakita Mo sa akin ang mabubuting bagay na inihanda Mo para gawin ko ngayong araw. Ngayon, gawin Mo pong makabuluhan sa harap ng kawalang-hanggan ang aking maliliit na gawa ng katapatan. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.295": "Tapat na Panginoon, nakikita Mo ang aking pasan at alam Mo kung bakit ito mahalaga: sa pagtatapos ng araw na ito, isinusuko ko na ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Tinatanggap ko ang Iyong tulong habang hinuhugasan Mo ang aking isipan ng kapayapaan at iniingatan ang aking puso habang natutulog. Ngayon, nawa'y salubungin ako ng bukas nang may bagong awa. Maging kapayapaan ko nawa ang Iyong kalooban at maging lakas ko ang Iyong presensya. Amen.",
  "p.296": "Mapagmahal na Tagapagligtas, nakikita Mo ang aking pasan at alam Mo kung bakit ito mahalaga: itinataas ko po ang aming pagmamahalan, mga pangako, at bawat relasyong nangangailangan ng Iyong haplos. Tinatanggap ko ang Iyong tulong habang ibinabalik Mo ang lambing sa kung saan kami naging matigas dahil sa stress. Ngayon, turuan Mo po kaming makinig, magpatawad, at piliin muli ang isa't isa. Panatilihin Mo po akong malapit sa Iyo upang marinig ko ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.297": "Makapangyarihang Diyos, nakikita Mo ang aking pasan at alam Mo kung bakit ito mahalaga: ipinagkakatiwala ko po sa Iyong tapat na pangangalaga ang mga bata at kabataang mahal ko. Tinatanggap ko ang Iyong tulong habang iniingatan Mo ang kanilang mga puso, ginagabayan ang kanilang mga desisyon, at pinalilibutan sila ng mga taong magbibigay ng matalinong payo. Ngayon, tulungan Mo po silang makilala Ka nang personal at malalim. Gawin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.298": "Prinsipe ng Kapayapaan, nakikita Mo ang aking pasan at alam Mo kung bakit ito mahalaga: pagpalain Mo po ang Iyong bayan at panibaguhin ang aming pagmamahal sa isa't isa. Tinatanggap ko ang Iyong tulong habang ginagawa Mo kaming mapagpakumbaba, mapagbigay, matapat, at matapang. Ngayon, nawa'y makita ang kagandahan ni Hesus sa aming buhay sa harap ng mundo. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.299": "Ama ng Awa, nakikita Mo ang aking pasan at alam Mo kung bakit ito mahalaga: tila napakalayo pa ng ilang mga pangako at pagod na ang aking mga pangarap. Tinatanggap ko ang Iyong tulong habang hinihingahan Mo ng pag-asa ang mga bahagi ng puso ko na binalot na ng pagkabigo. Ngayon, tulungan Mo po akong maniwala na patuloy Ka pang sumusulat ng magagandang kabanata. Nawa ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba. Amen.",
  "p.300": "Ama sa Langit, ipinagkakatiwala ko po ang araw na ito sa Iyong mga kamay bago pa man ito masapawan ng mga inaasahan ng iba. Ayusin Mo po ang aking pag-iisip, pakalmahin ang aking mga damdamin, at akayin Mo ako sa kung ano ang mabuti. Hayaang ang maging unang tugon ko ay pananampalataya sa halip na takot. Gawin Mo po akong pagpapala sa mga nangangailangan ng Iyong kabaitan ngayon. Amen.",
  "p.301": "Panginoong Hesus, punung-puno po ang isip ko ng mga alalahanin na hindi ko kayang lutasin nang mag-isa. Patahimikin Mo po ang ingay sa loob ko at ipaalala Mo sa akin na ang Iyong presensya ay higit na mas malakas kaysa sa anumang takot. Turuan Mo po ang puso kong huminga sa Iyong kapayapaan. Gawin Mo po sa akin ang mga bagay na hindi ko kayang gawin sa sarili ko. Amen.",
  "p.302": "Banal na Espiritu, tila mas mabigat po ang landas na nasa harap ko kaysa sa aking inaasahan. Bigyan Mo po ako ng lakas para sa susunod na hakbang ng katapatan at tapang para sa mga susunod pa. Gawin Mo po akong matatag ngunit huwag hayaang tumigas ang aking puso. Nawa ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba. Amen.",
  "p.303": "Mapagmahal na Diyos, inilalapit ko po sa Iyo ang sugat na pilit kong binabalik-balikan sa lihim. Palayain Mo po ako sa pait at turuan Mo akong magpatawad nang may karunungan, katotohanan, at biyaya. Hilumin Mo po ang mga sakit na hindi agad mabura ng pagpapatawad. Nawa'y matagpuan ako ng Iyong biyaya sa bawat kong kahinaan at akayin ako tungo sa kapayapaan. Amen.",
  "p.304": "Maawaing Ama, itinataas ko po sa Iyo ang aking pamilya at ang mga taong pinakamalapit sa aking puso. Balutin Mo po ang aming tahanan ng pasensya, katapatan, proteksyon, at pag-ibig. Hayaang maging banayad ang aming mga salita at maging matatag ang aming samahan. Turuan Mo po akong lumakad nang may hinahon, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.305": "Tapat na Panginoon, iniaalay ko po sa Iyo ang gawa ng aking mga kamay at ang bigat na pasan ko. Tulungan Mo po akong maglingkod nang may kahusayan nang hindi nagiging diyos ang tagumpay. Nawa'y mas mahalaga sa akin ang integridad kaysa sa papuri ng tao. Ipinagkakatiwala ko po sa Iyo ang mga bagay na naiintindihan ko at maging ang mga bagay na hindi ko pa nauunawaan. Amen.",
  "p.306": "Mapagmahal na Tagapagligtas, inilalapit ko po sa Iyo ang aking katawan, isipan, at kaluluwa na nangangailangan ng pagpapanumbalik. Hipuin Mo po ang bawat sugat, palakasin ang bawat kahinaan, at gabayan Mo po ng karunungan ang bawat nag-aalaga sa akin. Hayaang umusbong ang pag-asa bago pa man dumating ang kasagutan. Hubugin Mo po ang aking puso hanggang sa ito ay maging katulad ng puso ni Kristo. Amen.",
  "p.307": "Makapangyarihang Diyos, higit pa sa impormasyon, kailangan ko po ng banal na karunungan. Ipakita Mo po sa akin kung ano ang dapat piliin, kung ano ang dapat tanggihan, at kung kailan dapat maghintay. Iligtas Mo po ako sa mga desisyong dala lamang ng takot o pagmamataas. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.308": "Prinsipe ng Kapayapaan, humihinto po ako upang mapansin ang Iyong mga biyaya na madalas kong malagpasan sa aking pagmamadali. Buksan Mo po ang aking mga mata sa mga regalong nakatago sa bawat karaniwang sandali. Hayaang maging ugali ko ang pagpapasalamat at hindi lamang ayon sa nararamdaman. Nawa'y ang Iyong kalooban ang maging kapayapaan ko at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.309": "Ama ng Awa, hinihiling ko po ang Iyong paggabay at proteksyon sa aking buhay at sa bawat hakbang na gagawin ko ngayon. Ingatan Mo po ako sa mga panganib na nakikita at sa mga bitag na nakatago. Ihatid Mo po ako kung saan ako dapat pumunta at pigilan Mo ako kung saan hindi nararapat. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong at magkaroon ng tapang na sumunod dito. Amen.",
  "p.310": "Ama sa Langit, pilit po akong binabansagan ng mundo ayon sa aking mga pagkakamali, kakayahan, o sakit. Ipaalala Mo po sa akin na ako ay Iyo—tinubos ng biyaya at niyayakap ng Iyong pagmamahal. Hayaang ang Iyong katotohanan ang mas mangibabaw kaysa sa anumang maling paratang. Gawin Mo po akong pagpapala sa mga nangangailangan ng Iyong kabaitan ngayon. Amen.",
  "p.311": "Panginoong Hesus, may mga pighati po sa loob ko na hindi kayang ipaliwanag ng mga salita. Samahan Mo po ako sa gitna ng hapdi at aliwin Mo ako nang hindi minamadali ang aking paghilom. Turuan Mo po akong lumingon nang may pagmamahal habang patuloy na namumuhay nang may pag-asa. Gawin Mo po sa akin ang mga bagay na hindi ko kayang gawin sa sarili ko. Amen.",
  "p.312": "Banal na Espiritu, ramdam ko po ang hatak ng mga bagay na nagpapahina sa aking kaluluwa. Bigyan Mo po ako ng malinis na puso, ng paraan upang makaiwas sa tukso, at ng lakas na piliin ang tunay na buhay. Tulungan Mo po akong makasunod sa Iyo sa mismong sandaling ito. Nawa’y maging isang tahimik na alay ng pagsamba ang buong araw ko. Amen.",
  "p.313": "Mapagmahal na Diyos, napapagod na po ako sa paghihintay at natutuksong pilitin ang mga bagay na hindi pa naman dapat. Turuan Mo po akong magtiwala sa Iyong takdang panahon nang walang pait o pag-aalinlangan sa puso. Palaguin Mo po ang aking pananampalataya sa gitna ng paghihintay. Hayaan ang Iyong biyaya na samahan ako sa bawat kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.314": "Maawaing Ama, ayaw ko pong dumaan sa buhay na ito nang tila nangangapa o kalahating gising. Ipakita Mo po sa akin ang mabubuting gawa na inihanda Mo para sa akin ngayong araw. Gawing mahalaga sa Iyong kaharian ang bawat maliit kong hakbang ng katapatan. Turuan Mo po akong lumakad nang may hinahon, magmahal nang malalim, at magtiwala nang lubos sa Iyo. Amen.",
  "p.315": "Tapat na Panginoon, sa pagtatapos ng araw na ito, ipinauubaya ko na sa Iyo ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Hugasan Mo po ng kapayapaan ang aking isipan at ingatan ang aking puso habang ako ay natutulog. Nawa’y salubungin ako ng bukas nang may panibagong awa. Ipinagkakatiwala ko sa Iyo ang lahat—ang mga bagay na nauunawaan ko at maging ang mga hindi ko maintindihan. Amen.",
  "p.316": "Mapagmahal na Tagapagligtas, itinataas ko po sa Iyo ang aming pagmamahalan, ang aming mga pangako, at ang bawat relasyong nangangailangan ng Iyong haplos. Ibalik Mo po ang lambing sa aming mga puso kung saan naging matigas kami dahil sa pagod at stress. Turuan Mo po kaming makinig, magpatawad, at muling piliin ang isa't isa. Hubugin Mo ang aking puso hanggang sa maging repleksyon ito ng puso ni Kristo. Amen.",
  "p.317": "Makapangyarihang Diyos, ipinagkakatiwala ko po sa Iyong tapat na pagkalinga ang mga bata at kabataang mahal ko. Ingatan Mo po ang kanilang mga puso, gabayan ang kanilang mga desisyon, at palibutan sila ng mga taong magbibigay ng matalinong payo. Tulungan Mo po silang makilala Ka nang personal at malalim. Iangkla Mo po ako sa Iyong Salita, balutin ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.318": "Prinsipe ng Kapayapaan, pagpalain Mo po ang Iyong bayan at panibaguhin ang aming pag-ibig sa isa't isa. Gawin Mo po kaming mapagpakumbaba, mapagbigay, tapat, at matapang. Nawa ang aming buhay ay maging salamin ng kagandahan ni Jesus sa mundong nagmamasid. Ang Iyong kalooban nawa ang maging aking kapayapaan, at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.319": "Ama ng Awa, tila napakalayo pa ng ilang pangako at pagod na ang aking mga pangarap. Hipan Mo po ng bagong pag-asa ang mga bahagi ng aking buhay na puno ng pagkabigo. Tulungan Mo po akong maniwala na nagsusulat Ka pa rin ng magagandang kabanata para sa akin. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong, at bigyan ako ng tapang na sumunod sa Iyo. Amen.",
  "p.320": "Ama sa Langit, lumalapit po ako nang tapat sa Iyo ngayon: inilalagay ko ang araw na ito sa Iyong mga kamay bago pa ito mabalot ng mga ekspektasyon ng ibang tao. Pakiayos po ang aking mga iniisip, patatagin ang aking emosyon, at akayin ako sa kung ano ang mabuti. Huwag nawang manatiling salita lamang ang panalanging ito; hayaang ang una kong tugon ay pananampalataya sa halip na takot. Iangkla Mo po ako sa Banal na Kasulatan, balutin ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.321": "Panginoong Hesus, lumalapit po ako nang tapat sa Iyo ngayon: ang isip ko ay punung-puno ng mga alalahanin na hindi ko kayang lutasin nang mag-isa. Pakitahimik po ang ingay sa loob ko at ipaalala sa akin na ang Iyong presensya ay mas malakas kaysa sa anumang kaba. Huwag nawang manatiling salita lamang ang panalanging ito; turuan Mo po ang aking puso na huminga sa Iyong kapayapaan. Ang Iyong kalooban nawa ang maging aking kapayapaan, at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.322": "Banal na Espiritu, lumalapit po ako nang tapat sa Iyo ngayon: ang landas sa harap ko ay tila mas mabigat kaysa sa inaasahan ko. Bigyan Mo po ako ng tatag para sa susunod na hakbang, at tapang para sa mga susunod pa. Huwag nawang manatiling salita lamang ang panalanging ito; gawin Mo po akong matatag nang hindi nagiging matigas ang aking puso. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong, at bigyan ako ng tapang na sumunod sa Iyo. Amen.",
  "p.323": "Mapagmahal na Diyos, lumalapit po ako nang tapat sa Iyo ngayon: dala ko ang sakit na paulit-ulit kong inaalala nang palihim. Palayain Mo po ako sa anumang pait at turuan Mo akong magpatawad nang may karunungan, katotohanan, at biyaya. Huwag nawang manatiling salita lamang ang panalanging ito; pagalingin Mo po ang mga sugat na hindi agad nabubura ng pagpapatawad. Gawin Mo po akong pagpapala sa isang taong nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.324": "Maawaing Ama, lumalapit po ako nang may katapatan sa Iyong harapan ngayon: Itinataas ko po sa Iyo ang aking pamilya at ang mga taong pinakamahalaga sa akin. Balutin Mo po ang aming tahanan ng pasensya, katapatan, proteksyon, at pagmamahal. Nawa’y higit pa sa salita ang panalanging ito; gawin Mo pong malumanay ang aming pangungusap at matatag ang aming samahan. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.325": "Tapat na Panginoon, lumalapit po ako nang may katapatan sa Iyong harapan ngayon: Iniaalay ko po sa Iyo ang gawa ng aking mga kamay at ang bigat na pasan ng aking mga balikat. Tulungan Mo po akong maglingkod nang may kahusayan nang hindi nagiging diyos ang tagumpay. Nawa’y higit pa sa salita ang panalanging ito; mas maging mahalaga sana sa akin ang integridad kaysa sa palakpak ng iba. Hayaan Mong ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba. Amen.",
  "p.326": "Mapagmahal na Tagapagligtas, lumalapit po ako nang may katapatan sa Iyong harapan ngayon: Dinadala ko po sa Iyo ang aking katawan, isipan, at kaluluwa na nangangailangan ng paghilom. Hipuin Mo po ang mga sugat, palakasin ang mahihina, at gabayan ng Iyong karunungan ang bawat nag-aalaga sa akin. Nawa’y higit pa sa salita ang panalanging ito; bumangon sana ang pag-asa bago pa man makita ang kasagutan. Salubungin nawa ng Iyong biyaya ang bawat kong kahinaan at akayin ako tungo sa kapayapaan. Amen.",
  "p.327": "Makapangyarihang Diyos, lumalapit po ako nang may katapatan sa Iyong harapan ngayon: Higit pa sa impormasyon, kailangan ko po ng banal na karunungan. Ipakita Mo po sa akin kung ano ang dapat piliin, kung ano ang dapat iwasan, at kung kailan dapat maghintay. Nawa’y higit pa sa salita ang panalanging ito; ilayo Mo po ako sa mga desisyong dala lamang ng takot o pride. Turuan Mo po akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.328": "Prinsipe ng Kapayapaan, lumalapit po ako nang may katapatan sa Iyong harapan ngayon: Humihinto po ako upang mapansin ang Iyong mga habag na madalas kong malampasan sa aking pagmamadali. Buksan Mo po ang aking mga mata sa mga biyayang nakatago sa mga karaniwang sandali. Nawa’y higit pa sa salita ang panalanging ito; gawin Mo pong isang gawi ang pagpapasalamat, at hindi lang isang damdamin. Ipinagkakatiwala ko po sa Iyo ang mga bagay na nauunawaan ko at maging ang mga hindi. Amen.",
  "p.329": "Ama ng Awa, lumalapit po ako nang may katapatan sa Iyong harapan ngayon: Hinihiling ko po ang Iyong pagkalinga sa aking buhay at sa bawat hakbang na gagawin ko ngayong araw. Ingatan Mo po ako sa mga panganib na nakikita at sa mga bitag na nakatago. Nawa’y higit pa sa salita ang panalanging ito; dalhin Mo po ako sa kung saan ako dapat magpunta at pigilan Mo po ako sa hindi nararapat. Hubugin Mo po ang aking puso hanggang sa masalamin nito ang puso ni Kristo. Amen.",
  "p.330": "Ama sa Langit, lumalapit po ako nang may katapatan sa Iyong harapan ngayon: Pilit akong binibigyan ng mundo ng pagkakakilanlan base sa aking mga kabiguan, kakayahan, o sakit. Ipaalala Mo po sa akin na ako ay sa Iyo, tinubos ng biyaya at yakap ng Iyong pag-ibig. Nawa’y higit pa sa salita ang panalanging ito; maging mas malakas sana ang Iyong katotohanan kaysa sa anumang maling bansag sa akin. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.331": "Panginoong Hesus, lumalapit po ako nang may katapatan sa Iyong harapan ngayon: May lungkot sa loob ko na hindi kayang ipaliwanag ng mga salita. Samahan Mo po ako sa gitna ng hapdi at alwin Mo po ako nang hindi minamadali ang aking paggaling. Nawa’y higit pa sa salita ang panalanging ito; turuan Mo po akong lumingon nang may pagmamahal habang patuloy na nabubuhay nang may pag-asa. Nawa ang Iyong kalooban ang maging kapayapaan ko at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.332": "Banal na Espiritu, lumalapit po ako nang may katapatan sa Iyong harapan ngayon: Nararamdaman ko po ang hila ng mga bagay na nagpapahina sa aking kaluluwa. Bigyan Mo po ako ng malinis na puso, ng paraan upang makaiwas sa tukso, at ng lakas na piliin ang buhay. Nawa’y higit pa sa salita ang panalanging ito; tulungan Mo po akong sumunod sa Iyo sa mismong sandaling ito. Manatili sana akong sapat na malapit upang marinig ang Iyong bulong at sapat na matapang upang sumunod dito. Amen.",
  "p.333": "Mapagpalang Diyos, lumalapit po ako nang may katapatan sa Iyong harapan ngayon: Pagod na po akong maghintay at natutuksong pilitin ang mga bagay na hindi pa panahon. Turuan Mo po akong magtiwala sa Iyong timing nang hindi nagiging tamad o mapait. Nawa’y higit pa sa salita ang panalanging ito; palaguin Mo po ang isang tahimik na pananampalataya sa gitna ng paghihintay. Gamitin Mo po akong pagpapala sa isang taong nangangailangan ng Iyong kabaitan ngayon. Amen.",
  "p.334": "Maawaing Ama, lumalapit po ako nang may katapatan sa Iyong harapan ngayon: Ayokong dumaan lang sa buhay na ito na tila kalahating tulog. Ipakita Mo po sa akin ang mabubuting bagay na inihanda Mo para gawin ko ngayong araw. Nawa’y higit pa sa salita ang panalanging ito; magkaroon sana ng walang hanggang halaga ang aking maliliit na gawa ng katapatan. Gawin Mo po sa akin ang hindi ko kayang gawin sa aking sarili. Amen.",
  "p.335": "Tapat na Panginoon, lumalapit po ako nang may katapatan sa Iyong harapan ngayon: Sa pagtatapos ng araw na ito, isinusuko ko po ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Hugasan Mo po ng kapayapaan ang aking isipan at ingatan ang aking puso habang ako’y natutulog. Nawa’y higit pa sa salita ang panalanging ito; salubungin sana ako ng bukas nang may bagong awa. Hayaan Mong ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba. Amen.",
  "p.336": "Mapagmahal na Tagapagligtas, lumalapit po ako nang may katapatan sa Iyong harapan ngayong araw: iniaalay ko ang aming pagmamahalan, paninindigan, at bawat relasyong nangangailangan ng Iyong haplos. Ibalik Mo po ang lambing sa mga pusong pinatigas ng pagod at stress. Nawa’y higit pa sa mga salita ang panalanging ito; turuan Mo po kaming makinig, magpatawad, at piliing muli ang isa’t isa. Samahan Mo po ako ng Iyong biyaya sa bawat kahinaan at akayin ako tungo sa kapayapaan. Amen.",
  "p.337": "Makapangyarihang Diyos, tapat po akong lumalapit sa Iyo ngayon: ipinagkakatiwala ko sa Iyong mapagpalang kalinga ang mga bata at kabataang mahal ko. Protektahan Mo po ang kanilang mga puso, gabayan ang kanilang mga desisyon, at palibutan sila ng mga taong magbibigay ng tamang payo. Nawa’y higit pa sa mga salita ang panalanging ito; tulungan Mo po silang makilala Ka nang personal at malalim. Turuan Mo po akong lumakad nang dahan-dahan, magmahal nang wagas, at magtiwala nang lubos. Amen.",
  "p.338": "Prinsipe ng Kapayapaan, tapat po akong lumalapit sa Iyong harapan ngayon: pagpalain Mo po ang Iyong bayan at panibaguhin ang aming pag-ibig sa isa’t isa. Gawin Mo po kaming mapagpakumbaba, mapagbigay, tapat, at matapang. Nawa’y maging higit pa sa mga salita ang panalanging ito; hayaang makita ang ganda ni Hesus sa aming buhay sa harap ng mundong nagmamasid. Ipinagkakatiwala ko sa Iyo ang mga bagay na nauunawaan ko at maging ang mga hindi ko pa maintindihan. Amen.",
  "p.339": "Ama ng Awa, tapat po akong lumalapit sa Iyo ngayon: may mga pangakong tila napakalayo at may mga pangarap na tila pagod na. Hiningahan Mo po ng bagong pag-asa ang mga bahagi ng buhay ko kung saan nanahan ang pagkabigo. Nawa’y higit pa sa mga salita ang panalanging ito; tulungan Mo po akong maniwala na nagsusulat Ka pa rin ng magagandang kabanata. Hubugin Mo po ang aking puso hanggang sa masalamin nito ang puso ni Kristo. Amen.",
  "p.340": "Ama sa Langit, salamat po sa pagsalubong sa akin sa gitna ng totoong buhay, kung saan inilalagay ko ang araw na ito sa Iyong mga kamay bago pa man ito mapuno ng mga inaasahan ng ibang tao. Hinihiling ko po na ayusin Mo ang aking isipan, patatagin ang aking damdamin, at akayin ako sa kung ano ang mabuti. Sa Iyong biyaya, nawa’y pananampalataya ang maging una kong tugon sa halip na takot. Turuan Mo po akong lumakad nang dahan-dahan, magmahal nang wagas, at magtiwala nang lubos. Amen.",
  "p.341": "Panginoong Hesus, salamat po sa pagsalubong sa akin sa gitna ng totoong buhay, kung saan ang isip ko ay puno ng mga alalahanin na hindi ko kayang lutasin nang mag-isa. Patahimikin Mo po ang ingay sa loob ko at ipaalala sa akin na ang Iyong presensya ay mas malakas kaysa sa anumang kaba. Sa Iyong biyaya, turuan Mo po ang aking pusong huminga sa Iyong kapayapaan. Ipinagkakatiwala ko sa Iyo ang mga bagay na nauunawaan ko at maging ang mga hindi ko pa maintindihan. Amen.",
  "p.342": "Banal na Espiritu, salamat po sa pagsalubong sa akin sa gitna ng totoong buhay, kung saan ang daang tinatahak ko ay mas mabigat kaysa sa aking inaasahan. Hinihiling ko po na bigyan Mo ako ng tiyaga para sa susunod na hakbang at lakas ng loob para sa mga susunod pa. Sa Iyong biyaya, patatagin Mo po ako nang hindi tumitigas ang aking kalooban. Hubugin Mo po ang aking puso hanggang sa masalamin nito ang puso ni Kristo. Amen.",
  "p.343": "Mapagpalang Diyos, salamat po sa pagsalubong sa akin sa gitna ng totoong buhay, kung saan dinadala ko sa Iyo ang mga sakit na pabalik-balik sa aking isipan. Palayain Mo po ako sa anumang pait at turuan Mo akong magpatawad nang may karunungan, katotohanan, at biyaya. Sa Iyong biyaya, pagalingin Mo po ang mga sugat na hindi agad nabubura ng kapatawaran. Ibaon Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.344": "Maawaing Ama, salamat po sa pagsalubong sa akin sa gitna ng totoong buhay. Iniaalay ko po sa Iyo ang aking pamilya at ang mga taong pinakamalapit sa aking puso. Balutin Mo po ang aming tahanan ng pasensya, katapatan, proteksyon, at pagmamahal. Sa Iyong biyaya, gawin Mong malumanay ang aming mga salita at matatag ang aming samahan. Nawa’y ang Iyong kalooban ang maging kapayapaan ko at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.345": "Tapat na Panginoon, salamat po sa pagsalubong sa akin sa gitna ng totoong buhay, kung saan iniaalay ko sa Iyo ang gawa ng aking mga kamay at ang bigat sa aking mga balikat. Tulungan Mo po akong maglingkod nang mahusay nang hindi sinasamba ang tagumpay. Sa Iyong biyaya, nawa’y mas mahalaga sa akin ang integridad kaysa sa palakpak ng tao. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong, at bigyan Mo ako ng katapangang sumunod dito. Amen.",
  "p.346": "Mapagmahal na Tagapagligtas, salamat po sa pagsalubong sa akin sa gitna ng totoong buhay. Dinadala ko sa Iyo ang aking katawan, isip, at kaluluwa na nangangailangan ng panunumbalik. Haplusin Mo po ang mga sugat, palakasin ang mahihina, at gabayan ng karunungan ang lahat ng nag-aalaga sa akin. Sa Iyong biyaya, hayaang sumibol ang pag-asa bago pa man makita ang kasagutan. Gawin Mo po akong pagpapala sa mga nangangailangan ng Iyong kabaitan ngayon. Amen.",
  "p.347": "Makapangyarihang Diyos, salamat po sa pagsalubong sa akin sa gitna ng totoong buhay. Hindi lamang impormasyon ang kailangan ko kundi banal na karunungan. Ipakita Mo po sa akin kung ano ang dapat piliin, kung ano ang dapat tanggihan, at kung kailan dapat maghintay. Sa Iyong biyaya, ilayo Mo po ako sa mga desisyong dala lamang ng takot o pagmamataas. Gawin Mo po sa loob ko ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.348": "Prinsipe ng Kapayapaan, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan humihinto ako para mapansin ang Iyong mga awa na madalas kong malagpasan sa aking pagmamadali. Buksan Mo po ang aking mga mata sa mga biyayang nakatago sa mga ordinaryong sandali. Sa Iyong biyaya, gawin Mo pong isang gawi ang pagpapasalamat, at hindi lamang base sa aking nararamdaman. Nawa ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba. Amen.",
  "p.349": "Ama ng Awa, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay. Hinihiling ko ang Iyong pag-iingat sa aking buhay at sa bawat hakbang na tatahakin ko ngayong araw. Bantayan Mo po ako laban sa mga panganib na nakikita at sa mga bitag na nakakubli. Sa Iyong biyaya, dalhin Mo po ako sa dapat kong puntahan at pigilan ako sa mga maling landas. Nawa’y samahan ako ng Iyong biyaya sa lahat ng aking kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.350": "Ama sa Langit, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan pilit akong binabansagan ng mundo base sa aking mga pagkakamali, kakayahan, o sakit. Ipaalala Mo po sa akin na ako ay Iyo, tinubos ng biyaya at kayakap ng Iyong pag-ibig. Sa Iyong biyaya, nawa’y mas mangibabaw ang Iyong katotohanan kaysa sa anumang maling bansag sa akin. Turuan Mo po akong lumakad nang marahan, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.351": "Panginoong Hesus, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan may kalungkutan sa aking puso na hindi kayang ipaliwanag ng mga salita. Hiling ko po na samahan Mo ako sa gitna ng hapdi at aliwin ako nang hindi minamadali ang aking paggaling. Sa Iyong biyaya, turuan Mo akong makaalala nang may pagmamahal habang patuloy na namumuhay nang may pag-asa. Ipinagkakatiwala ko po sa Iyo ang mga bagay na nauunawaan ko at maging ang mga hindi ko maintindihan. Amen.",
  "p.352": "Banal na Espiritu, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan nararamdaman ko ang hila ng mga bagay na nagpapahina sa aking kaluluwa. Bigyan Mo po ako ng malinis na puso, ng paraan para makaiwas sa tukso, at ng lakas na piliin ang buhay. Sa Iyong biyaya, tulungan Mo akong makasunod sa Iyo sa mismong sandaling ito. Hubugin Mo po ang aking puso hanggang sa ito ay maging katulad ng puso ni Kristo. Amen.",
  "p.353": "Mapagbiyayang Diyos, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan pagod na akong maghintay at natutuksong ipilit ang mga bagay na hindi pa panahon. Turuan Mo po akong magtiwala sa Iyong takdang oras nang hindi nawawalan ng sigla o nagtatanim ng pait. Sa Iyong biyaya, palaguin Mo ang isang tahimik na pananampalataya sa gitna ng paghihintay. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.354": "Maawaing Ama, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay. Ayaw ko pong mamuhay nang walang direksyon o parang tulog ang diwa. Ipakita Mo po sa akin ang mabubuting bagay na inihanda Mo para gawin ko ngayong araw. Sa Iyong biyaya, nawa’y magkaroon ng halaga sa kawalang-hanggan ang aking maliliit na gawa ng katapatan. Magsilbi nawang kapayapaan ko ang Iyong kalooban, at maging lakas ko ang Iyong presensya. Amen.",
  "p.355": "Tapat na Panginoon, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay. Sa pagtatapos ng araw na ito, isinusuko ko na sa Iyo ang mga bagay na hindi ko na kayang ayusin pa ngayong gabi. Hugasan Mo po ng kapayapaan ang aking isipan at ingatan ang aking puso habang ako’y natutulog. Sa Iyong biyaya, salubungin Mo po ako ng bagong awa bukas ng umaga. Manatili sana akong malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.356": "Mapagmahal na Tagapagligtas, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay. Itinataas ko po sa Iyo ang aming pagmamahalan, mga pangako, at bawat relasyong nangangailangan ng Iyong haplos. Ibalik Mo po ang lambing sa mga aspetong naging matigas dahil sa bigat ng buhay. Sa Iyong biyaya, turuan Mo po kaming makinig, magpatawad, at muling piliin ang isa’t isa. Gamitin Mo po akong pagpapala sa isang taong nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.357": "Makapangyarihang Diyos, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay. Ipinagkakatiwala ko po sa Iyong tapat na kalinga ang mga bata at kabataang minamahal ko. Ingatan Mo po ang kanilang mga puso, gabayan ang kanilang mga desisyon, at palibutan sila ng mga taong magbibigay ng tamang payo. Sa Iyong biyaya, tulungan Mo silang makilala Ka nang personal at malalim. Gawin Mo po sa akin ang mga bagay na hindi ko kayang gawin sa sarili ko. Amen.",
  "p.358": "Prinsipe ng Kapayapaan, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay. Pagpalain Mo po ang Iyong bayan at panibaguhin ang aming pagmamahal sa isa’t isa. Hinihiling ko na kami ay maging mapagpakumbaba, mapagbigay, tapat, at matapang. Sa Iyong biyaya, nawa’y makita ang ganda ni Hesus sa aming buhay ng mundong nagmamasid. Ang buhay ko nawa ngayong araw ay maging isang tahimik na alay ng pagsamba. Amen.",
  "p.359": "Ama ng Awa, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan ang ilang pangako ay tila kaylayo pa at ang ilang pangarap ay tila pagod na. Hinihiling ko na bugsuan Mo ng pag-asa ang mga bahagi ng aking buhay na nababalot ng pagkabigo. Sa Iyong biyaya, tulungan Mo akong maniwala na nagsusulat Ka pa rin ng magagandang kabanata para sa akin. Samahan Mo po ako sa aking kahinaan at akayin sa kapayapaan. Amen.",
  "p.360": "Ama sa Langit, isinusuko ko po sa Iyo ang pangangailangang ito: inilalagay ko ang araw na ito sa Iyong mga kamay bago pa man ito diktahan ng inaasahan ng iba. Manatili Ka po sa aking tabi habang inaayos Mo ang aking pag-iisip, pinakalalma ang aking emosyon, at inaakay ako sa kung ano ang mabuti. Nawa’y makita sa aking mga iniisip, pagpili, at reaksyon na pananampalataya ang una kong tugon sa halip na takot. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.361": "Panginoong Hesus, isinusuko ko po sa Iyo ang pangangailangang ito: puno ang isip ko ng mga alalahanin na hindi ko kayang lutasin nang mag-isa. Samahan Mo po ako at patahimikin ang ingay sa loob ko; ipaalala Mo po sa akin na ang Iyong presensya ay higit na makapangyarihan kaysa anumang takot. Sa lahat ng aking iniisip at ginagawa, turuan Mo ang aking pusong huminga sa Iyong kapayapaan. Nawa’y maging isang tahimik na handog ng pagsamba ang buhay ko ngayong araw. Amen.",
  "p.362": "Banal na Espiritu, isinusuko ko po sa Iyo ang pangangailangang ito: tila mas mabigat ang daang nasa harap ko kaysa sa aking inaasahan. Manatili Ka po sa aking tabi at bigyan ako ng tatag para sa susunod na hakbang, at lakas ng loob para sa mga susunod pa. Sa aking mga iniisip at desisyon, palakasin Mo po ako nang hindi pinapatigas ang aking puso. Nawa’y samahan ako ng Iyong biyaya sa bawat kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.363": "Mapagmahal na Diyos, isinusuko ko po sa Iyo ang pangangailangang ito: inilalapit ko sa Iyo ang mga sakit na lihim kong binabalik-balikan. Samahan Mo po ako habang pinalalaya Mo ako sa pait ng kalooban, at turuan Mo akong magpatawad nang may karunungan, katotohanan, at biyaya. Hilumin Mo po ang mga sugat na hindi agad nabubura ng pagpapatawad. Turuan Mo akong lumakad nang may hinahon, magmahal nang malalim, at magtiwala nang lubusan. Amen.",
  "p.364": "Amang Mahabagin, isinusuko ko po sa Iyo ang pangangailangang ito: itinataas ko sa Iyo ang aking pamilya at ang mga taong pinakamahalaga sa akin. Manatili Ka po sa amin at punuin ang aming tahanan ng pagtitimpi, katapatan, kalinga, at pagmamahal. Nawa’y maging malumanay ang aming mga salita at maging matatag ang aming ugnayan. Pinagkakatiwalaan Kita sa mga bagay na nauunawaan ko at maging sa mga bagay na hindi ko maintindihan. Amen.",
  "p.365": "Tapat na Panginoon, isinusuko ko po sa Iyo ang pangangailangang ito: iniaalay ko sa Iyo ang gawa ng aking mga kamay at ang bigat na pasan-pasan ko. Samahan Mo po ako upang makapaglilingkod ako nang may kahusayan nang hindi ginagawang diyos ang tagumpay. Sa aking mga desisyon at kilos, nawa’y mas mahalaga sa akin ang integridad kaysa sa palakpak ng tao. Hubugin Mo ang aking puso hanggang sa masalamin nito ang puso ni Kristo. Amen.",
  "p.366": "Mapagmahal na Tagapagligtas, isinusuko ko po sa Iyo ang pangangailangang ito: inilalapit ko sa Iyo ang aking katawan, isipan, at kaluluwa na nangangailangan ng panunumbalik. Manatili Ka po sa aking tabi; hipuin Mo ang mga sugat, palakasin ang mahina, at gabayan ng Iyong karunungan ang lahat ng nag-aalaga sa akin. Buhayin Mo ang pag-asa sa akin bago pa man dumating ang kasagutan. Iangkla Mo ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.367": "Makapangyarihang Diyos, isinusuko ko po sa Iyo ang pangangailangang ito: higit pa sa impormasyon, kailangan ko ng banal na karunungan. Samahan Mo po ako at ituro kung ano ang dapat piliin, ano ang dapat iwasan, at kailan dapat maghintay. Iadya Mo po ako sa mga desisyong dala lamang ng takot o pagmamataas. Nawa’y ang Iyong kalooban ang maging aking kapayapaan at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.368": "Prinsipe ng Kapayapaan, isinusuko ko po sa Iyo ang pangangailangang ito: humihinto ako upang pagmasdan ang Iyong mga biyaya na madalas kong makaligtaan sa pagmamadali. Buksan Mo po ang aking mga mata sa mga regalong nakatago sa mga karaniwang sandali. Gawin Mo pong habito ang pasasalamat at hindi lang base sa aking nararamdaman. Panatilihin Mo akong malapit sa Iyo upang marinig ko ang Iyong bulong at magkaroon ng tapang na sumunod dito. Amen.",
  "p.369": "Ama ng Awa, isinusuko ko po sa Iyo ang pangangailangang ito: hinihiling ko ang Iyong kalinga sa aking buhay at sa bawat hakbang ko ngayong araw. Manatili Ka po sa aking tabi at bantayan ako laban sa mga panganib at mga bitag na hindi ko nakikita. Gabayan Mo po ako sa mga lugar na dapat kong puntahan at pigilan ako sa mga hindi nararapat. Gawin Mo po akong pagpapala sa mga taong nangangailangan ng Iyong kabutihan ngayon. Amen.",
  "p.370": "Ama sa Langit, isinusuko ko po sa Iyo ang pangangailangang ito: pilit akong binabansagan ng mundo base sa aking mga pagkakamali, kakayahan, o sakit. Manatili Ka po sa aking tabi at ipaalala na ako ay Iyo—tinubos ng biyaya at yakap ng Iyong pag-ibig. Nawa’y mas mangibabaw ang Iyong katotohanan kaysa sa anumang maling bansag sa akin. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.371": "Panginoong Hesus, isinusuko ko po sa Iyo ang pangangailangang ito: may lungkot sa aking puso na hindi kayang ipaliwanag ng mga salita. Samahan Mo po ako sa aking pighati at alwin ako nang walang pagmamadali sa aking paggaling. Turuan Mo akong makaalala nang may pagmamahal habang patuloy na namumuhay nang may pag-asa. Nawa’y maging isang tahimik na handog ng pagsamba ang buhay ko ngayong araw. Amen.",
  "p.372": "Banal na Espiritu, isinusuko ko po sa Iyo ang pangangailangang ito: Ramdam ko ang hatak ng mga bagay na nagpapahina sa aking kaluluwa. Samahan Mo po ako habang binibigyan Mo ako ng malinis na puso, ng malinaw na matatakasan mula sa tukso, at ng lakas na piliin ang buhay. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon na posible ang pagsunod sa Iyo sa mismong sandaling ito. Samahan po ako ng Iyong biyaya sa bawat kahinaan at akayin ako tungo sa kapayapaan. Amen.",
  "p.373": "Mapagmahal na Diyos, isinusuko ko po sa Iyo ang pangangailangang ito: Pagod na po akong maghintay at natutuksong pilitin ang mga bagay na hindi pa handa. Samahan Mo po ako habang tinuturuan Mo akong magtiwala sa Iyong takdang panahon nang hindi sumusuko o nagtatanim ng pait. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon ang paglago ng isang tahimik na pananampalataya sa gitna ng paghihintay. Turuan Mo po akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.374": "Mahabaging Ama, isinusuko ko po sa Iyo ang pangangailangang ito: Ayaw ko pong lumipas ang buhay na ito na tila kalahating gising lamang. Samahan Mo po ako habang ipinapakita Mo ang kabutihang inihanda Mo para sa akin ngayong araw. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon na ang maliliit kong gawa ng katapatan ay mahalaga para sa kawalang-hanggan. Ipinagkakatiwala ko po sa Iyo ang mga bagay na nauunawaan ko at maging ang mga hindi ko pa naiintindihan. Amen.",
  "p.375": "Tapat na Panginoon, isinusuko ko po sa Iyo ang pangangailangang ito: Sa pagtatapos ng araw na ito, binibitawan ko na ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Samahan Mo po ako habang pinupuno Mo ng kapayapaan ang aking isipan at iniingatan ang aking puso sa aking pagtulog. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon na sasalubungin ako ng bukas nang may bagong awa. Hubugin Mo po ang aking puso hanggang sa ito ay maging katulad ng puso ni Kristo. Amen.",
  "p.376": "Mapagmahal na Tagapagligtas, isinusuko ko po sa Iyo ang pangangailangang ito: Itinataas ko sa Iyo ang pag-ibig, katapatan, at bawat relasyong nangangailangan ng Iyong haplos. Samahan Mo po ako at ibalik ang lambing sa mga pusong pinatigas ng pagod. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon na tinuturuan Mo kaming makinig, magpatawad, at piliin ang isa’t isa muli. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.377": "Makapangyarihang Diyos, isinusuko ko po sa Iyo ang pangangailangang ito: Ipinagkakatiwala ko po sa Iyong tapat na pangangalaga ang mga bata at kabataang mahal ko. Samahan Mo po ako habang iniingatan Mo ang kanilang mga puso, ginagabayan ang kanilang mga desisyon, at pinaliligiran sila ng mga boses na puno ng karunungan. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon na natutulungan silang makilala Ka nang personal at malalim. Maging kapayapaan ko sana ang Iyong kalooban at maging lakas ko ang Iyong presensya. Amen.",
  "p.378": "Prinsipe ng Kapayapaan, isinusuko ko po sa Iyo ang pangangailangang ito: Pagpalain Mo po ang Iyong bayan at muling pasiglahin ang aming pagmamahal sa isa’t isa. Samahan Mo po ako habang ginagawa Mo kaming mapagpakumbaba, mapagbigay, matapat, at matapang. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon na ang aming buhay ay nagpapakita ng kagandahan ni Hesus sa mundo. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.379": "Ama ng Awa, isinusuko ko po sa Iyo ang pangangailangang ito: May mga pangakong tila napakalayo pa at mga pangarap na tila pagod na. Samahan Mo po ako at ihinga ang pag-asa sa mga bahagi ng buhay ko na pinamugaran ng pagkabigo. Nawa’y makita sa aking mga iniisip, desisyon, at reaksyon na naniniwala akong sumusulat Ka pa rin ng magagandang kabanata. Gamitin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.380": "Ama sa Langit, nakikita Mo po ang aking mga pasan at alam Mo kung bakit ito mahalaga: Inilalagay ko po ang araw na ito sa Iyong mga kamay bago pa man ako mabigatan sa inaasahan ng iba. Tinatanggap ko po ang Iyong tulong sa pag-aayos ng aking isipan, pagpapatatag ng aking damdamin, at pag-akay sa akin sa kung ano ang mabuti. Ngayong araw, nawa’y pananampalataya ang una kong maging tugon sa halip na takot. Maging kapayapaan ko sana ang Iyong kalooban at maging lakas ko ang Iyong presensya. Amen.",
  "p.381": "Panginoong Hesus, nakikita Mo po ang aking mga pasan at alam Mo kung bakit ito mahalaga: Puno ang isip ko ng mga alalahaning hindi ko kayang lutasin mag-isa. Tinatanggap ko po ang Iyong tulong habang pinatatahimik Mo ang ingay sa aking loob at ipinapaalalang mas malakas ang Iyong presensya kaysa sa anumang takot. Ngayong araw, turuan Mo ang aking puso na huminga sa Iyong kapayapaan. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.382": "Banal na Espiritu, nakikita Mo po ang aking mga pasan at alam Mo kung bakit ito mahalaga: Ang landas sa harap ko ay tila mas mabigat kaysa sa aking inaasahan. Tinatanggap ko po ang Iyong tulong habang binibigyan Mo ako ng tiyaga para sa susunod na hakbang at lakas ng loob para sa kasunod pa nito. Ngayong araw, gawin Mo po akong matatag nang hindi tumitigas ang aking puso. Gamitin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.383": "Mapagmahal na Diyos, nakikita Mo po ang aking mga pasan at alam Mo kung bakit ito mahalaga: Dinadala ko po sa Iyo ang sakit na paulit-ulit kong inaalala nang palihim. Tinatanggap ko po ang Iyong tulong habang pinalalaya Mo ako mula sa kapaitan at tinuturuang magpatawad nang may karunungan, katotohanan, at biyaya. Ngayong araw, pagalingin Mo po ang mga sugat na hindi agad nabubura ng pagpapatawad. Gawin Mo po sa akin ang hindi ko kayang gawin sa aking sarili. Amen.",
  "p.384": "Maawaing Ama, nakikita Mo ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: Itinataas ko po sa Iyo ang aking pamilya at ang mga taong pinakamalapit sa aking puso. Tinatanggap ko po ang Iyong tulong habang nilulukuban Mo ang aming tahanan ng pagtitimpi, katapatan, kalinga, at pag-ibig. Ngayon, gawin Mo pong banayad ang aming mga salita at patatagin ang aming pagsasamahan. Nawa ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba sa Iyo. Amen.",
  "p.385": "Tapat na Panginoon, nakikita Mo ang aking mga dinadala at alam Mo kung bakit ito mahalaga: Iniaalay ko po sa Iyo ang gawa ng aking mga kamay at ang bigat na nararamdaman ko. Tinatanggap ko po ang Iyong tulong upang makapaglingkod nang may kahusayan nang hindi nagiging diyos ang tagumpay. Ngayon, nawa’y mas pahalagahan ko ang integridad kaysa sa palakpak ng tao. Hayaan Mong ang Iyong biyaya ang pumuno sa aking kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.386": "Mapagmahal na Tagapagligtas, nakikita Mo ang aking pinapasan at alam Mo kung bakit ito mahalaga: Dinadala ko po sa Iyo ang aking katawan, isipan, at kaluluwa na nangangailangan ng panunumbalik. Tinatanggap ko po ang Iyong tulong habang hinahawakan Mo ang mga sugat, pinalalakas ang mahihina, at binibigyan ng karunungan ang bawat nag-aalaga sa akin. Ngayon, nawa’y umusbong ang pag-asa bago pa man maging ganap ang kasagutan. Turuan Mo po akong lumakad nang may hinahon, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.387": "Makapangyarihang Diyos, nakikita Mo ang aking mga pasanin at alam Mo kung bakit ito mahalaga: Higit pa sa impormasyon, banal na karunungan po ang kailangan ko. Tinatanggap ko po ang Iyong tulong habang itinuturo Mo kung ano ang pipiliin, kung ano ang tatanggihan, at kung kailan dapat maghintay. Ngayon, ilayo Mo po ako sa mga desisyong udyok lamang ng takot o pagmamataas. Ipinagkakatiwala ko po sa Iyo ang mga bagay na nauunawaan ko at pati na ang mga hindi ko pa maintindihan. Amen.",
  "p.388": "Prinsipe ng Kapayapaan, nakikita Mo ang aking dinadala at alam Mo kung bakit ito mahalaga: Humihinto po ako upang mapansin ang Iyong mga awa na madalas kong malampasan sa aking pagmamadali. Tinatanggap ko po ang Iyong tulong habang binubuksan Mo ang aking mga mata sa mga regalong nakatago sa mga ordinaryong sandali. Ngayon, gawin Mo pong isang gawi ang pagpapasalamat, at hindi lamang base sa aking nararamdaman. Hubugin Mo po ang aking puso hanggang sa masalamin nito ang puso ni Kristo. Amen.",
  "p.389": "Ama ng Awa, nakikita Mo ang aking pinapasan at alam Mo kung bakit ito mahalaga: Hinihiling ko po ang Iyong pagkalinga sa aking buhay at sa bawat hakbang na gagawin ko ngayong araw. Tinatanggap ko po ang Iyong tulong habang binabantayan Mo ako laban sa mga panganib na nakikita at sa mga bitag na nakakubli. Ngayon, ihatid Mo po ako sa dapat kong puntahan at pigilan Mo ako sa hindi nararapat. Nawa ang Iyong Salita ang maging aking sandigan, balutin Mo ako ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.390": "Ama sa Langit, nakikita Mo ang aking dinadala at alam Mo kung bakit ito mahalaga: pilit akong binabansagan ng mundo base sa aking mga pagkakamali, kakayahan, o sakit. Tinatanggap ko po ang Iyong tulong habang ipinapaalala Mo sa akin na ako ay Iyo, tinubos ng biyaya at kinalinga ng pag-ibig. Ngayon, nawa’y mas mangibabaw ang Iyong katotohanan kaysa sa anumang maling bansag sa akin. Maging kapayapaan ko nawa ang Iyong kalooban at maging lakas ko ang Iyong presensya. Amen.",
  "p.391": "Panginoong Hesus, nakikita Mo ang aking pinapasan at alam Mo kung bakit ito mahalaga: may pait sa aking puso na hindi kayang ipaliwanag ng mga salita. Tinatanggap ko po ang Iyong tulong habang sinasamahan Mo ako sa aking hapdi at inaaliw ako nang hindi minamadali ang aking paghilom. Ngayon, turuan Mo po akong makaalala nang may pagmamahal habang patuloy na namumuhay nang may pag-asa. Panatilihin Mo po akong malapit sa Iyo upang marinig ko ang Iyong bulong at maging matapang sa pagsunod dito. Amen.",
  "p.392": "Banal na Espiritu, nakikita Mo ang aking dinadala at alam Mo kung bakit ito mahalaga: nararamdaman ko ang hila ng mga bagay na nagpapahina sa aking kaluluwa. Tinatanggap ko po ang Iyong tulong habang binibigyan Mo ako ng malinis na puso, malinaw na paraan ng pag-iwas, at lakas na piliin ang buhay. Ngayon, tulungan Mo po akong makita na ang pagsunod ay posible sa bawat sandali. Gawin Mo po akong pagpapala sa mga taong nangangailangan ng Iyong kabaitan ngayong araw. Amen.",
  "p.393": "Mapagpala naming Diyos, nakikita Mo ang aking pinapasan at alam Mo kung bakit ito mahalaga: napapagod na po akong maghintay at natutukso nang pilitin ang mga bagay na hindi pa handa. Tinatanggap ko po ang Iyong tulong habang tinuturuan Mo akong magtiwala sa Iyong takdang oras nang hindi nagiging matampuruhin o walang kibo. Ngayon, palaguin Mo po ang isang tahimik na pananampalataya sa gitna ng pagkaantala. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.394": "Maawaing Ama, nakikita Mo ang aking dinadala at alam Mo kung bakit ito mahalaga: ayaw ko pong dumaan sa buhay na ito nang tila natutulog at walang pakialam. Tinatanggap ko po ang Iyong tulong habang ipinapakita Mo sa akin ang mabubuting gawa na inihanda Mo para sa akin ngayong araw. Ngayon, nawa’y maging mahalaga ang aking maliliit na gawa ng katapatan para sa kawalang-hanggan. Nawa ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba sa Iyo. Amen.",
  "p.395": "Tapat na Panginoon, nakikita Mo ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: sa pagtatapos ng araw na ito, ipinapaubaya ko na po ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Tinatanggap ko po ang Iyong tulong habang hinuhugasan Mo ang aking isipan ng kapayapaan at iniingatan ang aking puso sa aking pagtulog. Ngayon, nawa’y salubungin ako ng bukas nang may bagong awa. Hayaan Mong ang Iyong biyaya ang pumuno sa aking bawat kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.396": "Mapagmahal na Tagapagligtas, nakikita Mo po ang aking mga pasanin at alam Mo kung bakit mahalaga ang mga ito: Iniaalay ko sa Iyo ang aming pagmamahalan, katapatan, at bawat relasyong nangangailangan ng Iyong paghipo. Tinatanggap ko po ang Iyong tulong sa muling pagbabalik ng lambing sa mga pusong pinatigas ng pagod at stress. Ngayon, turuan Mo po kaming makinig, magpatawad, at muling piliin ang isa't isa. Turuan Mo akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.397": "Makapangyarihang Diyos, nakikita Mo po ang aking mga pasanin at alam Mo kung bakit mahalaga ang mga ito: Ipinagkakatiwala ko po sa Iyong tapat na kalinga ang mga bata at kabataang mahal ko. Tinatanggap ko po ang Iyong tulong sa pag-iingat sa kanilang mga puso, paggabay sa kanilang mga pasya, at pagpapaligid sa kanila ng mga taong magbibigay ng tamang payo. Ngayon, tulungan Mo po silang makilala Ka nang personal at malalim. Ipinagkakatiwala ko po sa Iyo ang mga bagay na nauunawaan ko at maging ang mga hindi ko pa maintindihan. Amen.",
  "p.398": "Prinsipe ng Kapayapaan, nakikita Mo po ang aking mga pasanin at alam Mo kung bakit mahalaga ang mga ito: Pagpalain Mo po ang Iyong bayan at panibaguhin ang aming pag-ibig sa isa't isa. Tinatanggap ko po ang Iyong tulong upang kami ay maging mapagpakumbaba, mapagbigay, matapat, at matapang. Ngayon, hayaang ang aming mga buhay ay maging salamin ng kagandahan ni Hesus sa harap ng mundo. Hubugin Mo po ang aking puso hanggang sa maging kawangis nito ang puso ni Kristo. Amen.",
  "p.399": "Ama ng Awa, nakikita Mo po ang aking mga pasanin at alam Mo kung bakit mahalaga ang mga ito: May mga pangakong tila napakalayo pa at mga pangarap na tila pagod na. Tinatanggap ko po ang Iyong tulong habang hinihingahan Mo ng bagong pag-asa ang mga bahagi ng buhay ko na binalot na ng pagkabigo. Ngayon, tulungan Mo akong maniwala na patuloy Ka pa ring sumusulat ng magagandang kabanata para sa akin. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.400": "Ama sa Langit, ipinapaubaya ko po ang araw na ito sa Iyong mga kamay bago pa man ito mabigatan ng mga ekspektasyon ng ibang tao. Iayos Mo po ang aking pag-iisip, patatagin ang aking damdamin, at akayin ako sa landas ng kabutihan. Hayaang ang una kong tugon ay pananampalataya at hindi takot. Ipinagkakatiwala ko po sa Iyo ang mga bagay na nauunawaan ko at maging ang mga hindi ko pa maintindihan. Amen.",
  "p.401": "Panginoong Hesus, puno ang aking isipan ng mga alalahanin na hindi ko kayang lutasin nang mag-isa. Patahimikin Mo po ang ingay sa aking loob at ipaalala sa akin na ang Iyong presensya ay mas malakas kaysa sa anumang takot. Turuan Mo po ang aking puso na huminga sa Iyong kapayapaan. Hubugin Mo po ang aking puso hanggang sa maging kawangis nito ang puso ni Kristo. Amen.",
  "p.402": "Banal na Espiritu, ang daang nasa harap ko ay tila mas mabigat kaysa sa inaasahan ko. Bigyan Mo po ako ng lakas para sa susunod na hakbang at katapangan para sa mga kasunod pa nito. Patatagin Mo po ako nang hindi tumitigas ang aking puso. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.403": "Mapagpalang Diyos, inilalapit ko po sa Iyo ang sugat na lihim kong inuulit-ulit sa aking isipan. Palayain Mo po ako sa pait at turuan akong magpatawad nang may karunungan, katotohanan, at biyaya. Hilumin Mo po ang sakit na hindi agad nabubura ng kapatawaran. Nawa ang Iyong kalooban ang maging aking kapayapaan at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.404": "Maawaing Ama, itinataas ko po sa Iyo ang aking pamilya at ang mga taong pinakamalapit sa aking puso. Balutin Mo po ang aming tahanan ng pasensya, katapatan, proteksyon, at pagmamahal. Turuan Mo kaming maging banayad sa aming mga salita at patatagin ang aming ugnayan. Manatili sana akong sapat na malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.405": "Tapat na Panginoon, iniaalay ko po sa Iyo ang gawa ng aking mga kamay at ang bigat na pasan ng aking mga balikat. Tulungan Mo po akong maglingkod nang may kahusayan nang hindi ginagawang diyos ang tagumpay. Higit na maging mahalaga sa akin ang integridad kaysa sa palakpak ng tao. Gamitin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayon. Amen.",
  "p.406": "Mapagmahal na Tagapagligtas, inilalapit ko po sa Iyo ang aking katawan, isipan, at kaluluwa na nangangailangan ng panunumbalik. Hipuin Mo po ang mga sugat, palakasin ang mahihina, at gabayan ng karunungan ang lahat ng nag-aalaga sa akin. Hayaang sumikat ang pag-asa bago pa man dumating ang kasagutan. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.407": "Makapangyarihang Diyos, hindi lamang impormasyon ang kailangan ko kundi banal na karunungan. Ipakita Mo po sa akin kung ano ang dapat piliin, kung ano ang dapat iwasan, at kung kailan dapat maghintay. Ingatan Mo po ako laban sa mga desisyong udyok lamang ng takot o pride. Hayaang ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba sa Iyo. Amen.",
  "p.408": "Prinsipe ng Kapayapaan, humihinto po ako sandali para mapansin ang Iyong mga habag na madalas kong malampasan sa sobrang pagmamadali. Buksan Mo po ang aking mga mata sa mga biyayang nakatago sa gitna ng mga ordinaryong sandali. Gawin Mo pong habit ang pagpapasalamat, hindi lang base sa aking nararamdaman. Nawa’y samahan ako ng Iyong biyaya sa lahat ng aking kahinaan at akayin ako tungo sa kapayapaan. Amen.",
  "p.409": "Ama ng Awa, hinihiling ko po ang Iyong pagkalinga sa aking buhay at sa bawat hakbang na gagawin ko ngayong araw. Ingatan Mo po ako sa mga panganib na nakikita at sa mga bitag na nakatago. Ihatid Mo po ako sa dapat kong puntahan at pigilan Mo ako sa mga daang hindi para sa akin. Turuan Mo po akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.410": "Ama sa Langit, pilit po akong binabansagan ng mundo base sa aking mga pagkakamali, performance, o mga pasakit. Ipaalala Mo po sa akin na ako ay sa Iyo, tinubos ng biyaya at yakap ng Iyong pagmamahal. Nawa’y mas manaig ang Iyong katotohanan kaysa sa anumang maling label sa akin. Ipinagkakatiwala ko po sa Iyo ang mga bagay na nauunawaan ko at maging ang mga hindi ko maintindihan. Amen.",
  "p.411": "Panginoong Hesus, may mga pighati po sa loob ko na hindi kayang ipaliwanag ng anumang salita. Samahan Mo po ako sa aking sakit at aliwin Mo po ako nang hindi minamadali ang aking paghilom. Turuan Mo po akong lumingon nang may pagmamahal habang patuloy na namumuhay nang may pag-asa. Hubugin Mo po ang aking puso hanggang sa masalamin nito ang puso ni Kristo. Amen.",
  "p.412": "Banal na Espiritu, nararamdaman ko po ang hatak ng mga bagay na nagpapahina sa aking kaluluwa. Bigyan Mo po ako ng malinis na puso, ng malinaw na matatakbuhan palayo sa tukso, at ng lakas na piliin ang buhay. Tulungan Mo po akong sumunod sa Iyo sa mismong sandaling ito. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.413": "Mapagpalang Diyos, napapagod na po ako sa paghihintay at natutuksong ipilit ang mga bagay na hindi pa naman handa. Turuan Mo po akong magtiwala sa Iyong timing nang hindi nagiging pabaya o mapait ang loob. Palaguin Mo po ang aking pananampalataya sa gitna ng paghihintay. Nawa’y ang Iyong kalooban ang maging kapayapaan ko at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.414": "Mahabaging Ama, ayaw ko pong dumaan lang sa buhay na ito nang tila kalahating gising. Ipakita Mo po sa akin ang kabutihang inihanda Mo para gawin ko ngayong araw. Nawa’y magkaroon ng halagang pang-walang hanggan ang maliliit na gawa ko ng katapatan. Manatili sana akong sapat na malapit upang marinig ang Iyong bulong, at maging sapat na matapang upang sumunod dito. Amen.",
  "p.415": "Tapat na Panginoon, sa pagtatapos ng araw na ito, ipinapaubaya ko na ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Hugasan Mo po ng kapayapaan ang aking isipan at ingatan ang aking puso habang ako’y natutulog. Nawa’y salubungin ako ng bagong awa sa pagdating ng bukas. Gawin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayon. Amen.",
  "p.416": "Mapagmahal na Tagapagligtas, itinataas ko po sa Iyo ang aming pagmamahalan, commitment, at bawat relasyong nangangailangan ng Iyong haplos. Ibalik Mo po ang lambing kung saan naging matigas ang aming loob dahil sa stress. Turuan Mo po kaming makinig, magpatawad, at piliin muli ang isa’t isa. Gawin Mo po sa loob ko ang hindi ko kayang gawin sa sarili ko lang. Amen.",
  "p.417": "Makapangyarihang Diyos, ipinagkakatiwala ko po sa Iyong tapat na pangangalaga ang mga bata at kabataang mahal ko. Ingatan Mo po ang kanilang mga puso, gabayan ang kanilang mga desisyon, at palibutan sila ng mga matalinong payo. Tulungan Mo po silang makilala Ikaw nang personal at malalim. Nawa’y ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba sa Iyo. Amen.",
  "p.418": "Prinsipe ng Kapayapaan, pagpalain Mo po ang Iyong bayan at sariwain ang aming pagmamahal sa isa’t isa. Gawin Mo po kaming mapagpakumbaba, mapagbigay, tapat, at matapang. Nawa’y makita ang kagandahan ni Hesus sa aming buhay sa harap ng mundong nagmamasid. Samahan Mo po ako sa aking mga kahinaan at akayin ako tungo sa kapayapaan. Amen.",
  "p.419": "Ama ng Awa, may mga pangako po na tila napakalayo pa at may mga pangarap na tila pagod na. Buhayin Mo po ang pag-asa sa mga bahagi ng aking puso na binalot na ng pagkabigo. Tulungan Mo po akong maniwala na patuloy Ka pang sumusulat ng magagandang kabanata sa aking buhay. Turuan Mo po akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.420": "Ama sa Langit, lumalapit po ako sa Iyong harapan nang may buong katapatan: Ipinagkakatiwala ko ang araw na ito sa Iyong mga kamay bago pa man ito mabahiran ng mga ekspektasyon ng ibang tao. Turuan Mo po ang aking isipan, pakalmahin ang aking damdamin, at akayin ako sa kung ano ang mabuti. Nawa’y higit pa sa salita ang panalanging ito; hayaang ang una kong tugon ay pananampalataya at hindi takot. Hayaan ang aking buhay ngayon ay maging isang tahimik na alay ng pagsamba. Amen.",
  "p.421": "Panginoong Hesus, lumalapit po ako nang may katapatan sa Iyong harapan: Puno ang aking isip ng mga alalahaning hindi ko kayang lutasin nang mag-isa. Patahimikin Mo po ang ingay sa loob ko at ipaalala sa akin na mas makapangyarihan ang Iyong presensya kaysa sa anumang kaba. Nawa’y higit pa sa salita ang panalanging ito; turuan ang aking puso na huminga sa Iyong kapayapaan. Hayaang ang Iyong biyaya ang sumalubong sa akin sa bawat kahinaan at ihatid ako sa kapayapaan. Amen.",
  "p.422": "Banal na Espiritu, lumalapit po ako nang may katapatan sa Iyong harapan: Ang daang tatahakin ko ay tila mas mabigat kaysa sa aking inaasahan. Bigyan Mo po ako ng lakas para sa susunod na hakbang at tapang para sa mga susunod pa. Nawa’y higit pa sa salita ang panalanging ito; patatagin Mo po ako nang hindi tumitigas ang aking puso. Turuan Mo akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.423": "Mapagpalang Diyos, lumalapit po ako nang may katapatan sa Iyong harapan: Dinadala ko sa Iyo ang mga sugat na pilit kong binabalik-balikan nang palihim. Palayain Mo po ako sa pait ng loob at turuan akong magpatawad nang may karunungan, katotohanan, at biyaya. Nawa’y higit pa sa salita ang panalanging ito; pagalingin Mo ang mga bahagi ng puso ko na hindi agad nabubura ng pagpapatawad. Pinagkakatiwalaan Kita sa mga bagay na nauunawaan ko at sa mga bagay na hindi. Amen.",
  "p.424": "Maawaing Ama, lumalapit po ako nang may katapatan sa Iyong harapan: Itinataas ko sa Iyo ang aking pamilya at ang mga taong pinakamalapit sa aking puso. Balutin Mo po ang aming tahanan ng pagtitimpi, katapatan, proteksyon, at pag-ibig. Nawa’y higit pa sa salita ang panalanging ito; gawing malumanay ang aming mga salita at matatag ang aming ugnayan. Hubugin Mo ang aking puso hanggang sa ito ay maging katulad ng puso ni Kristo. Amen.",
  "p.425": "Tapat na Panginoon, lumalapit po ako nang may katapatan sa Iyong harapan: Iniaalay ko sa Iyo ang gawa ng aking mga kamay at ang bigat na pasan ko. Tulungan Mo po akong maglingkod nang may kahusayan nang hindi nagiging diyos ang tagumpay. Nawa’y higit pa sa salita ang panalanging ito; hayaang mas mahalaga sa akin ang integridad kaysa sa palakpak ng tao. Iangkla Mo po ako sa Iyong Salita, balutin ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.426": "Mapagmahal na Tagapagligtas, lumalapit po ako nang may katapatan sa Iyong harapan: Dinadala ko sa Iyo ang aking katawan, isip, at kaluluwa na nangangailangan ng panunumbalik. Hipuin Mo po ang bawat sugat, palakasin ang mahina, at gabayan ng karunungan ang lahat ng nag-aalaga sa akin. Nawa’y higit pa sa salita ang panalanging ito; hayaang umusbong ang pag-asa bago pa man makita ang kasagutan. Maghari nawa ang Iyong kalooban bilang aking kapayapaan at ang Iyong presensya bilang aking lakas. Amen.",
  "p.427": "Makapangyarihang Diyos, lumalapit po ako nang may katapatan sa Iyong harapan: Higit sa impormasyon, kailangan ko po ng Iyong banal na karunungan. Ipakita Mo po sa akin kung ano ang pipiliin, ano ang tatanggihan, at kailan dapat maghintay. Nawa’y higit pa sa salita ang panalanging ito; ilayo Mo po ako sa mga desisyong dala lamang ng takot o yabang. Panatilihin Mo akong malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.428": "Prinsipe ng Kapayapaan, lumalapit po ako nang may katapatan sa Iyong harapan: Humihinto ako upang mapansin ang Iyong mga biyaya na madalas kong malampasan sa aking pagmamadali. Buksan Mo po ang aking mga mata sa mga regalong nakatago sa mga karaniwang sandali. Nawa’y higit pa sa salita ang panalanging ito; gawin Mong natural na gawi ang pagpapasalamat at hindi lamang base sa aking nararamdaman. Gawin Mo po akong pagpapala sa mga taong nangangailangan ng Iyong kabutihan ngayon. Amen.",
  "p.429": "Ama ng Awa, lumalapit po ako nang may katapatan sa Iyong harapan: Hinihiling ko ang Iyong pag-iingat sa aking buhay at sa bawat hakbang na gagawin ko ngayon. Bantayan Mo po ako sa mga panganib na nakikita at sa mga bitag na nakatago. Nawa’y higit pa sa salita ang panalanging ito; akayin Mo ako sa daang dapat kong puntahan at pigilan Mo ako sa hindi nararapat. Gawin Mo sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.430": "Ama sa Langit, lumalapit po ako nang may katapatan sa Iyong harapan: Pilit akong binabansagan ng mundo base sa aking mga kabiguan, kakayahan, o sakit. Ipaalala Mo po sa akin na ako ay sa Iyo, tinubos ng biyaya at yakap ng pag-ibig. Nawa’y higit pa sa salita ang panalanging ito; hayaang mas mangibabaw ang Iyong katotohanan kaysa sa anumang maling label sa akin. Hayaang ang buhay ko ngayon ay maging isang tahimik na alay ng pagsamba. Amen.",
  "p.431": "Panginoong Hesus, lumalapit po ako nang may katapatan sa Iyong harapan: May lungkot sa loob ko na hindi kayang ipaliwanag ng anumang salita. Samahan Mo po ako sa sakit na ito at aliwin ako nang hindi minamadali ang aking paghilom. Nawa’y higit pa sa salita ang panalanging ito; turuan Mo akong makaalala nang may pagmamahal habang namumuhay nang may pag-asa. Hayaang ang Iyong biyaya ang sumalubong sa akin sa bawat kahinaan at ihatid ako sa kapayapaan. Amen.",
  "p.432": "Banal na Espiritu, lumalapit po ako sa Iyo nang may katapatan: damang-dama ko po ang hatak ng mga bagay na nagpapahina sa aking kaluluwa. Bigyan Mo po ako ng pusong dalisay, ng malinaw na landas palabas sa tukso, at ng lakas na piliin ang buhay. Nawa'y ang panalanging ito ay hindi lang maging mga salita; tulungan Mo po akong makitang posibleng sumunod sa Iyo sa mismong sandaling ito. Turuan Mo po akong lumakad nang may hinahon, magmahal nang malalim, at magtiwala nang lubos. Amen.",
  "p.433": "Mapagmahal na Diyos, lumalapit po ako sa Iyo nang may katapatan: pagod na po akong maghintay at natutuksong pilitin ang mga bagay na hindi pa panahon. Turuan Mo po akong magtiwala sa Iyong takdang oras nang hindi nagiging matamlay o nagtatanim ng sama ng loob. Nawa'y ang panalanging ito ay hindi lang maging mga salita; patubuin Mo po ang isang tahimik na pananampalataya sa gitna ng paghihintay. Ipinagkakatiwala ko po sa Iyo ang mga bagay na nauunawaan ko at pati na ang mga hindi. Amen.",
  "p.434": "Mahabaging Ama, lumalapit po ako sa Iyo nang may katapatan: ayaw ko pong dumaan sa buhay na ito nang parang lutang o tulog ang diwa. Ipakita Mo po sa akin ang mabubuting bagay na inihanda Mo para gawin ko ngayong araw. Nawa'y ang panalanging ito ay hindi lang maging mga salita; gawin Mong mahalaga ang maliliit kong hakbang ng katapatan para sa kawalang-hanggan. Hubugin Mo po ang puso ko hanggang sa maging kawangis ito ng puso ni Kristo. Amen.",
  "p.435": "Tapat na Panginoon, lumalapit po ako sa Iyo nang may katapatan: sa pagtatapos ng araw na ito, isinusuko ko na ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Linisin Mo po ang aking isipan ng Iyong kapayapaan at ingatan ang aking puso habang ako’y nahihimbing. Nawa'y ang panalanging ito ay hindi lang maging mga salita; salubungin sana ako ng Iyong bagong awa bukas ng umaga. Iangkla Mo po ako sa Iyong Salita, balutin ng Iyong habag, at punuin ng pag-asa. Amen.",
  "p.436": "Mapagmahal na Tagapagligtas, lumalapit po ako sa Iyo nang may katapatan: itinataas ko po sa Iyo ang pag-ibig, ang aming mga pangako, at ang bawat relasyong nangangailangan ng Iyong haplos. Ibalik Mo po ang lambing sa mga pusong pinatigas ng pagod at stress. Nawa'y ang panalanging ito ay hindi lang maging mga salita; turuan Mo po kaming makinig, magpatawad, at muling piliin ang isa't isa. Ang Iyong kalooban nawa ang maging kapayapaan ko, at ang Iyong presensya ang maging lakas ko. Amen.",
  "p.437": "Makapangyarihang Diyos, lumalapit po ako sa Iyo nang may katapatan: ipinagkakatiwala ko po ang mga bata at kabataang mahal ko sa Iyong tapat na pag-aaruga. Ingatan Mo po ang kanilang mga puso, gabayan ang kanilang mga desisyon, at palibutan sila ng mga taong magtuturo ng tama. Nawa'y ang panalanging ito ay hindi lang maging mga salita; tulungan Mo po silang makilala Ka nang personal at malalim. Panatilihin Mo po akong sapat na malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.438": "Prinsipe ng Kapayapaan, lumalapit po ako sa Iyo nang may katapatan: pagpalain Mo po ang Iyong bayan at panibaguhin ang aming pagmamahal sa isa't isa. Gawin Mo po kaming mapagkumbaba, mapagbigay, tapat, at matapang. Nawa'y ang panalanging ito ay hindi lang maging mga salita; makita sana ang ganda ni Hesus sa aming buhay ng mundong nakamasid. Gamitin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.439": "Ama ng Awa, lumalapit po ako sa Iyo nang may katapatan: may mga pangakong tila napakalayo at mga pangarap na tila pagod na. Ihinga Mo po ang Iyong pag-asa sa mga bahagi ng buhay ko na nababalot ng pagkabigo. Nawa'y ang panalanging ito ay hindi lang maging mga salita; tulungan Mo po akong maniwala na gumagawa Ka pa rin ng magagandang kabanata sa buhay ko. Gawin Mo po sa loob ko ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.440": "Ama sa Langit, salamat po sa pagtatagpo Natin sa gitna ng totoong buhay, kung saan ipinauubaya ko ang araw na ito sa Iyong mga kamay bago pa ito mahawakan ng mga inaasahan ng ibang tao. Hinihiling ko po na ayusin Mo ang aking isipan, patatagin ang aking emosyon, at akayin ako sa kung ano ang mabuti. Sa Iyong biyaya, nawa'y pananampalataya ang una kong maging tugon sa halip na takot. Panatilihin Mo po akong sapat na malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.441": "Panginoong Hesus, salamat po sa pagtatagpo Natin sa gitna ng totoong buhay, kung saan ang isip ko ay punong-puno ng mga alalahaning hindi ko kayang lutasin mag-isa. Patahimikin Mo po ang ingay sa loob ko at ipaalala sa akin na ang Iyong presensya ay mas malakas kaysa sa anumang kaba. Sa Iyong biyaya, turuan Mo po ang aking puso na huminga sa Iyong kapayapaan. Gamitin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.442": "Banal na Espiritu, salamat po sa pagtatagpo Natin sa gitna ng totoong buhay, kung saan ang daang nasa harap ko ay tila mas mabigat kaysa sa inakala ko. Bigyan Mo po ako ng tiyaga para sa susunod na hakbang at lakas ng loob para sa mga darating pa. Sa Iyong biyaya, patatagin Mo po ako nang hindi nagiging matigas ang aking kalooban. Gawin Mo po sa akin ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.443": "Mapagmahal na Diyos, salamat po sa pagtatagpo Natin sa gitna ng totoong buhay, kung saan dinadala ko sa Iyo ang mga hapdi na paulit-ulit kong inaalala nang palihim. Palayain Mo po ako sa pait ng kalooban at turuan akong magpatawad nang may karunungan, katotohanan, at biyaya. Sa Iyong biyaya, hilumin Mo po ang mga sugat na hindi agad nabubura ng pagpapatawad. Nawa ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba. Amen.",
  "p.444": "Maawaing Ama, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan inilalapit ko sa Iyo ang aking pamilya at ang mga taong pinakamamahal ko. Hinihiling ko po na balutin Ninyo ang aming tahanan ng pasensya, katapatan, proteksyon, at pagmamahal. Sa Iyong biyaya, gawin po Ninyong malumanay ang aming pananalita at matatag ang aming samahan. Nawa’y samahan ako ng Iyong biyaya sa lahat ng aking kahinaan at akayin ako tungo sa kapayapaan. Amen.",
  "p.445": "Tapat na Panginoon, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan iniaalay ko sa Iyo ang gawa ng aking mga kamay at ang bigat na aking dinadala. Tulungan Mo po akong maglingkod nang mahusay nang hindi sinasamba ang tagumpay. Sa Iyong biyaya, nawa’y mas pahalagahan ko ang integridad kaysa sa palakpak ng iba. Turuan Mo po akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubusan. Amen.",
  "p.446": "Mapagmahal na Tagapagligtas, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan dinadala ko sa Iyo ang aking katawan, isip, at kaluluwang nangangailangan ng paghilom. Hipuin Mo po ang bawat sugat, palakasin ang mahihina, at gabayan ng Iyong karunungan ang lahat ng nag-aalaga sa amin. Sa Iyong biyaya, pag-alabin po Ninyo ang pag-asa bago pa man dumating ang kasagutan. Ipinagkakatiwala ko po sa Iyo ang lahat—ang mga bagay na nauunawaan ko at pati na ang mga hindi. Amen.",
  "p.447": "Makapangyarihang Diyos, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan higit pa sa impormasyon ang kailangan ko; kailangan ko po ng Iyong banal na karunungan. Ipakita Mo po sa akin kung ano ang dapat piliin, ano ang dapat tanggihan, at kailan dapat maghintay. Sa Iyong biyaya, ilayo Mo po ako sa mga desisyong dala lamang ng takot o pagmamataas. Hubugin Mo po ang aking puso hanggang sa maging kawangis ito ng puso ni Kristo. Amen.",
  "p.448": "Prinsipe ng Kapayapaan, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan ako ay humihinto upang mapansin ang Iyong mga biyaya na madalas kong makaligtaan sa aking pagmamadali. Buksan Mo po ang aking mga mata sa mga regalong nakatago sa mga ordinaryong sandali. Sa Iyong biyaya, gawin Mo pong likas sa akin ang pagpapasalamat sa halip na depende lamang sa aking nararamdaman. Iangkla Mo po ako sa Iyong Salita, palibutan ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.449": "Ama ng Awa, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan hinihiling ko ang Iyong pagkalinga sa aking buhay at sa bawat hakbang ko ngayong araw. Ingatan Mo po ako sa mga panganib na nakikita at sa mga bitag na hindi ko batid. Sa Iyong biyaya, dalhin Mo po ako sa lugar na dapat kong kalagyan at pigilan sa mga daang hindi para sa akin. Nawa’y ang Iyong kalooban ang maging kapayapaan ko at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.450": "Ama sa Langit, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan pilit akong binibigyan ng mundo ng tatak base sa aking mga pagkakamali, kakayahan, o sakit. Ipaalala Mo po sa akin na ako ay Iyo, tinubos ng biyaya at nakayakap sa Iyong pag-ibig. Sa Iyong biyaya, nawa’y mas manaig ang Iyong katotohanan kaysa sa anumang maling bansag sa akin. Panatilihin Mo po akong malapit sa Iyo upang marinig ko ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.451": "Panginoong Hesus, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan may mga lungkot sa aking puso na hindi kayang ipaliwanag ng mga salita. Hinihiling ko po na samahan Mo ako sa aking sakit at aliwin ako nang walang pagmamadali sa aking paghilom. Sa Iyong biyaya, turuan Mo po akong lumingon nang may pagmamahal habang patuloy na namumuhay nang may pag-asa. Gawin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayon. Amen.",
  "p.452": "Banal na Espiritu, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan nararamdaman ko ang hila ng mga bagay na nagpapahina sa aking kaluluwa. Bigyan Mo po ako ng malinis na puso, ng paraan upang makaiwas sa tukso, at ng lakas na piliin ang buhay. Sa Iyong biyaya, tulungan Mo po akong makasunod sa sandaling ito mismo. Gawin Mo po sa loob ko ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.453": "Mapagbiyayang Diyos, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan ako ay pagod na sa paghihintay at natutuksong pilitin ang mga bagay na hindi pa panahon. Turuan Mo po akong magtiwala sa Iyong takdang oras nang hindi nagiging tamad o mapait ang kalooban. Sa Iyong biyaya, palaguin Mo po ang isang tahimik na pananampalataya habang naghihintay. Nawa’y ang buhay ko ngayong araw ay maging isang payapang handog ng pagsamba sa Iyo. Amen.",
  "p.454": "Maawaing Ama, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, dahil ayaw ko pong dumaan sa mundong ito nang hindi lubos na gising ang diwa. Ipakita Mo po sa akin ang mga mabuting gawa na inihanda Ninyo para sa akin ngayong araw. Sa Iyong biyaya, gawin po Ninyong mahalaga ang aking maliliit na gawa ng katapatan para sa Iyong kaharian. Nawa’y samahan ako ng Iyong biyaya sa lahat ng aking kahinaan at akayin ako tungo sa kapayapaan. Amen.",
  "p.455": "Tapat na Panginoon, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay. Sa pagtatapos ng araw na ito, isinusuko ko na sa Iyo ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Hugasan Mo po ang aking isipan ng Iyong kapayapaan at ingatan ang aking puso habang ako ay natutulog. Sa Iyong biyaya, nawa’y salubungin ako ng bukas nang may bagong awa. Turuan Mo po akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubusan. Amen.",
  "p.456": "Mapagmahal na Tagapagligtas, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan inilalapit ko sa Iyo ang aking pagmamahal, paninindigan, at bawat relasyong nangangailangan ng Iyong haplos. Dalangin ko po na ibalik Mo ang lambing sa mga ugnayang naging matigas dahil sa bigat ng buhay. Sa Iyong biyaya, turuan Mo po kaming makinig, magpatawad, at muling piliin ang isa't isa. Ipinagkakatiwala ko po sa Iyo ang lahat—ang mga bagay na nauunawaan ko at maging ang mga hindi. Amen.",
  "p.457": "Makapangyarihang Diyos, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan ipinagkakatiwala ko sa Iyong tapat na pangangalaga ang mga bata at kabataang mahal ko. Ingatan Mo po ang kanilang mga puso, gabayan ang kanilang mga pasya, at palibutan sila ng mga taong magbibigay ng matalinong payo. Sa Iyong biyaya, tulungan Mo po silang makilala Ka nang personal at malalim. Hubugin Mo po ang aking puso hanggang sa masalamin nito ang puso ni Kristo. Amen.",
  "p.458": "Prinsipe ng Kapayapaan, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan pinagpapala Mo ang Iyong bayan at pinapanibago ang aming pagmamahal sa isa't isa. Gawin Mo po kaming mapagpakumbaba, mapagbigay, tapat, at matapang. Sa Iyong biyaya, nawa’y maging salamin ang aming buhay ng kagandahan ni Hesus sa harap ng mundong nagmamasid. Iangkla Mo po ako sa Iyong Salita, balutin ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.459": "Ama ng Awa, salamat po sa pagtagpo sa akin sa gitna ng tunay na buhay, kung saan ang ilang pangako ay tila kaylayo at ang ilang pangarap ay tila pagod na. Hinihiling ko po na hipan Mo ng pag-asa ang mga bahagi ng buhay ko na binalot na ng pagkabigo. Sa Iyong biyaya, tulungan Mo po akong maniwala na nagsusulat Ka pa rin ng magagandang kabanata para sa akin. Nawa’y ang Iyong kalooban ang maging aking kapayapaan at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.460": "Ama sa Langit, isinusuko ko po sa Iyo ang pangangailangang ito: Inilalagay ko ang araw na ito sa Iyong mga kamay bago pa man ito mabigatan ng mga inaasahan ng ibang tao. Samahan Mo po ako sa pag-aayos ng aking mga iniisip, sa pagpapatatag ng aking damdamin, at sa pag-akay sa akin sa kung ano ang mabuti. Nawa’y makita sa aking mga pasya at reaksyon na pananampalataya ang una kong tugon sa halip na takot. Hubugin Mo po ang aking puso hanggang sa masalamin nito ang puso ni Kristo. Amen.",
  "p.461": "Panginoong Hesus, isinusuko ko po sa Iyo ang pangangailangang ito: Puno ang aking isipan ng mga alalahanin na hindi ko kayang lutasin nang mag-isa. Manatili Ka po sa aking tabi upang patahimikin ang ingay sa aking loob at ipaalala sa akin na ang Iyong presensya ay mas malakas kaysa sa anumang kaba. Turuan Mo po ang aking pusong huminga sa Iyong kapayapaan. Iangkla Mo po ako sa Iyong Salita, balutin ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.462": "Banal na Espiritu, isinusuko ko po sa Iyo ang pangangailangang ito: Tila mas mabigat ang landas na nasa harap ko kaysa sa inaasahan ko. Samahan Mo po ako at bigyan ng lakas para sa susunod na hakbang, at tapang para sa mga susunod pa. Sa aking mga iniisip at kilos, gawin Mo po akong matatag ngunit may pusong malambot. Nawa’y ang Iyong kalooban ang maging aking kapayapaan at ang Iyong presensya ang maging aking lakas. Amen.",
  "p.463": "Mapagmahal na Diyos, isinusuko ko po sa Iyo ang pangangailangang ito: Dinadala ko sa Iyo ang sakit na paulit-ulit kong inaalala nang palihim. Samahan Mo po ako habang pinalalaya Mo ako sa pait ng kalooban, at turuan Mo akong magpatawad nang may karunungan, katotohanan, at biyaya. Pagalingin Mo po ang mga sugat na hindi agad nabubura ng pagpapatawad. Manatili sana akong malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.464": "Mahabaging Ama, isinusuko ko po sa Iyo ang pangangailangang ito: Itinataas ko sa Iyo ang aking pamilya at ang mga taong pinakamalapit sa aking puso. Manatili Ka po sa aming piling at punuin ang aming tahanan ng pasensya, katapatan, proteksyon, at pagmamahal. Gawin Mo pong malumanay ang aming mga salita at matibay ang aming ugnayan. Gamitin Mo po akong pagpapala sa sinumang nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.465": "Tapat na Panginoon, isinusuko ko po sa Iyo ang pangangailangang ito: Iniaalay ko sa Iyo ang gawa ng aking mga kamay at ang bigat na pasan ko. Samahan Mo po ako upang makapaglingkod nang may kahusayan nang hindi ginagawang diyos ang tagumpay. Nawa'y mas pahalagahan ko ang integridad kaysa sa papuri ng iba. Gawin Mo po sa loob ko ang hindi ko kayang gawin sa sarili ko lang. Amen.",
  "p.466": "Mapagmahal na Tagapagligtas, isinusuko ko po sa Iyo ang pangangailangang ito: Dinadala ko sa Iyo ang aking katawan, isipan, at kaluluwa na nangangailangan ng pagpapanumbalik. Samahan Mo po ako—haplusin ang mga sugat, palakasin ang mahina, at gabayan ng karunungan ang lahat ng nag-aalaga sa akin. Buhayin Mo po ang pag-asa sa aking puso bago pa man makita ang kasagutan. Nawa’y ang buhay ko ngayong araw ay maging isang tahimik na alay ng pagsamba. Amen.",
  "p.467": "Makapangyarihang Diyos, isinusuko ko po sa Iyo ang pangangailangang ito: Higit pa sa impormasyon, kailangan ko po ng banal na karunungan. Samahan Mo po ako at ituro kung ano ang dapat piliin, ano ang dapat iwasan, at kailan dapat maghintay. Ingatan Mo po ako sa mga desisyong dala lamang ng takot o pagmamataas. Nawa’y samahan ako ng Iyong biyaya sa bawat kahinaan at akayin ako tungo sa kapayapaan. Amen.",
  "p.468": "Prinsipe ng Kapayapaan, isinusuko ko po sa Iyo ang pangangailangang ito: tumitigil po ako sandali upang damhin ang Iyong mga habag na madalas kong nalalampasan sa aking pagmamadali. Samahan Mo po ako habang iminumulat Mo ang aking mga mata sa mga biyayang nakatago sa mga karaniwang sandali. Nawa’y ipakita ng aking mga iniisip, desisyon, at reaksyon na ang pasasalamat ay naging ugali ko na, at hindi lang basta nararamdaman. Turuan Mo po akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubusan. Amen.",
  "p.469": "Ama ng Awa, isinusuko ko po sa Iyo ang pangangailangang ito: dalangin ko po ang Iyong pagkalinga sa aking buhay at sa bawat hakbang ko ngayong araw. Manatili po Ikaw sa aking piling habang iniingatan Mo ako laban sa mga panganib na nakikita at mga bitag na nakatago. Nawa’y ipakita ng aking mga iniisip, desisyon, at reaksyon na Ikaw ang siyang umaakay sa akin kung saan ako dapat pumunta at pumipigil sa akin sa hindi nararapat. Nagtitiwala po ako sa Iyo, sa mga bagay na nauunawaan ko at sa mga hindi ko pa maintindihan. Amen.",
  "p.470": "Ama sa Langit, isinusuko ko po sa Iyo ang pangangailangang ito: patuloy po akong sinusubukang bansagan ng mundo ayon sa aking mga pagkakamali, kakayahan, o sakit. Samahan Mo po ako at ipaalala sa akin na ako ay Iyo—tinubos ng biyaya at yakap ng Iyong pagmamahal. Nawa’y ipakita ng aking mga iniisip, desisyon, at reaksyon na mas matimbang ang Iyong katotohanan kaysa sa anumang maling bansag sa akin. Hubugin Mo po ang aking puso hanggang sa masalamin nito ang puso ni Kristo. Amen.",
  "p.471": "Panginoong Hesus, isinusuko ko po sa Iyo ang pangangailangang ito: may lungkot sa loob ko na hindi kayang ipaliwanag ng mga salita. Samahan Mo po ako sa aking pighati at alwin Mo po ako nang hindi minamadali ang aking paghilom. Nawa’y ipakita ng aking mga iniisip, desisyon, at reaksyon na tinuturuan Mo akong lumingon nang may pagmamahal habang patuloy na namumuhay nang may pag-asa. Iangkla Mo po ako sa Iyong Salita, palibutan ng awa, at punuin ng pag-asa. Amen.",
  "p.472": "Banal na Espiritu, isinusuko ko po sa Iyo ang pangangailangang ito: nararamdaman ko ang hila ng mga bagay na nagpapahina sa aking kaluluwa. Samahan Mo po ako at bigyan ng malinis na puso, malinaw na daan para makaiwas, at lakas upang piliin ang buhay. Nawa’y ipakita ng aking mga iniisip, desisyon, at reaksyon na ginagawa Mong posible ang pagsunod sa mismong sandaling ito. Maging kapayapaan ko sana ang Iyong kalooban, at maging lakas ko ang Iyong presensya. Amen.",
  "p.473": "Mapagbiyayang Diyos, isinusuko ko po sa Iyo ang pangangailangang ito: napapagod na po akong maghintay at natutuksong pilitin ang mga bagay na hindi pa handa. Samahan Mo po ako at turuang magtiwala sa Iyong takdang oras nang hindi nagiging matampuruhin o mapait. Nawa’y ipakita ng aking mga iniisip, desisyon, at reaksyon ang isang tahimik na pananampalataya sa gitna ng paghihintay. Manatili sana akong malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.474": "Mahabaging Ama, isinusuko ko po sa Iyo ang pangangailangang ito: ayaw ko pong dumaan sa buhay na ito nang tila hindi gising ang diwa. Samahan Mo po ako at ipakita ang mabubuting bagay na inihanda Mo para gawin ko ngayong araw. Nawa’y ipakita ng aking mga iniisip, desisyon, at reaksyon na ang aking maliliit na gawa ng katapatan ay may halagang pang-walang hanggan. Gawin Mo po akong pagpapala sa isang taong nangangailangan ng Iyong kabutihan ngayon. Amen.",
  "p.475": "Tapat na Panginoon, isinusuko ko po sa Iyo ang pangangailangang ito: sa pagtatapos ng araw na ito, binibitawan ko na ang mga bagay na hindi ko na kayang ayusin ngayong gabi. Manatili po Ikaw sa aking piling at hugasan ang aking isipan ng Iyong kapayapaan; ingatan Mo po ang aking puso habang ako’y natutulog. Nawa’y ipakita ng aking mga iniisip, desisyon, at reaksyon na ang bukas ay sasalubong sa akin nang may bagong awa. Gawin Mo po sa loob ko ang hindi ko kayang gawin sa sarili ko. Amen.",
  "p.476": "Mapagmahal na Tagapagligtas, isinusuko ko po sa Iyo ang pangangailangang ito: inilalapit ko po ang pagmamahalan, mga pangako, at bawat relasyong nangangailangan ng Iyong haplos. Samahan Mo po kami at ibalik ang lambing sa mga pusong pinatigas ng pagod at stress. Nawa’y ipakita ng aking mga iniisip, desisyon, at reaksyon na tinuturuan Mo kaming makinig, magpatawad, at piliin ang isa’t isa muli. Maging isang tahimik na alay ng pagsamba ang aking buhay ngayong araw. Amen.",
  "p.477": "Makapangyarihang Diyos, isinusuko ko po sa Iyo ang pangangailangang ito: ipinagkakatiwala ko po ang mga bata at kabataang mahal ko sa Iyong tapat na pangangalaga. Samahan Mo po ako sa pag-iingat sa kanilang mga puso, paggabay sa kanilang mga desisyon, at pagpapalibot sa kanila ng mga taong may mabuting payo. Nawa’y ipakita ng aking mga iniisip, desisyon, at reaksyon na tinutulungan Mo silang makilala Ikaw nang malalim at personal. Samahan Mo po ako ng Iyong biyaya sa bawat kahinaan at akayin ako tungo sa kapayapaan. Amen.",
  "p.478": "Prinsipe ng Kapayapaan, isinusuko ko po sa Iyo ang pangangailangang ito: pagpalain Mo po ang Iyong bayan at panibaguhin ang aming pagmamahal sa isa’t isa. Samahan Mo po kami at gawin kaming mapagpakumbaba, mapagbigay, matapat, at matapang. Nawa’y ipakita ng aking mga iniisip, desisyon, at reaksyon na ang aming buhay ay nagpapamalas ng kagandahan ni Hesus sa mundong nakamasid. Turuan Mo po akong lumakad nang dahan-dahan, magmahal nang malalim, at magtiwala nang lubusan. Amen.",
  "p.479": "Ama ng Awa, isinusuko ko po sa Iyo ang pangangailangang ito: may mga pangakong tila napakalayo pa at mga pangarap na tila napapagod na. Samahan Mo po ako at hipan ng pag-asa ang mga bahagi ng buhay ko na nababalot ng pagkabigo. Nawa’y ipakita ng aking mga iniisip, desisyon, at reaksyon na naniniwala akong nagsusulat Ka pa rin ng magagandang kabanata sa aking buhay. Nagtitiwala po ako sa Iyo, sa mga bagay na nauunawaan ko at sa mga hindi ko pa maintindihan. Amen.",
  "p.480": "Ama sa Langit, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: Ipinagkakatiwala ko po ang araw na ito sa Iyong mga kamay bago pa man ako matangay ng mga inaasahan ng iba. Tinatanggap ko po ang Iyong tulong sa pag-aayos ng aking isipan, pagpapatatag ng aking damdamin, at pag-akay sa akin sa kung ano ang mabuti. Ngayon, nawa'y pananampalataya ang una kong tugon sa halip na takot. Salubungin sana ako ng Iyong biyaya sa bawat kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.481": "Panginoong Hesus, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: punung-puno ang aking isip ng mga alalahaning hindi ko kayang lutasin nang mag-isa. Tinatanggap ko po ang Iyong tulong sa pagpatahimik Mo sa ingay sa loob ko, at ipaalala Mo po sa akin na mas makapangyarihan ang Iyong presensya kaysa sa anumang kaba. Ngayon, turuan Mo po ang aking pusong huminga sa Iyong kapayapaan. Turuan Mo po akong lumakad nang may hinahon, magmahal nang malalim, at magtiwala nang buong-buo. Amen.",
  "p.482": "Banal na Espiritu, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: tila mas mabigat ang daang nasa harap ko kaysa sa aking inaasahan. Tinatanggap ko po ang Iyong tulong upang magkaroon ako ng tatag sa bawat hakbang ng pananampalataya at lakas ng loob para sa mga susunod pa. Ngayon, gawin Mo po akong matatag nang hindi tumitigas ang aking puso. Ipinagkakatiwala ko po sa Iyo ang mga bagay na nauunawaan ko at pati na ang mga hindi ko pa maintindihan. Amen.",
  "p.483": "Mapagmahal na Diyos, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: inilalapit ko po sa Iyo ang hapding paulit-ulit kong inaalala nang palihim. Tinatanggap ko po ang Iyong tulong upang mapalaya ako mula sa pait ng kalooban, at turuan Mo po akong magpatawad nang may karunungan, katotohanan, at biyaya. Ngayon, pagalingin Mo po ang mga sugat na hindi agad nabubura ng pagpapatawad. Hubugin Mo po ang aking puso hanggang sa ito ay maging katulad ng puso ni Kristo. Amen.",
  "p.484": "Maawaing Ama, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: itinataas ko po sa Iyo ang aking pamilya at ang mga taong pinakamalapit sa aking puso. Tinatanggap ko po ang Iyong tulong habang binabalot Mo ang aming tahanan ng pasensya, katapatan, proteksyon, at pagmamahal. Ngayon, nawa'y maging malumanay ang aming mga salita at maging matatag ang aming ugnayan. Maging angkla ko po ang Iyong Salita, palibutan Mo po ako ng Iyong awa, at punuin ng pag-asa. Amen.",
  "p.485": "Tapat na Panginoon, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: iniaalay ko po sa Iyo ang gawa ng aking mga kamay at ang bigat sa aking mga balikat. Tinatanggap ko po ang Iyong tulong upang makapaglingkod ako nang mahusay nang hindi sinasamba ang tagumpay. Ngayon, mas pahalagahan ko po sana ang integridad kaysa sa palakpak ng tao. Nawa'y ang Iyong kalooban ang maging kapayapaan ko at ang Iyong presensya ang maging lakas ko. Amen.",
  "p.486": "Mapagmahal na Tagapagligtas, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: inilalapit ko po sa Iyo ang aking katawan, isipan, at kaluluwa na nangangailangan ng panunumbalik. Tinatanggap ko po ang Iyong tulong habang hinahawakan Mo ang mga sugatan, pinapalakas ang mahihina, at ginagabayan ng karunungan ang lahat ng nag-aalaga sa akin. Ngayon, hayaang umusbong ang pag-asa bago pa man makita ang kasagutan. Panatilihin Mo po akong malapit sa Iyo upang marinig ang Iyong bulong at maging matapang na sumunod dito. Amen.",
  "p.487": "Makapangyarihang Diyos, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: hindi lamang impormasyon ang kailangan ko kundi banal na karunungan. Tinatanggap ko po ang Iyong tulong habang ipinapakita Mo sa akin ang dapat piliin, ang dapat tanggihan, at kung kailan dapat maghintay. Ngayon, ilayo Mo po ako sa mga desisyong dala lamang ng takot o pagmamalaki. Gawin Mo po akong pagpapala sa mga taong nangangailangan ng Iyong kabutihan ngayong araw. Amen.",
  "p.488": "Prinsipe ng Kapayapaan, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: tumitigil po ako sandali upang mapansin ang Iyong mga awa na madalas kong malagpasan sa pagmamadali. Tinatanggap ko po ang Iyong tulong habang binubuksan Mo ang aking mga mata sa mga regalong nakatago sa mga karaniwang sandali. Ngayon, gawin Mo pong isang gawi ang pagpapasalamat at hindi lamang isang damdamin. Gawin Mo po sa akin ang hindi ko kayang gawin sa aking sarili. Amen.",
  "p.489": "Ama ng Awa, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: hinihiling ko po ang Iyong pagkalinga sa aking buhay at sa bawat hakbang na gagawin ko ngayong araw. Tinatanggap ko po ang Iyong tulong habang binabantayan Mo ako sa mga panganib na nakikita at sa mga bitag na nakatago. Ngayon, ihatid Mo po ako sa kung saan ako dapat pumunta at pigilan Mo po ako kung saan hindi nararapat. Nawa'y ang buhay ko ngayon ay maging isang tahimik na alay ng pagsamba. Amen.",
  "p.490": "Ama sa Langit, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: pilit akong binibigyan ng mundo ng pagkakakilanlan base sa aking mga kabiguan, kakayahan, o sakit. Tinatanggap ko po ang Iyong tulong habang ipinapaalala Mo sa akin na ako ay sa Iyo—tinubos ng biyaya at yakap ng Iyong pag-ibig. Ngayon, nawa'y ang Iyong katotohanan ang mas mangibabaw kaysa sa anumang maling bansag sa akin. Salubungin sana ako ng Iyong biyaya sa bawat kahinaan at akayin ako sa kapayapaan. Amen.",
  "p.491": "Panginoong Hesus, nakikita Mo po ang aking mga pinapasan at alam Mo kung bakit ito mahalaga: may pait sa aking puso na hindi kayang lubos na ipahayag ng mga salita. Tinatanggap ko po ang Iyong tulong habang sinasamahan Mo ako sa aking hapdi at inaaliw ako nang hindi minamadali ang aking paggaling. Ngayon, turuan Mo po akong makaalala nang may pagmamahal habang patuloy na namumuhay nang may pag-asa. Turuan Mo po akong lumakad nang may hinahon, magmahal nang malalim, at magtiwala nang buong-buo. Amen.",
  "p.492": "Banal na Espiritu, Nakikita Mo ang aking dinadala at alam Mo kung bakit ito mahalaga: Nararamdaman ko ang paghila ng kung ano ang nagpapahina sa aking kaluluwa. Natanggap ko ang Iyong tulong habang binibigyan Mo ako ng malinis na puso, malinaw na pagtakas, at lakas upang piliin ang buhay. Ngayon, gawing posible ang pagsunod sa eksaktong sandaling ito. Pinagkakatiwalaan kita sa kung ano ang naiintindihan ko at kung ano ang hindi ko. Amen.",
  "p.493": "Mapagmahal na Diyos, nakikita Mo ang aking dinadala at alam Mo kung bakit ito mahalaga: Pagod na akong maghintay at natutukso na pilitin ang hindi pa handa. Natatanggap ko ang Iyong tulong habang tinuturuan Mo akong magtiwala sa Iyong panahon nang hindi nagiging pasibo o mapait. Ngayon, lumago ang tahimik na pananampalataya sa pagkaantala. Hulmahin Mo ang puso ko hanggang maging tulad ito ng puso ni Kristo. Amen.",
  "p.494": "Maawaing Ama, Nakikita Mo ang aking dinadala at alam Mo kung bakit ito mahalaga: Ayokong maanod sa buhay na ito na kalahating gising. Natatanggap ko ang Iyong tulong habang ipinapakita Mo sa akin ang kabutihang inihanda Mo para sa akin na gawin ngayon. Ngayon, gawing mahalaga ang aking maliliit na gawain ng katapatan sa walang hanggang mga paraan. Angkla ako sa Banal na Kasulatan, palibutan ako ng awa, at punuin ako ng pag-asa. Amen.",
  "p.495": "Tapat na Panginoon, nakikita Mo ang aking dinadala at alam Mo kung bakit ito mahalaga: sa pagtatapos ng araw na ito, inilalabas ko ang hindi ko kayang ayusin ngayong gabi. Natatanggap ko ang Iyong tulong habang hinuhugasan Mo ang aking isipan nang may kapayapaan at pinapanatiling ligtas ang aking puso habang ako ay natutulog. Ngayon, hayaang bukas ay salubungin ako ng sariwang awa. Nawa'y ang Iyong kalooban ay maging aking kapayapaan at ang Iyong presensya ay maging aking lakas. Amen.",
  "p.496": "Mapagmahal na Tagapagligtas, nakikita Mo ang aking dinadala at alam Mo kung bakit ito mahalaga: Itinataas ko ang pag-ibig, pangako, at bawat relasyon na nangangailangan ng Iyong hawakan. Natatanggap ko ang Iyong tulong habang Iyong ibinabalik ang lambing kung saan naging matalas kami ng stress. Ngayon, turuan kaming makinig, magpatawad, at piliin muli ang isa't isa. Panatilihin akong malapit upang marinig ang Iyong bulong at sapat na lakas ng loob na sundin ito. Amen.",
  "p.497": "Makapangyarihang Diyos, nakikita Mo ang aking dinadala at alam Mo kung bakit ito mahalaga: Inilalagay ko ang mga bata at kabataang minamahal ko sa Iyong tapat na pangangalaga. Natatanggap ko ang Iyong tulong habang pinoprotektahan Mo ang kanilang mga puso, ginagabayan ang kanilang mga pagpili, at pinalibutan sila ng matatalinong tinig. Ngayon, tulungan silang makilala ka nang personal at malalim. Gawin mo akong isang pagpapala sa isang taong nangangailangan ng Iyong kabaitan ngayon. Amen.",
  "p.498": "Prinsipe ng Kapayapaan, Nakikita Mo kung ano ang aking dinadala at alam Mo kung bakit ito mahalaga: pagpalain Mo ang Iyong bayan at i-renew ang aming pagmamahal sa isa't isa. Natatanggap ko ang Iyong tulong habang ginagawa Mo kaming mapagpakumbaba, mapagbigay, makatotohanan, at matapang. Ngayon, hayaan ang ating buhay na gawing maganda si Hesus sa mundong nagmamasid. Gawin mo sa akin ang hindi ko magawa sa sarili ko. Amen.",
  "p.499": "Ama ng Awa, nakikita Mo ang aking dinadala at alam Mo kung bakit ito mahalaga: ang ilang mga pangako ay nararamdaman na malayo at at ang ilang mga pangarap ay pumapagod na. Natatanggap ko ang Iyong tulong habang ikaw ay humihinga ng pag-asa sa mga lugar kung saan naayos ang pagkabigo. Ngayon, tulungan mo akong maniwala na nagsusulat ka pa rin ng magagandang kabanata. Hayaan ang aking buhay ngayon na maging isang tahimik na handog ng pagsamba. Amen.",
  "pd.0": "Hayaang ang Iyong kapayapaan ang maghari sa aking mga isipan at patatagin ang aking puso.",
  "pd.1": "Tulungan akong lumakad nang may pananampalataya ngayon, paisa-isa.",
  "pd.2": "Punan mo ako ng pag-asa na lumalampas sa bawat takot.",
  "pd.3": "Turuan mo akong magtiwala sa Iyo nang higit pa sa aking damdamin.",
  "pd.4": "Panginoon, ang presensya Mo po sana ang maging lakas na masasandalan ko sa buong araw na ito. Sa Iyo po ako huhugot ng tibay sa bawat sandali. Manatili Ka po sa aking piling. Amen.",
  "pd.5": "Panginoon, bigyan Mo po ako ng biyaya para sa sandaling ito at tapang para sa anumang darating. Ikaw po ang magsilbing lakas ko sa bawat hakbang. Amen.",
  "pd.6": "Panginoon, patahimikin Mo po ang anumang tinig ng pagkabalisa sa aking puso. Ipaalala Mo po sa akin na hindi Ka kailanman lumalayo at palagi Kitang kasama. Amen.",
  "pd.7": "Ama, iayon Mo po ang aking pag-iisip, pananalita, at mga gawa sa Iyong banal na kalooban. Nawa’y maging repleksyon ako ng Iyong kabutihan sa lahat ng aking gagawin. Amen.",
  "pd.8": "Panginoon, panibaguhin Mo po ang aking espiritu ngayong umaga. Tulungan Mo po akong maging daluyan ng Iyong pag-ibig at liwanag sa lahat ng aking makakasalamuha. Amen.",
  "pd.9": "Panginoon, yakapin Mo po ako nang mahigpit at gabayan sa landas ng karunungan at kapayapaan. Huwag Mo po akong hayaang mawalay sa Iyong mapagpalang kamay. Amen.",
  "pd.10": "Panginoon, Ikaw po ang maging liwanag na gagabay sa bawat hakbang ko ngayong araw. Tanglawan Mo po ang aking daan upang hindi ako maligaw. Amen.",
  "pd.11": "Panginoon, ipaalala Mo po sa akin na kailanman ay hindi ako naglalakad nang mag-isa. Sa bawat hirap at ginhawa, alam kong Kaagapay Kita. Amen.",
  "pd.12": "Panginoon, itatag Mo po ang aking kaluluwa sa hindi matitinag na katotohanan ng Iyong katapatan. Ikaw ang aking sandigan at matibay na pundasyon habambuhay. Amen.",
  "pd.13": "Panginoon, hayaang umusbong ang Iyong kagalakan sa aking puso, kahit sa gitna ng mga pagsubok. Ikaw po ang nagbibigay sa akin ng dahilan upang ngumiti at magpatuloy. Amen.",
  "pd.14": "Panginoon, gawin Mo po akong kasangkapan ng Iyong biyaya para sa lahat ng makakasalubong ko. Nawa'y madama nila ang Iyong pagmamahal sa pamamagitan ko. Amen.",
  "pd.15": "Panginoon, balutin Mo po ako ng Iyong awa at habag mula paggising hanggang sa aking pagtulog. Manatili nawa ako sa ilalim ng Iyong mapagpalang pagkalinga. Amen.",
  "pd.16": "Panginoon, mas manaig nawa ang Iyong tinig kaysa sa anumang bulong ng takot at pag-aalinlangan sa aking puso. Ikaw po ang magsalita ng katotohanan sa aking buhay ngayon. Amen.",
  "pd.17": "Ama, ipinapaubaya ko po sa Iyo ang lahat ng pasaning hindi ko na kayang dalhin nang mag-isa. Ikaw na po ang bahalang kumarga sa mga mabibigat kong dinadala. Amen.",
  "pd.18": "Panginoon, hayaang dumaloy ang Iyong pag-ibig sa pamamagitan ko nang malaya at walang sukat. Gawin Mo po akong daluyan ng Iyong biyaya sa lahat ng aking makakasalamuha. Amen.",
  "pd.19": "Panginoon, gabayan Mo po ang bawat hakbang ko at ituon ang aking puso sa Iyo. Huwag Mo po akong hayaang maligaw ng landas sa araw na ito. Amen.",
  "pd.20": "Palakasin Mo po ang anumang mahina sa akin at buuin ang bawat bahaging nasira. Hilumin Mo po ang aking puso at panumbalikin ang aking sigla sa Iyong piling. Amen.",
  "pd.21": "Panginoon, Ikaw po ang maging kapayapaan ko sa gitna ng maingay at magulong mundo. Panatilihin Mo po akong tenang at panatag sa Iyong piling. Amen.",
  "pd.22": "Panginoon, tulungan Mo po akong makita ang kagandahan ng araw na ito nang may pasasalamat. Turuan Mo po ang aking mga mata na mamalas ang Iyong mga biyaya sa bawat sandali. Amen.",
  "pd.23": "Yakapin Mo po ako ng Iyong katapatan na parang isang pamilyar at komportableng balabal. Hayaan Mong mabalot ako ng Iyong init at kalinga sa buong maghapon. Amen.",
  "pd.24": "Panginoon, samahan Mo po ako sa tabi ng payapang tubig at panumbalikin ang aking kaluluwa. Ikaw po ang aking tunay na pahinga at kalakasan. Amen.",
  "pd.25": "Itanim Mo po ang Iyong Salita nang malalim sa aking puso, nang higit pa sa kayang yanigin ng anumang bagyo. Nawa'y manatili akong matatag dahil sa Iyong mga janji. Amen.",
  "pd.26": "Panginoon, maging handog nawa ng papuri sa Iyo ang bawat hiningang kukunin ko. Luwalhatiin Ka nawa ng aking buong buhay sa bawat sandali. Amen.",
  "pd.27": "Panginoon, Ikaw po sana ang maging banayad na tinig na hindi ko magagawang balewalain ngayong araw. Turuan Mo po akong makinig at sumunod sa Iyong gabay. Amen.",
  "pd.28": "Panginoon, pagkalooban Mo po ako ng katapangang mula sa langit. Palakasin Mo po ang aking loob upang maharap ko ang anumang hamon nang may buong tiwala sa Iyo. Amen.",
  "pd.29": "Ama, itali Mo po ang puso ko sa Iyo at huwag Mo po akong hayaang maligaw ng landas. Nawa’y manatili akong laging malapit sa Iyong piling. Amen.",
  "p.amen": "Amen.",
};
export default dict;
